quests[26067] = { id = 26067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jin'Zils Segen", description = "Ah, es ist vollbracht! Nun müssen wir ihn ausprobieren.\n\nReist zum größten Konfliktherd im Hochwipfeltal und setzt meinen Voodoostecken bei den Marodeuren von Krom'gar ein, die gegen die Grimmtotem kämpfen. Dank meiner Voodoomagie sollten sie ihre Schlagkraft zurückerhalten und unsere Feinde vernichten!\n\nGeht jetzt, {name}!", sourceObjective = "Benutzt Jin'Zil's Voodoostecken, um 12 Marodeure von Krom'gar mit Voodoo zu erfüllen.", completion = "Endlich ein Sieg! Allerdings wird er ohne eine stabile Nachschublinie nicht von langer Dauer sein. Genießt ihn so lange, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26068] = { id = 26068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wut der Kobolde!", description = "Jetzt kommandieren wir die Koboldarmeen des Steinkrallengebirges! Klingt fast schon beeindruckend. Fast.\n\n<Devo seufzt.>\n\nDas Basislager der Allianz, nördlich von hier, wird streng bewacht. Es ist fast uneinnehmbar. Nur nordöstlich von hier, an der Grabstätte, gibt es einen Eingang. Nehmt das Koboldkriegshorn und brecht zur Grabstätte auf. Betretet sie von Osten, {name}! Von dort aus reist Ihr nach Westen, bis Ihr den Punkt erreicht, den ich auf Eurer Karte markiert habe. Benutzt das Horn und bringt die Wut der Kobolde über die Allianz!", sourceObjective = "Benutzt das Koboldkriegshorn nahe des Banners der Horde an der Grabstätte, um die Koboldarmee loszulassen!", progress = "Auf mein Zeichen! Entfesselt die Koboldhölle!", completion = "<Devo lacht.>\n\nFaszinierende Geschichte, Freund. Unsere neuen Koboldverbündeten scheinen doch ganz nützlich zu sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[26069] = { id = 26069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nura Pfadfinder", description = "Das Südliche Brachland wird von der Allianz angegriffen. Die Tauren bitten um Hilfe. Wir können sie nicht abweisen. Alle gesunden Soldaten der Horde sollten ihnen helfen.\n\nWenn Ihr sie unterstützen wollt, dann nehmt den Weg zum Höhenpfad. Ihr findet ihn im Dorf. Sucht nach Nura Pfadfinder.", sourceObjective = "Meldet Euch bei Nura Pfadfinder auf dem Höhenpfad im Südlichen Brachland.", completion = "Die Lage ist ernst, {race}. Wir brauchen all die Hilfe, die wir kriegen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[26070] = { id = 26070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Läuterung der Entweihten", description = "Unsere Freunde des Irdenen Rings hier haben uns gefragt, ob wir ihnen nicht zur Hand gehen könnten. Wie es scheint treiben im Brühgraben ein paar Gesichtslose ihr Unwesen und verderben alle Wildtiere dort.\n\nKönnt Ihr Euch für mich darum kümmern?", sourceObjective = "Tötet eine beliebige Kombination aus 8 Schmetteraalen, Tiefenschiffshaltern oder Schluchtpirschern.", completion = "Das soll mir reichen. Hier ist Euer Anteil, wie versprochen.\n\nAber werdet nicht selbstgefällig, {name}. Der schwere Teil kommt erst noch.", sourceObjectiveStatus = "unverified-source-field" }
quests[26071] = { id = 26071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Läuterung der Entweihten", description = "Diese Leute vom Irdenen Ring wollen, dass wir das Töten für sie übernehmen. Im Brühgraben treiben einige Gesichtslose ihr Unwesen und verderben alle Wildtiere dort.\n\nSchwimmt mal runter und kümmert Euch darum.", sourceObjective = "Tötet eine beliebige Kombination aus 8 Schmetteraalen, Tiefenschiffshaltern oder Schluchtpirschern.", completion = "Gut gemacht.\n\nAber bildet Euch nicht zu viel darauf ein, {name}. Der schwere Teil kommt erst noch.", sourceObjectiveStatus = "unverified-source-field" }
quests[26072] = { id = 26072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In das Totem", description = "Ihr müsst mein Totem nach unten in den Brühgraben bringen. Benutzt es, um die Energien der Gesichtslosen einzufangen, wenn sie sterben. Das Totem wird sie davon abhalten, dahin zurückzukehren, wo sie herkamen.\n\nWenn das Totem ganz gefüllt ist, bringt es zu mir zurück. Wir werden es verwenden, um ihren Anführer aus der tiefsten Tiefe hervorzulocken.", sourceObjective = "Tötet 5 gesichtslose Entweiher, während sie sich in der Reichweite des Totems der Einsperrung befinden.", completion = "Ja, {race}. Könnt Ihr spüren, wie sie mit aller Macht versuchen auszubrechen und uns zu vernichten?\n\nDas ist gut! Sie sind der perfekte Köder für ihren Anführer.", sourceObjectiveStatus = "unverified-source-field" }
quests[26073] = { id = 26073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Süden nichts Neues", description = "Kehrt jetzt zu Oberanführer Krom'gar zurück, {name}. Teilt ihm unsere Lage mit und berichtet, was Ihr getan habt, um Malaka'jin vor dem Fall zu bewahren.\n\nWir danken Euch für alles, was Ihr getan habt. Vielleicht werdet Ihr eines Tages Eure eigene Region kommandieren.", sourceObjective = "Meldet Euch bei Oberanführer Krom'gar in der Feste Krom'gar im Steinkrallengebirge.", completion = "Lok'tar ogar! Ihr seid die Verkörperung all dessen, was einen Soldaten der Horde ausmacht, {name}. Hätten wir doch nur mehr wie Euch, dann wäre der Krieg bereits vorbei und Kalimdor würde der Horde gehören - UNANGEFOCHTEN!!\n\nErhebt Euch als ein Champion von Krom'gar!", sourceObjectiveStatus = "unverified-source-field" }
quests[26074] = { id = 26074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Anfang vom Ende", description = "Champion, wir haben ein neues Ziel anvisiert. Unsere Späher im Kriegsnarbental melden, dass die Nachtelfen an ihrer eigenen Massenvernichtungswaffe arbeiten und sie in einem uralten Baum verbergen. Sie werden nie die Gelegenheit bekommen, sie gegen uns einzusetzen.\n\nIhr werdet die Bombe zum Auftanken zu den Schlickwerken begleiten und danach zum Klippenläuferposten. Von dort aus werden wir die Bombe zünden und all unsere Feinde vernichten.\n\nGeht jetzt, {name}. Meldet Euch bei Jibbly Rakit, wenn ihr an den Schlickwerken eintrefft.", sourceObjective = "Fahrt im Heißluftballon von Krom'gar zu den Schlickwerken im Steinkrallengebirge.", completion = "Krom'gar hat seinen Champion geschickt! Ihr müsst Euch keine Sorgen machen, Champion. Wir tanken den Ballon rasch wieder auf. Wollt Ihr uns in der Zwischenzeit ein wenig helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[26075] = { id = 26075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Haufen Probleme", description = "Wir haben ein kleines Problem...\n\n<Jibbly zeigt auf die großen Kothaufen, die überall in der Basis liegen.>\n\nWir haben die Schlickwerke in der Nähe eines Wyvernhabitats errichtet. Die Risszeichnungen der Schlickwerke wurden mit großer Sorgfalt erstellt, damit die Wyvernhabitate nicht gestört werden. Anscheinend verehren die Tauren und Orcs die Bestien. Wisst Ihr, was ich verehren würde? Einen Tag ohne Koteinschläge!\n\nGanz im Vertrauen, die Wyvern müssen sterben!", sourceObjective = "Tötet 6 beliebige Prachtschwingenwyvern.", progress = "Bitte helft mir. Die Wachen werden schon etwas aufmüpfig.", completion = "Hoffentlich sind Euch keine entgangen. Ich halte das nicht mehr länger aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[26076] = { id = 26076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spionageplage", description = "Wir haben noch ein Problem, {name}. Es wimmelt hier von Allianzspionen! Ihr habt keine gesehen? Weil sie unsichtbar sind! Getarnt! Ich habe eine Lösung, aber dafür brauche ich jemanden, der die Kraft und das Geschick hat, meinen Plan umzusetzen.\n\nBenutzt diese Gasbombe, dann werdet Ihr die getarnten Spione sehen können. Schickt sie zu ihrem Schöpfer, wenn Ihr sie enttarnt habt.\n\nIhr erkennt einen getarnten Spion an dem Effekt, den sie auf die Luft haben. Seht genau hin!", sourceObjective = "Tötet 8 Allianzspione. Enttarnt die Spione mit Jibblys Gasbombe!", progress = "Habt Ihr die Spionageplage gestoppt?", completion = "Alle dachten, ich spinne. Aber ich wusste, dass es hier überall Spione gibt. Und Kacke.", sourceObjectiveStatus = "unverified-source-field" }
quests[26077] = { id = 26077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Letzte Lieferung", description = "Oberanführer Krom'gar hat einen Befehl aus der Basis übermittelt. Fahrt mit dem Heißluftballon von Krom'gar zum Klippenläuferposten. Der Plan sieht vor, von dort aus mit der Bombe die Allianz im Kriegsnarbental zu vernichten.\n\nMacht Euch auf, {name}. Man sollte Krom'gar nicht warten lassen.\n\nSprecht mit General Grebo, wenn Ihr Euer Ziel erreicht habt. Er wird Euch über Eure nächste Mission informieren.", sourceObjective = "Fahrt mit dem Heißluftballon von Krom'gar zum Klippenläuferposten im Steinkrallengebirge.", completion = "Häuptling Klippenläufer und seine Tauren wollen die Horde verraten! Sie behaupten, dass der uralte Baum im Kriegsnarbental nur eine Druidenschule ist. Sie verstehen nicht, dass Kriegszeiten verzweifelte Maßnahmen verlangen. Meine Späher haben mir versichert, dass die Nachtelfen eine äußerst mächtige Waffe in diesem Baum verbergen. Wir müssen damit aufräumen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26078] = { id = 26078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Löscht die Feuer", description = "Der Angriff der Dunkeleisenzwerge hat uns überrascht. Ihre Saboteure haben viele unserer Flugzeuge, Dampfpanzer und Vorräte beschädigt. Wir konnten nur noch ein paar Bomber rechtzeitig starten.\n\nJeder Techniker, jeder Rekrut und jede Wache, die ich entbehren kann, versucht verzweifelt, die anderen zu reparieren und startklar zu machen. Unsere Infanterie kann nicht mehr lange ausharren. Nehmt diese Ausrüstung und helft bei der Löschung der brennenden Bomber.", sourceObjective = "Löscht 6 Feuer auf dem Flugplatz von Eisenschmiede mit Eurer Feuerwehrausrüstung.", completion = "Gut gemacht! Meine Männer arbeiten hart daran, unsere Flugmaschinen und die Dampfpanzer kampfbereit zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26079] = { id = 26079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Falkenstein und Otto", description = "Die Miliz von Stromgarde hat Kopfgelder auf Lord Falkenstein und seine Leibwache Otto ausgesetzt. Falkenstein ist für die Bemühungen des Syndikats im Arathihochland verantwortlich und sein Tod wäre eine erhebliche Störung dieser Bemühungen.\n\nSeine Leibwache Otto ist zwar kein strategisch wichtiges Ziel, aber er ist ein starker Gegner und hat Dutzende unserer Verteidiger auf dem Gewissen.\n\nIhre Kopfgelder können bei Hauptmann Nials abgeholt werden.", sourceObjective = "Bringt Ottos und Falkensteins Köpfe zu Hauptmann Nials bei der Zuflucht.", progress = "Hallo. Kommt Ihr, um Bericht zu erstatten?", completion = "Falkenstein und Otto? Wunderbar!\n\nHier ist Eure Belohnung, {name}. Ich freue mich, sie auszuzahlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26080] = { id = 26080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein letzter Gefallen", description = "{name}, Ihr müsst das hier zu Käpt'n Glovaal bringen. In meinem Zustand bräuchte ich sicher eine Woche, um zur Dämmerbucht zu gelangen. Aber wir haben keine Zeit zu verlieren!", sourceObjective = "Bringt Grabungslieds Fisch und Tipps zu Kapitän Glovaal in der Dämmerbucht.", progress = "Chabt Ihr Oskar und Humphrey gefunden?", completion = "Ich verstehe. Ja, ich mich erinnere jetzt… Humphrey und Oskar waren nicht die besten Schwimmer.\n\nDie Informatjionen sind sehr chilfreich und der Fisch sieht sich sehr ljecker aus. Wenn Ihr Cherr Grabungslied seht, bevor er zurückkehrt, bitte sagt ihm danke von mjir.", sourceObjectiveStatus = "unverified-source-field" }
quests[26081] = { id = 26081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alinas Belohnung", description = "Hier endet also die Geschichte von Trol'kalar. Diese Waffe wird im Namen der Dunklen Fürstin den Lebenden den Tod bringen.\n\nVerlasst mich jetzt, {name}. Es obliegt mir erneut, die Klinge zu bewachen. Berichtet Alina von Eurem Sieg. Sie wird Euch sicherlich belohnen", sourceObjective = "Sprecht mit Dunkelruferin Alina.", completion = "Die Nachricht von Eurem Sieg stimmt mich zufrieden, {class}... ein seltenes Gefühl. Die Dunkle Fürstin glaubt, unsere Eroberung von Lordaeron wäre vielleicht die einzige Möglichkeit, den Verlassenen wahre Zufriedenheit zu schenken, vielleicht sogar Erleichterung.\n\nDoch das spielt keine Rolle. Unser Sieg ist unausweichlich. Für Eure Loyalität im Dienste der Verlassenen belohne ich Euch im Namen von Sylvanas.", sourceObjectiveStatus = "unverified-source-field" }
quests[26082] = { id = 26082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Kriegsnarbe!", description = "Ich werde dem alten Narr erlauben, seinen Fall vorzutragen. Er behauptet, er könne Beweise dafür bringen, dass die Nachtelfen keine Massenvernichtungswaffe besitzen. Wir werden sehen.\n\nWährend wir auf diesen Beweis warten, werdet Ihr unsere Armee im Tal unterstützen. Zu diesem Zweck haben wir eine große Anzahl Belagerungspanzer vorbereitet. Unsere Verwüster sind angriffsbereit.\n\nNehmt den Fahrstuhl hinunter zum Boden des Außenpostens und übernehmt einen Verwüster von Krom'gar. Vernichtet damit unsere Feinde im Kriegsnarbental.", sourceObjective = "Benutzt den Verwüster von Krom'gar, um 5 darnassische Glevenschleudern und 20 beliebige Soldaten der Allianz im Kriegsnarbental zu vernichten.", progress = "Tötet sie alle!", completion = "Ihr beweist ein ziemliches Zerstörungstalent, {name}. Die Allianzsoldaten, die nach Eurer wilden Fahrt durch das Kriegsnarbental noch übrig sind, wird die Bombe erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26083] = { id = 26083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallo Lolo", description = "Gichtdarm war geschickt spähen. Guckt viele Dinge. Groß Abenteuer!\n\nGichtdarm findet geheim Piratschiff. Piraten viel Angst, laufen weg. Aber Oger Lolo nicht laufen. Lolo macht gut Freund mit Gichtdarm!\n\nGichtdarm muss weg, aber vermissen Lolo. Ihr sagen hallo zu Lolo von Gichtdarm.", sourceObjective = "Findet Lolo den Ausguck in der Faldirbucht.", completion = "Ihr Freund von Gichtdarm! Er komisch Oger. Riechen seltsam.", sourceObjectiveStatus = "unverified-source-field" }
quests[26084] = { id = 26084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammerfall", description = "Ihr habt uns hier gut gedient, {name}. Wir haben ein Zeichen gesetzt, aber die nächste Phase unseres Eroberungsfeldzugs wird Monate brauchen, nicht nur Minuten.\n\nEs gibt noch viel zu tun. Ich werde Euch den langweiligen Teil - das Warten auf das Eintreffen der Wehrbefestigungen - ersparen. Reist gen Osten nach Hammerfall. Die Orcs dort werden Eure Hilfe gebrauchen können.", sourceObjective = "Meldet Euch bei Gor'mul in Hammerfall im Arathibecken.", completion = "Throm'ka, {class}. Wenn Eure Taten für die Untoten so bemerkenswert waren, wie Ihr sagt, fühle ich mich geehrt, Euch beim Dienst für die Horde zu unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26085] = { id = 26085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sammelt die Verteidiger", description = "Während unsere Ingenieure dafür sorgen, dass die Bomber bald wieder fliegen, kämpfen unsere Wachen und Gebirgsjäger gegen die Eindringlinge.\n\nSeit Beginn des Einmarschs sind sie dort draußen, ohne Zeit für Schlaf oder Essen. Die Verteidiger von Eisenschmiede gehören zu den besten Azeroths, aber selbst sie haben Grenzen.\n\nNehmt diese Banner und platziert sie in Verwehungen aus losem Schnee. Erinnert die Soldaten an das, wofür sie kämpfen und stärkt ihre Moral.", sourceObjective = "Platziert 8 Banner von Eisenschmiede in Hügel aus losem Schnee überall auf dem Flugplatz von Eisenschmiede.", completion = "Die Soldaten entdecken verborgene Reserven der Stärke und des Mutes und werfen sich den Dunkeleisenzwergen entgegen. Solange wir hier sind, wird der Flugplatz nicht fallen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26086] = { id = 26086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orako", description = "<Kapitän Verne sieht auf seine Uhr.>\n\nWo ist dieser Jäger? Ich habe Orako vor einer Woche in die Tiefenlichtkluft geschickt, um einen Bericht zu schreiben! Ja, er ist schon ganz schön anstrengend und ich hätte nichts dagegen, ihn vom Hals zu haben, aber ich brauche seinen Bericht.\n\nIhr da! Wie heißt Ihr? {name}? Würdet Ihr ihn für mich ausfindig machen? Es scheint zwar merkwürdig, dass <ein/eine:c> {class} einen Jäger suchen soll, aber mir bleibt keine andere Wahl.", sourceObjective = "Meldet Euch bei Orako bei der Tiefenlichtkluft in Vashj'ir.", completion = "Gah! Diese Fische sind einfach nicht zu treffen!\n\n<Orako schaut Euch an.>\n\nMein Wolf wurde von einem Fisch gefressen und ich gehe nicht zurück, bis ich ihn gefunden habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[26087] = { id = 26087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leuchtsaft", description = "Es ist einfach, einen Fisch in einem Fass zu erschießen. Einen Fisch in einem Meer zu erschießen ist da schon schwieriger.\n\nHabt Ihr die Murlocs unten in der Kluft gesehen, {class}? Sie schießen überhaupt nicht! Sie tragen kleine Kugeln voller Leuchtsaft auf dem Kopf, dank derer die Fische zu IHNEN kommen. He, das sollten wir auch versuchen!\n\nGeht nach Süden und tötet die Krebse und Barsche in der Kluft. Sie haben haufenweise Leuchtsaft in ihrer Haut. Ich habe es genau gesehen!", sourceObjective = "Besorgt Euch 6 Einheiten Leuchtsaft von den Pyropanzerkrabblern und Luxschuppenbarschen in der Tiefenlichtkluft.", progress = "Wir brauchen haufenweise Leuchtsaft!", completion = "Schaut nur, wie das leuchtet!\n\n<Orako blickt sehnsüchtig in die Ferne.>\n\nMein Wolf hat leuchtende Dinge geliebt…", sourceObjectiveStatus = "unverified-source-field" }
quests[26088] = { id = 26088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hierher, Fischlein Fischlein!", description = "<Orako formt einen Ball aus dem Leuchtsaft und bringt ihn dann an einem Gerät an, an dem er offensichtlich schon lange bastelt.>\n\nHier, ich habe einen Hut für Euch. Er hat ein Licht, das Fische anlockt. Genau wie bei den Murlocs!\n\nDie Murlocs jagen gerne im Tang und in den Korallen an den Seiten der Kluft. Wenn Ihr diesen Hut aufsetzt und durch den Tang schwimmt, könnt Ihr vielleicht genauso Fische fangen, wie sie.", sourceObjective = "Setzt den Fischerhut auf und schwimmt durch die Korallen in der Tiefenlichtkluft, um 30 Tiefenlichtknabberfische anzulocken.", progress = "Wie viele habt Ihr gefangen?", completion = "Hm… Ihr habt ganz schön viele Fische, aber das sind nicht die, die meinen Wolf gefressen haben. Ich schätze, es war ein größerer Fisch.", sourceObjectiveStatus = "unverified-source-field" }
quests[26089] = { id = 26089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stirb, Fischmann, stirb", description = "Ein Fisch hat meinen Wolf gefressen, und Murlocs sehen aus wie Fische. Diese Murlocs werden bezahlen!\n\nGeht zurück in die Kluft und tötet diese Fischmänner! Mein Wolf wird seine Rache bekommen!", sourceObjective = "Tötet 4 Tiefenlichtjäger und 4 Tiefenlichtorakel.", completion = "Ich weiß, dass Murlocs keine Fische sind. Ich dachte nur, sie zu töten würde meine Laune heben. Aber ich bin immer noch traurig wegen meines Wolfs.\n\n<Orako seufzt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26090] = { id = 26090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hier, ein Ei!", description = "<Dies scheint ein Ei eines dieser verschlagenen Großaale zu sein, die über der Kluft umherschwimmen. Ihr fragt Euch, ob Orako vielleicht daran interessiert sein könnte.>", sourceObjective = "Bringt das enorme Aalei zu Orako bei der Tiefenlichtkluft in Vashj'ir.", progress = "<Bamm!>\n\nIhr habt mir etwas mitgebracht?", completion = "Das ist ein großes Ei.\n\n<Orako schnüffelt daran.>\n\nEs ist groß und es riecht nach Fisch. Vielleicht ist der große Fisch, von dem dieses Ei stammt, ja der, der meinen Wolf gefressen hat!", sourceObjectiveStatus = "unverified-source-field" }
quests[26091] = { id = 26091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hierher, Fischlein Fischlein, Teil 2: Der Eier-Aal-Trick-Blues", description = "<Orako nimmt eine Sprengfalle aus seiner Tasche und schiebt sie durch die äußere Hülle des Eis.>\n\nJetzt wird das Ei explodieren. Legt es in der Nähe eines dieser gigantischen Aale ab und wartet, bis er näher kommt. Wenn das Ei explodiert, ist der große Fisch schon halbtot und Ihr könnt ihn leicht erledigen.\n\nRettet meinen Wolf! Mit diesem Ei wird es Euch gelingen.", sourceObjective = "Benutzt das aal-splosive Gerät in der Nähe eines verschlagenen Großaals in der Tiefenlichtkluft und besiegt dann den geschwächten Großaal.", completion = "<Orako spielt ausgiebig mit Wolf.>\n\nOh, vielen Dank, {name}! Ich wusste, dass Wolf noch lebt!\n\nHier, bedient Euch. Ich habe dafür keine Verwendung mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[26092] = { id = 26092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orakos Bericht", description = "<Ihr erinnert Orako daran, dass er einen Bericht an Kapitän Verne senden sollte.>\n\nStimmt, ein Bericht. Alles, was ich hier gesehen habe, sind Fische. Fische, Fische und nochmals Fische.\n\n<Orako wirft einen Blick auf den Sack Fische, den Ihr ihm mitgebracht habt.>\n\nBringt das zurück zum Kapitän. Das ist mein Bericht.", sourceObjective = "Bringt Orakos Bericht zu Kapitän \"Juwel\" Verne in der Schattenhöhle.", progress = "Wo war er? Was ist passiert?", completion = "Das ist sein Bericht?! Dieser Idiot…\n\nIch schätze, wir können die Nahrung gut gebrauchen. Danke, {name}. Ihr habt Eure Aufgabe so gut erledigt, wie ich es erwartet habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[26093] = { id = 26093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nordhof", description = "Wir kämpfen in einem Krieg um Stromgarde und wir verlieren. Die Oger, das Syndikat und wir selbst haben unsere einst mächtige Stadt zerrissen und jede Fraktion kämpft mit der anderen bis zu einem blutigen Patt.\n\nAber unsere Truppen werden dezimiert, während die Zahl der Feinde ansteigt.\n\nAuch wenn Süderstade gefallen ist, dürfen wir unseren Feinden keinen Fußbreit unseres Bodens mehr überlassen! Wir müssen das Land für uns zurückerobern, bevor die Horde die Gelegenheit hat, sich weiter auszubreiten.", sourceObjective = "Tötet 10 Mitglieder des Syndikats.", completion = "Sehr gut, {name}. Das letzte, was wir bei der Bedrohung durch die Untoten noch brauchen, ist ein Angriff von einer Bande gewöhnlicher Diebe.", sourceObjectiveStatus = "unverified-source-field" }
quests[26094] = { id = 26094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegenschlag", description = "Mein Chefingenieur sagt, dass er einen der Bomber repariert hat. Er ist startbereit. Nehmt diese Bomben und sucht den reparierten Bomber am Anfang der Rollbahn.\n\nSetzt die Bomben ein, sobald Ihr in der Luft seid, und richtet unter den angreifenden Dunkeleisenzwergen so viel Schaden wie möglich an. Ich habe Gerüchte gehört, laut derer sie eine neue Art von Kriegsgolem einsetzen wollen. Sucht nach diesen Golems. Sie sind Eure wichtigsten Ziele.", sourceObjective = "Steigt in den reparierten Bomber und tötet 30 Angreifer der Dunkeleisenzwerge mit der Eisenhammerbombe. Ihr könnt beliebige Dunkeleisenzwerge oder ihre Verbündeten auf dem Flugplatz töten.", completion = "Das Blatt wendet sich, {name}, größtenteils dank Eurer Leistungen. Jetzt müssen wir den Anführern der Dunkeleisenzwerge einen Schlag versetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26095] = { id = 26095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abzeichen von Stromgarde", description = "Das Syndikat in Stromgarde kämpft dort gegen unsere Milizeinheiten. Um den Abschaum dazu anzustacheln, unsere disziplinierteren Truppen anzugreifen, hat das Syndikat ein Kopfgeld auf unsere Soldaten ausgesetzt. Sie belohnen jedes Abzeichen von Stromgarde, das einem toten Milizsoldaten abgenommen wird, mit Gold.\n\nWir wollen diese Abzeichen wieder haben. Diese Halsabschneider dürfen keine Trophäen unserer mutigen Gefallenen behalten!\n\nBetretet den vom Syndikat kontrollierten Teil von Burg Stromgarde und bringt unsere Abzeichen an Euch.", sourceObjective = "Erbeutet 7 Abzeichen von Stromgarde vom feindlichen Syndikat in Burg Stromgarde.", progress = "Konntet Ihr Abzeichen von Stromgarde erbeuten, {name}? Das Syndikat muss begreifen, dass es von unseren Toten nicht profitieren wird.", completion = "Danke, {name}. Wir werden den Familien dieser gefallenen Soldaten mitteilen, dass sie im Kampf getötet wurden.\n\nSelbst schlimme Nachrichten sind besser als im Ungewissen über das Schicksal eines Angehörigen zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[26096] = { id = 26096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbrühende Pilze", description = "Wir glauben, dass wir eine gute Verwendung für die Gnadenlosen gefunden haben, die Euer Freund aus der Höhle uns gebracht hat. Ich benötige jedoch ein Konservierungsmittel dafür.\n\nUnten im Brühgraben findet Ihr Pilze, die genau die Eigenschaften haben, die ich brauche. Bringt mir ein paar davon und ich schaue, was ich tun kann.", sourceObjective = "Sammelt 5 Verbrühende Pilze.", progress = "Ich habe gehört, dass Ihr ein unangenehmes Erlebnis hattet, als Ihr Euch einen der Dämonen auf den Kopf gesetzt habt. Ich kann Euch jedoch versichern, dass sie jetzt alle mausetot sind.", completion = "Ich werde die Pilze als Reagenz benutzen, um die Kadaver einzubalsamieren. Wir haben gleich einen für Euch vorbereitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26097] = { id = 26097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweis für eine Lüge", description = "Im Herzen des Kriegsnarbentals steht ein uralter Baum - ein Baum, der den Zeitaltern widerstanden hat und seit Generationen als ein Ort des Friedens und der Lehre genutzt wird. Solange ich denken kann, hat meine Familie in diesem Hain zusammen mit den Nachtelfen das Druidentum studiert. Und jetzt soll ich glauben, dass sich in diesem Baum eine Massenvernichtungswaffe der Allianz befindet?\n\nKrom'gar irrt sich. Das werde ich beweisen!\n\nIch habe meinen Sohn Orthus in den Hain von Thal'darah geschickt. Er soll nach der Waffe suchen. Geht dorthin und trefft ihn.", sourceObjective = "Findet Orthus im Hain von Thal'darah im Steinkrallengebirge.", completion = "Orthus ist tot. Er hält etwas in der Hand.", sourceObjectiveStatus = "unverified-source-field" }
quests[26098] = { id = 26098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verrat im Hain", description = "Der Raum ist voller toter Druiden. Etwas stimmt nicht, denn Ihr seht keine Anzeichen eines Kampfes. Von der Tür führen blutige Schleifspuren ins Innere.\n\nIhr öffnet Orthus' erstarrte Faust und findet etwas verstörendes: ein Insigne des Generals von Krom'gar.\n\nBringt das Insigne des Generals von Krom'gar zurück zu Oberhäuptling Klippenläufer.", sourceObjective = "Bringt das Insigne des Generals von Krom'gar zurück zu Oberhäuptling Klippenläufer am Klippenläuferposten im Steinkrallengebirge.", progress = "Er... Mein Kind ist tot?", completion = "<Ihr gebt Oberhäuptling Klippenläufer das Insigne.>\n\n<Oberhäuptling Klippenläufer schreit wütend auf.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26099] = { id = 26099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das soll Gerechtigkeit sein?", description = "Er war ein guter Junge, {name}. Jung, liebevoll. Niemals hätte er einen der jungen Druiden getötet. Sie waren seine Freunde! Nein... Nicht Orthus.\n\nDer General muss sich für dieses Verbrechen verantworten. Ich verlange Gerechtigkeit!", sourceObjective = "Verteidigt Euch.", progress = "Das ist gerecht.", completion = "Ihr habt es mit eigenen Augen gesehen, {name}. General Grebo hat uns angegriffen!\n\n\n\nWas sollen wir jetzt tun? Der Kriegshäuptling wird uns als Verräter hinrichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26100] = { id = 26100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der General ist tot", description = "Würdet Ihr mit Oberanführer Krom'gar reden, {name}? Vielleicht hört er ja auf Euch. Ihr seid schließlich ein Champion in seiner Armee. Ihr habt alles gesehen. Bitte helft uns, {name}. Wir wollen doch nur in Frieden gelassen werden.\n\nSprecht mit Oberanführer Krom'gar und versucht ihm zu vermitteln, dass wir nicht wollten, was geschehen ist.", sourceObjective = "Sprecht mit Oberanführer Krom'gar in der Feste Krom'gar im Steinkrallengebirge.", completion = "WAS? Die Tauren haben meinen General umgebracht? Das ist Verrat! HOCHVERRAT! Für diesen schweren Fehler werden sie bezahlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26101] = { id = 26101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Über dem Gesetz", description = "Es war richtig, dass Ihr mir dieses Verbrechen gemeldet habt. Die Täter werden für dieses feige Verbrechen bezahlen. Blut wird fließen.\n\nOhne Grebo fehlt mir ein General. Ihr werdet seinen Platz einnehmen.\n\nTrefft mich am Klippenläuferposten, General. Zusammen werden wir diesen Schwachsinn beenden.", sourceObjective = "Trefft Oberanführer Krom'gar am Klippenläuferposten im Steinkrallengebirge.", completion = "Der verräterische Tauren wird zusehen, wie wir seinen geliebten Hain vernichten und sein Dorf niederbrennen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26102] = { id = 26102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimmaxts Ende", description = "Dank eures Einsatzes ist der Angriff der Dunkeleisenzwerge ins Stocken geraten. General Grimmaxt, der Anführer der Dunkeleisenzwerge, versucht, seine Truppen aus ihren Reihen auf dem gefrorenen See im Süden anzutreiben.\n\nEr steht auf einem ihrer neuen Dunkeleisengolems und ruft seinen Soldaten Befehle zu. Wenn es ihm gelingt, sie zu motivieren, überrennen sie uns vielleicht doch noch. Das müsst Ihr verhindern, {name}. Zerstört den Golem, der General Grimmaxt beschützt, dann ihn selbst. Er ist der Schlüssel zu unserem Sieg.", sourceObjective = "Tötet General Grimmaxt auf dem Flugplatz von Eisenschmiede.", completion = "Geschafft! Ohne Eure Hilfe hätte der Feind den Flugplatz von Eisenschmiede erobert. Dann hätten die Dunkeleisenzwerge freie Bahn bis Eisenschmiede gehabt.\n\nDer Rat der Drei Hämmer muss erfahren, was hier geschehen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[26103] = { id = 26103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Biotreibstoff", description = "Unterseeboottreibstoff ist teuer!\n\nDie Machthaber in Gnomeregan waren so freundlich, uns mehrere Treibstofffässer zur Verfügung zu stellen, aber wir verbrauchen sie schneller als erwartet. Das bedeutet, dass wir improvisieren müssen.\n\nEs ist kein Geheimnis, dass die Meereslebewesen allerlei interessante Chemikalien enthalten... wie zum Beispiel Öl. Bringt dieses Gerät zu Korthuns Ende und benutzt es an Kadavern von Schildkröten, Schiffshaltern und Hammerhaien. Wenn wir nicht mehr Unterseeboottreibstoff beschaffen können, ist ihr Öl vielleicht unsere einzige Hoffnung.", sourceObjective = "Benutzt die Ölextraktionspumpe an den Kadavern von Meeresdickichtschildkröten, Kolkschiffshaltern und Dornenschuppenhammerhaien in Korthuns Ende, um 4 Einheiten Schildkrötenöl, 4 Einheiten Schiffshalteröl und 4 Einheiten Hammerhaiöl zu sammeln.", progress = "Wie hat das Gerät funktioniert, {name}?", completion = "<Ingenieur Hexasept steckt einen Finger in jede Probe und schnuppert daran.>\n\nJa, das sollte klappen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26105] = { id = 26105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erobert Korthuns Ende", description = "Die Horde hat Spione in dieser Gegend? Die Dämmerbucht ist ganz in der Nähe und die Zange X2 befindet sich dort! Die Horde darf auf keinen Fall in ihre Nähe gelangen!\n\nIhr müsst jemanden in der Dämmerbucht darüber informieren… nachdem Ihr mehr von diesen dreckigen Spionen der Horde den Garaus gemacht habt!", sourceObjective = "Tötet 7 von Höllschreis Seebären in Korthuns Ende.", completion = "Das habt Ihr gut gemacht, {name}. Zur Zeit müssen wir besonders vor Angriffen der Horde auf der Hut sein. Die Zange X2 hat zwar viel Feuerkraft auf dem Meer, aber versteckt im hinteren Teil dieser Höhle ist sie leicht angreifbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[26106] = { id = 26106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treibstoffologie leicht gemacht", description = "Wie viel wisst Ihr über Treibstoff, {name}? Den perfekten Treibstoff herzustellen ist eine anspruchsvolle Aufgabe. Es gibt einfach viel zu viele Faktoren, die exakt ausgeglichen sein müssen: Chrono-Pyroxidationsparameter, Tempero-Inflammationsvariablen, ignifaktorische Rußifizierungskriterien... Und das sind nur die wichtigsten!\n\nHoffentlich kann ich die Proben, die Ihr mir gebracht habt, in das richtige Verhältnis bringen, um... den perfekten Biotreibstoff herzustellen. Benutzt den Tisch dort drüben und versucht, ein paar Proben miteinander zu kombinieren. Bringt mir die Ergebnisse, wenn Ihr fertig seid.", sourceObjective = "Benutzt die Treibstofftestanlage in der Dämmerbucht, um den perfekten Biotreibstoff herzustellen.", progress = "Wir haben noch nicht die richtige Kombination gefunden, {name}. Macht weiter! Ich bin mir sicher, dass Ihr es schafft.", completion = "Habt Ihr je daran gedacht, eine wissenschaftliche Karriere anzustreben, {name}? Wenn Ihr je genug von Eurem derzeitigen Metier habt, meldet Euch bei mir. Ich könnte einen Assistent mit Eurer Passion für Experimente und wissenschaftliche Arbeit brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26107] = { id = 26107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stimmungsaufheller", description = "Dank der Schamanenkünste unseres Volkes konnte ich Jahre der Lethargie hinter mir lassen. Jetzt sorge ich für alle hier und stelle den Segen her, der auch mir neue Kraft schenkte.\n\nDie Hochlandraptoren sind tückische und wilde Bestien. Ihre Geister können unseren Kriegern große Stärke geben. Bringt mir Raptoraugen, damit ich die Amulette herstellen kann, so wie es mich Tor'gan lehrte.", sourceObjective = "Erbeutet 10 Hochlandraptoraugen von Hochlandschreitern oder Hochlandhauern.", progress = "Die Wildheit in den Augen der Raptoren wird auf unsere Krieger übergehen.", completion = "Die Lethargie, die mich nach dem Fall unserer Lager überkam, war so stark, dass ich das Geschenk ablehnte, als man es mir anfangs machte.\n\nNun bin ich stolz darauf, meinen Anteil im Namen der Horde zu leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26108] = { id = 26108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arglist des Raptors", description = "Die Hochlandfleischpirscher sind noch wilder als ihre Artgenossen. Sie besitzen nicht nur Stärke, sondern auch große List.\n\nAls ich in der Lethargie gefangen war, konnten mich selbst Amulette der Stärke nicht bewegen. Doch Tor'gan benutzte die Herzen der Fleischpirscher, um mich mit einem Geist zu erfüllen, der meine Zweifel besiegte und mich befreite.\n\nUnsere Soldaten verdienen die List des Raptors. Sammelt Fleischpirscherherzen für mich, {name}.", sourceObjective = "Sammelt 12 Raptorherzen von Hochlandfleischpirschern.", progress = "All meine Vorbereitungen sind getroffen, jetzt brauche ich nur noch die Raptorherzen.", completion = "Ich übertrage die Macht und den Geist der Raptoren in diese Kugel, so wie es mich Tor'gan gelehrt hat. Sie wird die Krieger mit der wilden Stärke und der Intelligenz des Raptors erfüllen.\n\nDie List des Raptors erfüllt Euch nun auch, {class}. Nehmt sie mit Stolz an. Für die Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[26110] = { id = 26110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie in alten Zeiten", description = "Schon seltsam. Kin und ich haben so einiges zusammen durchgemacht und doch finden wir uns in Arathi wieder, wie schon vor so vielen Jahren.\n\nHier vereitelten wir einen Plan zur Schaffung einer neuen Seuche, sie und ich. Die Horde scheint ihre Lektion nicht gelernt zu haben, denn es wimmelt schon wieder von ihnen auf diesem Hof.\n\nIhr untoter Kurier schlurft für jeden sichtbar umher. Ihr könnt uns helfen. Findet den Kurier und bringt mit, was auch immer er bei sich trägt.", sourceObjective = "Nehmt dem Kurier der Verlassenen den versiegelten Ordner ab.", progress = "Vielen Dank für Eure Hilfe bei der Suche nach dem Kurier, {name}.\n\nWährend Eurer Abwesenheit sah Kin einen Apotheker, der aus dem gleichen Haus südlich von hier kam. Ich bin mir sicher, dass sie nichts Gutes im Schilde führen -- ich brauche nur einen Beweis, damit wir nicht unüberlegt handeln.\n\nHattet Ihr Glück?", completion = "Schon wieder Apotheker. Die kapieren es einfach nicht. Mal sehen, was dieses Mal los ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[26111] = { id = 26111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "… und er wird kommen", description = "Ich erfülle Euch nun mit den Energien des verderbenden Gesichtslosen.\n\nSchwimmt hinunter zu meinem Ködertotem im Graben im Nordosten. Nutzt das Totem, um die Energien zu entfesseln. Bringt mir das Gehirn ihres Anführers.\n\nRuft Ick'thys den Unergründlichen… und er wird kommen!", sourceObjective = "Besorgt Euch das Gehirn des Unergründlichen.", progress = "Habt Ihr es, {name}?\n\nMit dem Gehirn des Unergründlichen können wir vielleicht doch mit L'ghorek, dem sterbenden Ahnen vor uns, kommunizieren.", completion = "Und nun schauen wir mal, ob wir Euch in L'ghorek versetzen können, damit Ihr mit ihm sprecht, bevor er stirbt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26112] = { id = 26112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überfällige Antworten", description = "Wie genau ist es den Kriegern der Dunkeleisenzwerge gelungen, bis hierher vor die Tore Eisenschmiedes zu kommen und beinahe unsere Stadt zu erobern?\n\nHerrscht nicht 'Kaiserin' Moira, Mitglied unseres hochgeschätzten Rates der Drei Hämmer, über die Dunkeleisenzwerge? Ohne ihr Wissen und ihre Zustimmung konnte das nicht geschehen. Das war keine zusammengewürfelte Gruppe rebellischer Zwerge, sondern eine gut ausgerüstete Invasionsstreitmacht.\n\nIch habe einen Bericht über die Schlacht um den Flugplatz zusammengestellt. Bringt ihn zum Hohen Sitz nach Eisenschmiede und konfrontiert sie damit!", sourceObjective = "Bringt Steinbrechers Bericht zu Moira Thaurissan im Hohen Sitz von Eisenschmiede.", progress = "Was hat diese Störung zu bedeuten?", completion = "Und was genau ist das?\n\n<Moira nimmt den Bericht entgegen. Sie wird blass, als sie ihn liest.>\n\nDas ist unmöglich!", sourceObjectiveStatus = "unverified-source-field" }
quests[26113] = { id = 26113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quae und Kinelory", description = "Die Horde besetzt Go'sheks Hof im Osten schon seit langem. Bei all unseren anderen Problemen hier fiel das nicht ins Gewicht. Aber nun gibt es Berichte über Untote in diesem Gebiet.\n\nAlles, was alarmierender ist als ein paar schlurfende Peons, gibt Anlass zu Nachforschungen. Das ist nicht das erste Mal, dass die Untoten auf dem Hof ihre dunklen Pläne vorantreiben. Ich habe meine besten Späher dorthin geschickt. Meldet Euch bei Quae und Kinelory. Sie werden Euch alles erzählen.", sourceObjective = "Findet Quae auf dem Hügel über Go'sheks Hof.", completion = "Die Zuflucht schickt Euch? Schön, dass es sie noch gibt.\n\nWir haben hier ein paar interessante Dinge beobachtet, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26114] = { id = 26114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quae vertraut Euch", description = "<Quae sieht die Unterlagen durch.>\n\nAusdehnung...Gebietskontrolle... diese Untoten planen nichts neues, aber sie wollen ganz Arathi einnehmen. Wir müssen ihre Pläne stören.\n\nIch halte hier oben Wache. Ihr geht mit Kin und besorgt die Invasionspläne. Diese wandelnden Kadaver werden nicht einmal erfahren, welchen Tag wir haben.\n\nUnd passt auf sie auf, verstanden?", sourceObjective = "Sprecht mit Kinelory nahe Go'Sheks Hof im Arathihochland.", completion = "Die Seuche nahm uns unsere Freunde und Familien, aber die Verlassenen nahmen uns Phin. Sie sind nicht besser als die Geißel. Ich werde sie alle mit meinen eigenen Händen töten, wenn es sein muss.\n\nSagt Bescheid, wenn Ihr bereit seid. Wir können direkt anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26115] = { id = 26115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sehen ist verstehen", description = "Bleibt bei mir, {name} und seht zu, wie unsere mächtige Waffe den Feind vernichtet!\n\nVersteht, was es bedeutet, zur Horde zu gehören!", sourceObjective = "Versteht, was es bedeutet, zur Horde zu gehören.", progress = "Habt Ihr es verstanden?", completion = "Jetzt endlich wisst Ihr, was es heißt, ein Mitglied der Horde zu sein, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26116] = { id = 26116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kinelory schlägt zu", description = "Also gut, {name}. Wenn Ihr soweit seid... \n\nWollen wir?", sourceObjective = "Beschützt Kinelory, bis sie zu Quae zurückkehrt.", progress = "Bleibt besser bei Kinelory. Ich vertraue Euch, aber wenn ihr etwas zustoßen sollte, weiß ich nicht, was ich tun würde.", completion = "Ihr habt uns einen großen Dienst erwiesen, {name}. Danke.\n\nHoffentlich hat Euch Kin keine Probleme bereitet. Sie ist sehr zuvorkommend, aber tödlich für ihre Feinde.", sourceObjectiveStatus = "unverified-source-field" }
quests[26117] = { id = 26117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für Süderstade", description = "Es gab Abende in der Taverne, nach denen Kinelory schlimmer aussah als jetzt. Ihr habt sie anscheinend gut beschützt.\n\nDie Zuflucht sollte von unserem Erfolg erfahren. Ich bleibe mit Kin hier, damit sie sich ausruhen kann. Geht ohne uns los.", sourceObjective = "Kehrt zu Kommandantin Amaren in der Zuflucht zurück.", completion = "Ich bin wirklich beeindruckt, {class}. Bei all dem, was hier geschieht, ist dies ein kleiner Trost.\n\nIhr habt die Untoten bekämpft, die Horde zurückgeworfen und die Opfer von Süderstade geehrt. Im Namen des Königreichs von Stromgarde verleihe ich Euch eine offizielle Belobigung und diese Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[26118] = { id = 26118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fasst den Botschafter", description = "Der Verrat des Botschafters wird mich noch lange verfolgen. Ihr müsst ihn verhaften, bevor er noch weiteren Schaden anrichtet oder schlimmer noch, bevor er entkommt und mit der Planung des nächsten Angriffs beginnt. Eisenschmiede wird erst sicher sein, wenn Botschafter Schlackenhammer sich nicht mehr frei in der Stadt bewegt.\n\nNehmt diese Fesseln und geht zur Botschaft der Dunkeleisenzwerge. Sie befindet sich nördlich des Hohen Sitzes, am Rand der Großen Schmiede. Verhaftet Botschafter Schlackenhammer und kehrt mit ihm zurück.", sourceObjective = "Geht zur Botschaft der Dunkeleisenzwerge und verhaftet Botschafter Schlackenhammer mit Hilfe der stabilen Handfesseln.", completion = "Der Botschafter wird uns keinen Ärger mehr machen. Er ist nicht der einzige Dunkeleisenzwerg, dessen Herz immer noch für den Schattenhammer schlägt. Das dürfen wir nie vergessen. Wir müssen wachsam sein und ihre Pläne vereiteln, sonst wird mein Sohn nur Ruinen und Asche erben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26120] = { id = 26120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der wahnsinnige Orc des Drachenmals", description = "Die Orcs des Drachenmals werden immer mehr zur Plage. Ihre waghalsigen Angriffe auf den Hain sind zwar lästig, verhelfen meinen Wachen aber wenigstens zu einigen nützlichen Übungseinheiten.\n\nMeine Späher haben jedoch beobachtet, dass sie schwarze Großdrachenwelpen mit Netzen einfangen. Das Letzte, was dieses Land gebrauchen kann, ist ein primitives Wiederaufleben der Drachenzähmung. Macht Euch auf den Weg nach Osten, {class}, und tötet die Welpendiebe. Sorgt dafür, dass ihre Dummheit uns nicht teuer zu stehen kommt.", sourceObjective = "Tötet 12 Welpendiebe des Drachenmals.", completion = "Die Orcs haben verstanden, dass sie nicht weiter nach Westen vordringen dürfen. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26121] = { id = 26121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erobert Korthuns Ende", description = "Ihr seht Spione da oben? Das ist nix gut… gar nix gut, <Genosse/Genossin>.\n\nKehrt zurück zu Korthuns Ende und vernichtet sie, mein Freund.", sourceObjective = "Tötet 7 von Höllschreis Seebären in Korthuns Ende.", sourceObjectiveStatus = "unverified-source-field" }
quests[26122] = { id = 26122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umweltbewusstsein", description = "Habt Ihr je Unterseeboottreibstoff gerochen, {name}? Widerliches Zeug. Leider müssen wir große Mengen davon verbrennen, um die Verne anzutreiben. Und es riecht nicht nur abstoßend, sondern ist auch tödlich für die Tiere hier. Wir müssen bewusster mit unserer Umwelt umgehen.\n\nDie Meereswesen hier in der Gegend haben besonders öliges Fleisch. Bringt dieses Gerät zum Meeresdickicht direkt über dieser Höhle und benutzt es an den Kadavern von Schildkröten, Schiffshaltern und Hammerhaien. Ihr Öl kann vielleicht das Leben Hunderter anderer Meereslebewesen retten.", sourceObjective = "Benutzt die Ölextraktionspumpe an den Kadavern von Meeresdickichtschildkröten, Kolkschiffshaltern und Dornenschuppenhammerhaien in Korthuns Ende, um 4 Einheiten Schildkrötenöl, 4 Einheiten Schiffshalteröl und 4 Einheiten Hammerhaiöl zu sammeln.", progress = "Bitte… Sagt den anderen Goblins nicht, dass ich Umweltschützer bin! Ich könnte ihren Spott nicht ertragen!", completion = "<Fiasco steckt einen Finger in jede Probe und schnuppert daran.>\n\nJa, das sollte klappen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26124] = { id = 26124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sichert das Meeresdickicht", description = "Die Allianz hat Spione in dieser Gegend? Die Schattenhöhle ist ganz in der Nähe und das neue Unterseeboot der Horde, die Verne, befindet sich dort! Die Allianz darf auf keinen Fall in ihre Nähe gelangen!\n\nIhr müsst jemanden in der Höhle darüber informieren… nachdem Ihr mehr von diesen hinterhältigen Spionen der Allianz den Garaus gemacht habt!", sourceObjective = "Tötet 7 Meeresspäher der Allianz im Meeresdickicht.", completion = "Das habt Ihr gut gemacht, {name}. Zur Zeit müssen wir besonders vor Angriffen der Allianz auf der Hut sein. Die Verne hat zwar viel Feuerkraft auf dem Meer, aber versteckt im hinteren Teil dieser Höhle ist sie leicht angreifbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[26125] = { id = 26125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sichert das Meeresdickicht", description = "Ihr habt da oben Spione gesehen? Das ist nicht gut… Das lasse ich nicht zu!\n\nKehrt zum Meeresdickicht zurück und werdet sie los, bevor sie sich in unser Versteck einschleichen können.", sourceObjective = "Tötet 7 Meeresspäher der Allianz im Meeresdickicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26126] = { id = 26126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der perfekte Treibstoff", description = "Wie viel wisst Ihr über Treibstoff, {name}? Den perfekten Treibstoff herzustellen ist eine anspruchsvolle Aufgabe. Es gibt einfach viel zu viele Faktoren, die exakt ausgeglichen sein müssen: Chrono-Pyroxidationsparameter, Tempero-Inflammationsvariablen, ignifaktorische Rußifizierungskriterien... Und das sind nur die wichtigsten!\n\nHoffentlich kann ich die Proben, die Ihr mir gebracht habt, in das richtige Verhältnis bringen, um... den perfekten Biotreibstoff herzustellen. Benutzt den Tisch dort drüben und versucht, ein paar Proben miteinander zu kombinieren. Bringt mir die Ergebnisse, wenn Ihr fertig seid.", sourceObjective = "Benutzt die Treibstofftestanlage in der Schattenhöhle, um den perfekten Biotreibstoff herzustellen.", completion = "Das war's. Ab heute werde ich die Verne mit Biotreibstoff betreiben. Ich werde ein paar Männer nach oben schicken, um mehr Öl zu besorgen.\n\nDenkt nur an die ganzen Meerestiere, die wir heute gerettet haben, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[26127] = { id = 26127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Enthüllung des Schattenhammers", description = "Ich dachte ebenso wie alle anderen, dass es sich bei diesen Narren nur um nichtsnutzige Dunkeleisenzwerge handelte, aber diese Wahnsinnigen sind überzeugte Kultisten!\n\nDer Schattenhammer will nichts anderes als die Zerstörung der ganzen Welt. Sie haben sich Todesschwinge und Ragnaros angeschlossen und sind eng mit den Dunkeleisenzwergen verbunden.\n\nAber es ist egal, wer sie sind, wichtig ist nur, dass sie sich in Dun Modr aufhalten und entfernt werden müssen! Ich werde keinen von ihnen durchlassen. Geht zu ihnen und zertrümmert ein paar Schädel!", sourceObjective = "Tötet 12 Mitglieder des Schattenhammers in Dun Modr.", completion = "Gute Leistung, Junge, aber wir haben keine Zeit für Feste. Der Thandolübergang wird bedroht!", sourceObjectiveStatus = "unverified-source-field" }
quests[26128] = { id = 26128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um den Thandolübergang", description = "Ich habe den Thandolübergang schon einmal vor der Zerstörung bewahrt. Damals kämpfte ich gegen die Dunkeleisenzwerge. Das gleiche tat mein Vater und dessen Vater vor ihm...\n\nDie einzigen Dunkeleisenzwerge, die mir entkamen, liefen direkt auf die Brücke zu. Etwas stimmt nicht. Ich befürchte, dass wir bei unserer Ankunft in eine üble Falle stürmen werden.\n\nIch könnte Eure Hilfe brauchen, {name}. Für Eisenschmiede. Seid Ihr dabei?", sourceObjective = "Besiegt Calamoth Aschbart am Thandolübergang.", completion = "Gut, dass wir den los sind!\n\nDank Euch ist der Thandolübergang sicher, {name}. Ich hoffe, dass Calamoth nicht noch einmal zurückkehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26129] = { id = 26129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffenbrüder", description = "Hört zu, {name}. Zum ersten Mal seit dem Bürgerkrieg bin ich mit Graumähne einer Meinung. Es ist an der Zeit, unsere Fehde endlich beizulegen.\n\nDiesen Bestien scheint es egal zu sein, ob man Rebell oder Königstreuer ist.\n\nÜberbringt Graumähne meine Antwort. Meine Männer werden sich seinen Leuten anschließen.\n\nNicht weit von hier gibt es ein sicheres Versteck, in Josiahs Keller. Meine Jungs haben dort ein wenig schwere Artillerie gelagert.\n\nSagt dem König, dass er sich jederzeit in unserer Waffenkammer bedienen kann.", sourceObjective = "Sprecht mit König Genn Graumähne im Militärviertel in Gilneas.", completion = "Eine Waffenkammer der Rebellen? In meiner eigenen Stadt?\n\nWas zur Hölle führte Crowley nur im Schilde?", sourceObjectiveStatus = "unverified-source-field" }
quests[26130] = { id = 26130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Verbindung zu L'ghorek", description = "L'ghorek ist der Ahn, der auf der Klippe gegenüber von uns ruht. Er wird kontrolliert. Etwas Riesiges unter uns verschlingt seine Lebensenergien.\n\nUnter L'ghorek gibt es eine Höhle, die als Muscheltiefe bekannt ist. In dieser Höhle befinden sich drei mächtige Ogermagier, die ein Ritual abhalten, das das Ding aus der Tiefe mit dem Ahnen verbindet. Ihr müsst die drei töten, um die Verbindung zu L'ghorek zu unterbrechen.", sourceObjective = "Tötet Ur'Goz, Sku'Bu und Neph'Lahim.", completion = "Jetzt, da L'ghoreks Verbindung unterbrochen wurde, müssen wir versuchen, mit ihm Kontakt aufzunehmen. Ich kann spüren, dass der Ahn noch lebt, aber er ist sehr schwach.", sourceObjectiveStatus = "unverified-source-field" }
quests[26131] = { id = 26131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung für Loch Modan", description = "Seit Stunden warte ich darauf, dass sich der Rat meine Bitte anhört, aber es sieht nicht gut aus. Moira scheint darauf versessen zu sein, den Rat lahmzulegen.\n\nWährenddessen leidet Loch Modan. Wir haben viele Feinde, aber nur wenige Ressourcen. Würdet Ihr mich vielleicht anhören, {name}, wenn der Rat nicht dazu gewillt ist? Sprecht mit Gryth Thurden, dem Greifenmeister von Eisenschmiede. Er hält sich im östlichen Teil der Großen Schmiede auf. Er wird Euch kostenlos zum Südtorpass fliegen lassen. Stellt Euch nach Eurer Ankunft Pilot Hammerfuß vor.", sourceObjective = "Bittet Gryth Thurden in der Großen Schmiede um einen Flug nach Loch Modan. Sprecht bei Eurer Ankunft mit Pilot Hammerfuß.", completion = "Ihr könnt Euch nicht vorstellen, wie froh ich bin, neue Gesichter aus Eisenschmiede zu sehen. Vielleicht war es doch keine Verschwendung, Gebirgsjäger Gerstenbräu dorthin zu entsenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26132] = { id = 26132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scheusale aus der Netherwelt", description = "Die Ogermagier in der Muscheltiefe haben sich selbst ein paar Beschützer beschworen: Fleischlingscheusale aus der Netherwelt.\n\nWir können nicht riskieren, dass sie diese Entartungen später gegen unsere Streitmächte einsetzen. Wenn Ihr schon da drin seid, zerstört so viele von den Dingern, wie Ihr könnt.", sourceObjective = "Tötet 8 Netherscheusale.", completion = "Das Letzte, was wir brauchen, ist ein Haufen beschworener Kreaturen, die während unseres letzten Angriffs unsere Streitmächte anfallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26133] = { id = 26133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scheusale aus der Netherwelt", description = "Die Ogermagier in der Muscheltiefe haben sich selbst ein paar Beschützer beschworen: Fleischlingscheusale aus der Netherwelt.\n\nIch will nicht miterleben, dass sie diese Entartungen gegen unsere Streitmächte einsetzen. Wenn Ihr schon da drin seid, vernichtet sie alle!", sourceObjective = "Tötet 8 Netherscheusale.", completion = "Eine Sache weniger, um die wir uns bei unserem letzten Angriff sorgen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26134] = { id = 26134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts mehr für Euch hier", description = "Es gibt hier nichts mehr für Euch, {name}. Was mich betrifft, ich muss nur noch Mashas Leiche begraben. Wenn ich das getan habe, werde ich zur Bombenabwurfstelle gehen und das Nachwachsen einleiten. Vielleicht wird eines Tages ein neuer Hain erblühen - ein Hain erfüllt mit dem Geist meines Kindes und denen der gefallenen jungen Nachtelfen.\n\nIch habe von einem Blutelf namens Furien in Desolace gehört, der nach gleichgesinnten Abenteurern sucht. Vielleicht solltet Ihr ihn aufsuchen.\n\nLebt wohl, <Freund/Freundin>, ich werde Euch nie vergessen.", sourceObjective = "Sprecht mit Furien in Tethris Aran in Desolace.", completion = "<Furien stöhnt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26135] = { id = 26135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visionen der Vergangenheit: Aufstieg aus der Tiefe", description = "Was Ihr mir vorhin von den Naga erzählt habt, lässt mir keine Ruhe mehr. Wer sind diese Verbündeten, die sie rufen? Denken sie wirklich, sie könnten den Gezeitenjäger besiegen?\n\nDie Flucht aus dieser Höhle ist eine ganz schöne Erleichterung, aber unser Ziel hier bleibt das gleiche. Ich hoffe, dass Ihr bereit seid, ein letztes Mal die Antworten bei der Kriegsmaid zu suchen.\n\nEs kann nur einen Ort geben, an den sie das Artefakt gebracht haben: den Tempel oben auf den Ruinen. Sicher wird er gut beobachtet. Seid daher vorsichtig.", sourceObjective = "Werdet Zeuge der letzten Geschichte der Kriegsmaid, indem Ihr ihre gebrochene Klinge im Tempel von Quel'Dormir benutzt.", completion = "Diener des alten Gottes? Dann haben sich zwei sehr gefährliche Feinde miteinander verbündet. Vielleicht ist es doch nicht so abwegig, dass sie den Gezeitenjäger töten können.\n\n{name}, das dürfen wir nicht zulassen. Wenn Azshara den Gezeitenjäger besiegt und seine Macht an sich reißt, kann wahrscheinlich keiner auf den Meeren gegen sie bestehen.\n\nWenigstens ist der erste Schritt eindeutig. Wir müssen dieses Untier vernichten, das unsere Schiffe zerstört hat. Unsere Marine war mutig genug, eine neue Flotte hierher zu bringen. Vielleicht haben sie ja einen Plan.", sourceObjectiveStatus = "unverified-source-field" }
quests[26137] = { id = 26137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach den Jungs", description = "Ihr habt sicher gesehen, wie stark der Loch mittlerweile geschädigt ist. Die Schäden dehnen sich leider sogar noch weiter aus. Das ganze Wasser musste ja irgendwo hin, und es floss hinunter ins Sumpfland.\n\nDa unten unterstützen uns viele mutige Zwerge. Sie brauchen Vorräte. Aus diesem Grund habe ich zwei meiner Gebirgsjäger mit einem Fass voller Bier auf den Weg ins Sumpfland geschickt.\n\nSeit sie die Straße nach Dun Algaz erreicht haben, gab es keine Nachricht mehr von ihnen. Würdet Ihr nachsehen, ob es ihnen gut geht?", sourceObjective = "Reist ins Sumpfland und sprecht mit Gebirgsjäger Rharen nahe Dun Algaz.", completion = "Gut, Euch zu sehen, {class}.\n\nSturmlanze schickt Euch? Wegen des Fasses? Oh Mann...", sourceObjectiveStatus = "unverified-source-field" }
quests[26138] = { id = 26138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ferilon Laubkind", description = "Eine Gruppe von Nachtelfen hat sich im Sumpfland niedergelassen. Ein paar von ihnen sind aus Kalimdor eingetroffen, um das Land hier zu untersuchen, sich die Pflanzen anzusehen und all so etwas.\n\nEiner der Druiden - er heißt Ferilon - kam hier vor einer Weile vorbei. Er war so nett, uns mit den Raptoren zu helfen und erwähnte, dass er Leute braucht, die ihn bei seinen Aufgaben unterstützen.\n\nWenn Ihr Zeit habt, könntet Ihr ihn an einem Ort im Nordosten namens Hain des Sumpfhüters aufsuchen.", sourceObjective = "Findet Ferilon Laubkind im Hain des Sumpfhüters.", sourceObjectiveStatus = "unverified-source-field" }
quests[26139] = { id = 26139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Arathi", description = "Geht vor und warnt die andere Seite des Übergangs, {name}.\n\nHinter der Brücke im Norden werdet Ihr die Zuflucht finden, die Festung der Allianz in Arathi. Sagt Hauptmann Nials, er solle sich vor den Hundesöhnen des Schattenhammers in Acht nehmen.", sourceObjective = "Reist ins Arathihochland und sprecht mit Hauptmann Nials in der Zuflucht.", completion = "Ich sollte Thargas wohl dafür danken, dass er mir einen so mutigen Helden geschickt hat.\n\nVielleicht wollte er aber auch nur alles allein aufräumen. In jedem Fall könnt Ihr hier viel für die Allianz tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[26140] = { id = 26140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit dem Ahnen reden", description = "Setzt den toten Gnadenlosen auf Euren Kopf und gebt Euch als einer ihrer Sklaven aus.\n\nBetretet L'ghorek. Kommuniziert mit dem Ahnen.", sourceObjective = "Bringt das Gehirn des Unergründlichen zu L'ghorek im Cerebrillum in L'ghorek in Vashj'ir.", progress = "ICH SPÜRE... ETWAS. KOMMT NÄHER...", completion = "WEISE VON… EUREM ERUNAK… EUCH... DAS… GEHIRN DES GESICHTSLOSEN… VERWENDEN ZU LASSEN. ICH SEHE… EUCH JETZT.\n\nICH WERDE STERBEN. ES IST NICHT… AUFZUHALTEN.\n\nABER… IHR WERDET MIR… ERST HELFEN, DIESE… PARASITEN ZU BESEITIGEN.", sourceObjectiveStatus = "unverified-source-field" }
quests[26141] = { id = 26141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runensteine der Bindung", description = "AUF DER ANDEREN… SEITE MEINES… RAUMS SIND… KANDIDATEN FÜR DEN AUFSTIEG.\n\nWIR BENÖTIGEN… IHRE RUNENSTEINE DER BINDUNG… UM EINEN... WEG ZU FINDEN... EINEN GEBUNDENEN ELEMENTAR... ZU KONTROLLIEREN.", sourceObjective = "Sammelt 7 Runensteine der Bindung.", progress = "HABT… IHR ALLES… WAS… WIR BRAUCHEN?", completion = "WIR WERDEN… DIESE… RUNENSTEINE NUTZEN… DAMIT IHR… VON EINEM… DER WASSERELEMENTARE... BESITZ ERGREIFEN KÖNNT.", sourceObjectiveStatus = "unverified-source-field" }
quests[26142] = { id = 26142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg verboten!", description = "UM IHRE… RITUALE DES AUFSTIEGS… AUFZUHALTEN… MÜSST IHR DIE… URALTEN LEITUNGEN ZERSTÖREN.\n\nSIE VERWENDEN… DIE LEITUNGEN, UM… MEINE ENERGIEN… ABZUZAPFEN UND… ASZENDENTEN ZU ERSCHAFFEN.\n\nEIN KAMPF MIT… NEPTULON IST UNVERMEIDBAR. DER SCHATTENHAMMER… DARF DIESE WESEN... NICHT HABEN.", sourceObjective = "Zerstört 5 uralte Leitungen.", completion = "IHR AUFSTIEG… IST ZU ENDE!", sourceObjectiveStatus = "unverified-source-field" }
quests[26143] = { id = 26143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles, was aufsteigt", description = "<Die Stimme des Ahnen drückt gegen Euren Geist.>\n\nJETZT, DA IHR… DIE ENERGIEN… DER GETREUEN… GESTOHLEN HABT… BETRETET DEN TEMPEL UND… VERNICHTET… HALLAZEAL DEN AUFGESTIEGENEN!", sourceObjective = "Tötet Hallazeal den Aufgestiegenen.", completion = "IHR HABT… MIR UND DEM… GEZEITENJÄGER EINEN… GROSSEN DIENST ERWIESEN.", sourceObjectiveStatus = "unverified-source-field" }
quests[26144] = { id = 26144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangene", description = "Der Kultist des Schattenhammers hat diesen Schlüssel fallenlassen. Benutzt ihn, um die Gefangenen der Allianz in den Käfigen in L'ghorek zu befreien.\n\nSchnell, bevor die Gefangenen dem geopfert werden, was dort in der Tiefe lauert!", sourceObjective = "Rettet 5 Gefangene der Allianz.", sourceObjectiveStatus = "unverified-source-field" }
quests[26145] = { id = 26145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bedrohung durch die Troggs", description = "{class}, Ihr seid Euch vielleicht nicht unbedingt der Bedrohung durch die Troggs bewusst, die ihren Schatten über das Land der Zwerge wirft. Nachdem die Reserve von Eisenschmiede zur Front der Allianz gerufen wurde, bleibt uns nur ein Bruchteil der Verteidigungskräfte, die nötig wären, um dieses Land zu schützen. Meinem Regiment wurde aufgetragen, über die Stadt hier zu wachen und wir können unseren Posten aufgrund der Gefahr einer Invasion nicht verlassen.\n\nEs muss aber etwas Druck auf diese verdammten Troggs ausgeübt werden, die in den Hügeln lauern. Wenn Ihr Euch dem gewachsen fühlt, startet einen Angriff auf die Troggs. Bringt mir acht Troggsteinzähne als Beweis.", sourceObjective = "Sammelt 8 Troggsteinzähne.", progress = "Könnt Ihr mir acht Troggsteinzähne zeigen? Wenn nicht, dann habt Ihr immer noch etwas zu erledigen, {name}.", completion = "Ich bin ziemlich beeindruckt, {name}. Ihr habt dem Volk der Zwerge einen großen Dienst erwiesen, indem Ihr unser Land verteidigt habt. Selbst König Magni Bronzebart wäre stolz auf Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[26146] = { id = 26146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung der Länder des Königs", description = "Wir müssen den Loch beschützen, {name}! Da so viele Soldaten des Königs tapfer auf entlegenen Schlachtfeldern kämpfen, wurden wir an der Heimatfront überrannt. Troggs schlüpfen aus jeder Spalte! Der Troggbefall stellt die größte Bedrohung für Eisenschmiede dar.\n\nWir brauchen Euch, <tapferer Abenteurer/tapfere Abenteurerin>, damit Ihr Euch vorwagt, um dieser Bedrohung durch die Troggs ein Ende zu bereiten. Tötet zwölf Splittersteintroggs und kommt zurück.", sourceObjective = "Tötet 12 Splittersteintroggs oder Späher der Splittersteintroggs.", completion = "Gut gemacht, {name}! Ihr habt verblüffende Tapferkeit auf dem Schlachtfeld gezeigt. Wir werden den Krieg gegen die Troggs durch solche Anstrengungen gewinnen. Ihr habt König Magni gute Dienste geleistet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26147] = { id = 26147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Größer und ekliger", description = "Die Gebirgsjäger haben mir erzählt, dass Ihr recht mutig und fähig seid, {name}. <Ein/Eine:r> {race} wie Ihr ist hier vonnöten. Das Problem mit den Troggs wird nicht besser. Unsere Reservekräfte wurden an die Front gerufen und nun sind wir hier alleine. Doch jetzt, wo <ein erfahrener/eine erfahrene:c> {class} hier ist, können wir sicher mehr erreichen.\n\nGeht und tötet acht Schamanen der Splittersteintroggs und acht Knochenknacker der Splittersteintroggs. Ihr könnt sie in und in der Nähe der Höhle im südlichen Teil der Berge finden.\n\nNun lasst uns sehen, ob Ihr Eurem Ruf als Trogg-Schreck gerecht werdet.", sourceObjective = "Tötet 8 Schamanen der Splittersteintroggs und 8 Knochenknacker der Splittersteintroggs.", completion = "Ich war mich sicher, als ich Euch gesehen habe, {name}: Ihr würdet Eisenschmiede stolz machen. Ihr habt unserem Volk gut gedient. Ich salutiere vor Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26148] = { id = 26148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Entscheidungsschlag", description = "Die Bestien in Loch Modan scheinen einem Häutpling namens Grawmug zu folgen. Er ist der größte aller Troggs und hält sich tief in der Dunkelheit der Höhlen nördlich von hier auf.\n\nWenn Ihr meint, Ihr seid einer solchen Aufgabe gerecht, so würde ich Euch gerne mit der Ermordung Grawmugs beauftragen.", sourceObjective = "Tötet Grawmug.", completion = "Ausgezeichnet, {name}! Ihr habt wieder Hoffnung nach Loch Modan gebracht. Durch den Tod Grawmugs haben wir bessere Aussichten darauf, die Troggs aus diesen Landen zu vertreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26149] = { id = 26149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangene", description = "Der Kultist des Schattenhammers hat diesen Schlüssel fallenlassen. Benutzt ihn, um die Gefangenen der Horde in den Käfigen in L'ghorek zu befreien.\n\nSchnell, bevor die Gefangenen dem geopfert werden, was dort in der Tiefe lauert!", sourceObjective = "Rettet 5 Gefangene der Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[26150] = { id = 26150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Besuch bei Maybell", description = "Ihr scheint mir vom hilfsbereiten Schlag zu sein, {name}. Würdet Ihr einem alten Mann einen Gefallen tun?\n\nDas letzte Mal, als ich drüben in den Weinbergen der Maclures war, habe ich Maybell in ihrer Hütte weinen hören. Wärt Ihr so nett und würdet nach ihr sehen? Ich mache mir Sorgen um sie.", sourceObjective = "Sprecht mit Maybell Maclure in den Weinbergen der Maclures in den Wäldern von Elwynn.", completion = "William hat Euch geschickt? Gesegnet sei seine Seele. Mir… mir geht es gut. Es ist nur… Nun ja…", sourceObjectiveStatus = "unverified-source-field" }
quests[26152] = { id = 26152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: James Clark", description = "Auf Geheiß der Armee von Sturmwind wurde ein Kopfgeld auf James Clark ausgesetzt.\n\nClark wird gesucht wegen Raubes, Einbruchs, Brandstiftung und Mordes. Er wird auch verdächtigt, Brackbrunns preisgekröntes Schwein Prinzessin entführt zu haben und versteckt zu halten.\n\nJames Clark wurde zuletzt auf dem Weg zum Holzfällerlager des Osttals gesehen.\n\nFührt James Clark der Gerechtigkeit zu und meldet Euch dann bei Marschall McCree im Holzfällerlager des Osttals.", sourceObjective = "Tötet James Clark und nehmt James Clarks Kopf.", progress = "Wollt Ihr ein Kopfgeld einfordern?", completion = "Und wieder wurde der Gerechtigkeit Genüge getan.", sourceObjectiveStatus = "unverified-source-field" }
quests[26153] = { id = 26153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pennys Kürbiskuchen", description = "Meine Tochter liebt Kürbispuffer, aber hier in Elwynn gab es dieses Jahr wegen des kalten Winters nur wenig Kürbisse. Ich habe aber von einem Kürbisfeld bei Sturmwind gehört, auf dem die Früchte nun reif sein sollen. Erntet für mich ein paar reife Kürbisse und ich werde Euch meinen Dank beweisen.", sourceObjective = "Sammelt 6 Sturmwindkürbisse und bringt sie Robby Flay in Sturmwind.", progress = "Habt Ihr die Kürbisse geerntet?", completion = "Gute Arbeit, {name}! Penny wird morgen zum Frühstück eine tolle Überraschung bekommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26154] = { id = 26154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenkammerjäger", description = "NUN… NEHMT DEN… ABGESTIMMTEN RUNENSTEIN… UND BENUTZT IHN… UM VON EINEM… GEBUNDENEN STROM… IM MITTLEREN TEMPEL… BESITZ ZU ERGREIFEN. SIE WERDEN… EUCH… IGNORIEREN. KEINER WIRD… EUCH BEMERKEN.\n\nNUTZT... DIE MACHT DES ELEMENTARS… UM ZWIELICHTVEREHRER... UND IHRE GESICHTSLOSEN AUFSEHER... ZU TÖTEN.", sourceObjective = "Ergreift Besitz von einem gebundenen Strom und tötet dann 50 Zwielichtverehrer und 10 gesichtslose Aufseher.", sourceObjectiveStatus = "unverified-source-field" }
quests[26157] = { id = 26157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kasim Sharim", description = "Ich möchte, dass Ihr eine Nachricht für mich überbringt.\n\nKasim Sharim ist ein alter Blutmagier, der viel über die Dämonen in den Verwüsteten Landen weiß. Man sieht es ihm zwar nicht an, aber er ist recht alt und sehr mächtig... aber auch ein wenig exzentrisch. In letzter Zeit hält er sich meistens im hinteren Teil der Schlangenschlinge auf, einer Höhle in der Nähe des Ortes, an dem ihr die Kultisten getötet habt.\n\nBitte überbringt ihm diese Nachricht. Er wird ihre Bedeutung verstehen.", sourceObjective = "Meldet Euch bei Kasim Sharim im hinteren Teil der Schlangenschlinge in den Verwüsteten Landen.", progress = "Ich kenne Euch nicht.", completion = "Hah! Ihr Einfaltspinsel aus Nethergarde seid immer zwei Schritte hinter mir, dabei bin ich längst nicht so schnell wie früher.\n\nIch brauche Mahars Notiz nicht. Ich weiß auch so, was vorgeht. Was glaubt Ihr, weshalb ich mich so tief in eine Höhle zurückgezogen habe? Ein starker {race} wie Ihr wäre mir allerdings eine Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[26158] = { id = 26158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stimmt den Blutstein ab", description = "Haben die Kämpfe auf dem Weg durch die Höhle Spaß gemacht? Zugegebenermaßen habe ich nicht die... praktischste Stelle für meine Studien ausgesucht, vor allem nicht für vorbeiziehende <Abenteurer/Abenteuerinnen>, die nach Belieben kommen und gehen wollen.\n\nAllerdings kann ich Euch an meine Blutsteinteleporter anpassen. Legt einfach Eure Hände auf den Stein in der hinteren Ecke, dann werdet Ihr vor die Höhle versetzt. Benutzt den Stein draußen, um wieder hinein zu kommen!", sourceObjective = "Stellt euch auf die Blutsteinteleporter in der Schlangenschlinge ein.", completion = "Hervorragend! Ihr habt die einfachste aller Aufgaben bewältigt, ohne zu sterben. Das hätten wir erledigt...", sourceObjectiveStatus = "unverified-source-field" }
quests[26159] = { id = 26159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der erste Schritt", description = "Wie jeder gute Blutmagier wirke ich meine Magie mit Blut. Jedes Blut ist anders. In den Verwüsteten Landen gibt es mehrere nützliche Geschmacksrichtungen, wenn man weiß, wo man suchen muss.\n\nFür unsere Zwecke? Basilisken und Hyänen zu gleichen Teilen. Wir werden viel Blut brauchen. Geht nach Westen ins Herz der Verwüsteten Lande. Und vergesst nicht, den Teleporter zu benutzen!", sourceObjective = "Beschafft 9 Phiolen mit Blut einer Kicherfanghyäne und 9 Phiolen mit Blut eines Rotsteinbasilisken.", progress = "Habt Ihr es?", completion = "<Kasim betrachtet das Blut gierig.>\n\nMehr als genug und immer noch warm! Dann lasst uns das Ritual beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26160] = { id = 26160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutritual", description = "Ihr wollt wahrscheinlich wissen, was wir tun. Hier ist die Kurzfassung - eine Fassung, in der ich Experte bin:\n\nDie Kultisten der Schattenanbeter wollen den Dämon Razelikh beschwören und in die Verwüsteten Lande holen. Das können wir nicht zulassen. Deshalb werden wir ihn selbst beschwören und umbringen. Das klingt leichter als es ist...\n\nLasst mich wissen, wenn Ihr für das Blutritual bereit seid und tretet dann zurück.", sourceObjective = "Sprecht mit Kasim Sharim, um das Blutritual einzuleiten.", completion = "Das Blutritual war ein Erfolg. Ich weiß genau, wohin wir als Nächstes gehen müssen.\n\nTut mir Leid, falsche Formulierung. Ich wollte sagen, ich weiß, wohin IHR als Nächstes gehen müsst...", sourceObjectiveStatus = "unverified-source-field" }
quests[26161] = { id = 26161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht irgendeine Leiche", description = "Wir brauchen Loramus Thalipedes, den Dämonenjäger. Er kennt Razelikhs wahren Namen und wie Ihr wisst, braucht man den Namen eines Dämons, um Macht über ihn zu gewinnen. Das Problem ist nur, dass Loramus getötet und seine Leiche zerrissen wurde.\n\nWenn Ihr mir die Teile bringt, lässt sich noch etwas ausrichten. Alle drei Teile befinden sich im Westen... die Schreckensfelsoger verstecken sie in ihren Höhlen. Beeilt Euch, denn ebenso wie Grimeo, schuldet mir auch Loramus etwas...", sourceObjective = "Findet Loramus' Kopf, Loramus' Torso und Loramus' Beine.", progress = "Vertraut mir... was Loramus zugestoßen ist, lässt sich richten. Die Grenzen der Blutmagie sind noch undefiniert.", completion = "Verstehe... ja, damit kann ich arbeiten.\n\n<Kasim betrachtet den Kopf des Nachtelfen.>\n\nLoramus Thalipedes, Dämonenjäger. Ich freue mich auf unser Wiedersehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26162] = { id = 26162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Altar der Stürme", description = "Auf den Klippen westlich von hier steht ein mächtiger Altar. Ein mächtiger, DÄMONISCHER Altar, der von Kultisten bewacht wird, aber trotzdem mächtig ist. Wenn Ihr ihn erreichen könnt, dann wäret Ihr in der Lage, Loramus zu uns zurückzubringen.\n\nDer Altar wird sich Euch wahrscheinlich widersetzen, deshalb müsst Ihr Loramus' Leichnam bis zur Vollendung des Rituals beschützen. Bringt den Dämonenjäger anschließend zu mir zurück.", sourceObjective = "Bringt Loramus' Leichnam zum Altar der Stürme und beschützt ihn während des Rituals.", completion = "Ihr... Ihr Narr! Was habt Ihr getan?", sourceObjectiveStatus = "unverified-source-field" }
quests[26163] = { id = 26163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zeit ist knapp", description = "Razelikh will in die Verwüsteten Lande zurückkehren und Azeroth mit seinen Dämonen überrennen. Er bereitet bereits die Beschwörung der Legionen vor, die uns vernichten sollen. Mit diesen drei Amuletten können wir ihn zwar beschwören... aber nicht zerstören.\n\n<Der Gnom zeichnet rasch eine Rune in die Luft und reicht sie Euch.>\n\nBringt dies zu Grimeo am Dunklen Portal im Südosten. Er wird Euch führen. Beeilt Euch! Eure Zeit ist knapp bemessen! So wie meine Größe!", sourceObjective = "Bringt die disharmonische Rune zu Behüter Grimeo am Dunklen Portal in den Verwüsteten Landen.", progress = "Kenne ich Euch, guter {race}?", completion = "Nein, nein, nein... nicht wieder Kasim! Das ist Irrsinn!\n\nBitte bleibt ruhig. Wisst Ihr, wie schnell man mich aus der Wache werfen wird, wenn mein Kommandant erfährt, dass ich immer noch für den Kurzen arbeite?\n\n<Ihr gebt Grimeo die Rune. Er presst sie gegen seine Brust, schließt die Augen und seufzt.>\n\nWie ich sehe, sagt Ihr die Wahrheit. Lasst uns rasch beginnen, damit es noch rascher vorüber ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[26164] = { id = 26164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verkohlte Granit des Dunklen Portals", description = "Kasim möchte, dass Ihr Granitsplitter von den Felsen rund um das Dunkle Portal sammelt. Ich weiß nicht, was er mit den Felsen vorhat, aber ich habe einen Verdacht und der ist nicht angenehm.\n\nBenutzt diese Spitzhacke und sucht nach kleinen, zutage getretenen Steinen am Rand des Explosionskraters um das Portal", sourceObjective = "Besorgt 24 verkohlte Granitsplitter.", progress = "Bitte sprecht leise.", completion = "Hoffentlich ist es das, was der Gnom wollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[26165] = { id = 26165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das abscheuliche Blut der Dämonen", description = "Sharim will Dämonenblut. Für mich persönlich sieht das Zeug nicht einmal aus wie Blut - eher wie flüssige Verwesung - aber das ist ohne Belang.\n\nZum Glück für Euch ist das Gebiet um das Dunkle Portal voller Dämonen. Höllenbestien, Teufelshunde und Teufelswachen - sie alle haben das, was Ihr benötigt, in reichlichen Mengen.", sourceObjective = "Besorgt 7 Flaschen mit abscheulichem Dämonenblut.", progress = "Ihh, was stinkt hier so? Seid Ihr das, oder das Blut?", completion = "Ihr habt ohne jeden Zweifel Dämonenblut gefunden.\n\nVon Kasims Bitte einmal abgesehen, bin ich sicher, dass mein Wachkommandant für Eure Bemühungen sehr dankbar ist. Sie haben schon seit einiger Zeit Schwierigkeiten, mit diesen Ablenkungen der Dämonen zurechtzukommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26166] = { id = 26166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbesserung des Steins", description = "<Grimeo packt die letzten Materialien in ein ordentlich umwickeltes Päckchen.>\n\nDas ist alles, was der Gnom von uns verlangt hat. Wenn Ihr ihn seht, sagt ihm bitte, dass meine Schuld mit dieser Aufgabe beglichen ist. Ich werde seine Bitten nicht länger erfüllen.", sourceObjective = "Bringt Grimeos Paket zu Kasim Sharim in der Schlangenschlinge in den Verwüsteten Landen.", progress = "Ihr seid zurückgekehrt, {class}.", completion = "Das wird genügen. Wenn Ihr Grimeo noch einmal seht, sagt ihm, dass er befriedigend gearbeitet hat. Jedoch ist seine Schuld noch nicht getilgt. Ich werde mich an die Arbeit machen und das Steinmesser des Versiegelns herstellen. Jetzt sind Fragen unnötig. Alles wird sich zu seiner Zeit klären.\n\nSolange ich arbeite, habe ich eine andere Aufgabe, die Ihr erledigen könnt.\n\nWas seht Ihr mich so böse an? Diese Aufgabe wird Euch Spaß machen... es geht um das Sammeln von Körperteilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26167] = { id = 26167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Amulett von Allistarj", description = "Um unseren Dämon zu beschwören, brauchen wir drei Amulette. Das erste ist das Amulett von Allistarj.\n\nAllistarj selbst ist tot, aber er hat sein Amulett in einer Schatzgrube in dieser Höhle eingeschlossen. Zusammen mit anderen Amuletten wird dieses Relikt uns Zugang zu Razelikhs Behausung verschaffen.\n\n<Kasim konzentriert sich einen Moment.>\n\nDas Amulett befindet sich nahe des Eingangs. Ich würde vorschlagen, den Teleporter zu benutzen.", sourceObjective = "Besorgt das Amulett von Allistarj aus der Schlangenschlinge in den Verwüsteten Landen.", progress = "Allistarj hat einen Teil seiner selbst in dem Amulett hinterlassen. Sogar jetzt kann ich seine Bosheit spüren.", completion = "<Kasim untersucht das Amulett.>\n\nEr war ein Erzmagier, das spüre ich. Ich werde das Amulett für Euch aufbewahren, während Ihr die anderen sucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26168] = { id = 26168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Amulett von Sevine", description = "Das zweite Amulett, Sevines Amulett, befindet sich weit im Süden in Händen eines Murlocs, auf einer Klippe mit Ausblick über die Havarieküste. Wie es in den Besitz dieses Murlocs gelangt ist, entzieht sich meiner Kenntnis, aber ich kann mit Sicherheit sagen, dass Ihr es dort finden werdet.\n\nBringt mir ihr Amulett, zusammen mit dem Rest.", sourceObjective = "Besorgt das Amulett von Sevine von Salzflopper nahe der Havarieküste in den Verwüsteten Landen.", progress = "Sevines Amulett - zusammen mit den anderen können wir den Entweiher beschwören.", completion = "<Kasim wiegt das Amulett in der Hand.>\n\nEin Hexenmeister... und zwar ein mächtiger. Ich werde das hier behalten, bis die Zeit reif ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[26169] = { id = 26169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Amulett von Grol", description = "Grol... der Oger.\n\n<Kasim lacht.>\n\nGrols Leichnam ruht wohl nicht länger bei den Ogern. Seine Leiche ist zusammen mit seinem Amulett der Macht in einem Schiffswrack vor der Havarieküste im Osten. Sein Amulett ist das letzte - sobald sie vereint sind, werden die drei uns Zugang zu Razelikh gewähren und darin liegt unsere Chance, diesen Wahnsinn zu beenden.", sourceObjective = "Besorgt das Amulett von Grol von der Havarieküste in den Verwüsteten Landen.", progress = "Das dritte Amulett von Razelikhs drittem Hauptmann.", completion = "<Kasim umklammert das dritte Amulett.>\n\nEr war ein mächtiger Krieger. Ich werde das Amulett behalten, bis wir bereit sind, fortzufahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[26170] = { id = 26170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das letzte Ritual", description = "Das Messer ist fertig. Loramus ist anwesend und weiß, was er zu tun hat. Ich werde nun die drei Amulette nehmen und ihre Verzauberung nutzen, um Euch Zugang zu Razelikh, dem Erschaffer des Amuletts, zu verschaffen.\n\nIch bin bereit, dieses Ritual an Euch und Loramus durchzuführen. Sprecht noch einmal mit mir, wenn Ihr beide ebenfalls bereit seid.", sourceObjective = "Sprecht mit Kasim Sharim, um an seinem Ritual teilzunehmen.", completion = "Anscheinend sind wir jetzt bereit, unserem Dämon entgegenzutreten, {name}. Wir haben den Segen des Amuletts, wir haben das Steinmesser und ich allein weiß den wahren Namen des Dämons: Rakh'likh. Zusammen könnte das genügen, den Entweiher zu besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26171] = { id = 26171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr seid Rakh'likh, Dämon", description = "<Held/Heldin>, hört gut zu.\n\nZunächst müssen wir nach Nordwesten zum tödlichen Pförtner reisen, der auf uns am nördlichen Fuß der Anhöhe des Entweihers wartet. Der Pförtner wird uns dann oben auf die Anhöhe schicken. Sobald wir dort sind, brauche ich Eure Hilfe, um Razelikh zu besiegen, denn ich fürchte, dass ich nicht stark genug bin, um ihn alleine zu schlagen.\n\nWas noch wichtiger ist - Ihr müsst das Steinmesser halten und nicht benutzen, bevor ich es Euch sage. Dieses Messer wird Razelikhs Seele in ihrem neuen, ewigen Gefängnis festsetzen.\n\nWenn wir Erfolg haben, sprecht mit Grimeo, dem Draenei.", sourceObjective = "Sprecht mit dem tödlichen Pförtner nördlich der Anhöhe des Entweihers. Wenn Ihr oben auf der Anhöhe angelangt seid, zerstört Razelikhs Körper und benutzt dann das Steinmesser des Versiegelns, um seine Seele gefangen zu nehmen.", completion = "Loramus wiedererweckt? Und dann setzte er den Dämon in seinem eigenen Körper fest.. beim Licht...\n\nIch verstehe. Also hatte Kasim das die ganze Zeit so geplant. Ich hatte den richtigen Verdacht, aber ich denke, ich wollte es nicht glauben.\n\nAh, noch eines! Kasim hat mir eine letzte Anweisung in seiner Rune übermittelt. Anfangs verstand ich sie nicht, aber nach den heutigen Ereignissen ergibt sie wesentlich mehr Sinn:\n\nEr sagte mir, ich solle Euch eins hiervon auswählen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26172] = { id = 26172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auch Blutmagier müssen essen", description = "Entgegen der landläufigen Vorstellung trinken uralte und mächtige Blutmagier KEIN Blut. Wir essen normale Speisen so wie jeder andere auch - etwas, was in der hintersten Ecke einer feindlichen Kultistenfeste schwer zu bekommen ist.\n\nDie Aschmähneneber im zentralen Tal der Verwüsteten Lande sind eine praktische Speise, da man ihr Fleisch nicht kochen muss. Würdet Ihr diese Eber jagen und meine schwindenden Nahrungsvorräte wieder aufstocken?", sourceObjective = "Besorgt 5 Aschmähnensteaks von Aschmähnenebern in den Verwüsteten Landen.", progress = "Ich bin so hungrig! Wenn Ihr Euch nicht beeilt, sehe ich mich doch noch gezwungen, meine Reagenzien zu trinken.", completion = "Die sind perfekt, {name}. Ich werde in den nächsten Tagen gut zu essen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26173] = { id = 26173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückendeckung", description = "Der einzige Grund, warum Ihr mich neben Soldaten der Horde stehen seht, ist der, dass unsere Pflicht unsere Feindschaft überwiegt - wenn auch knapp. Man hat uns die Aufgabe übertragen, das Dunkle Portal vor unerwünschten Reisenden zu schützen. Der kürzlich aufgetretene Kataklysmus hat uns besonders verwundbar für Angriffe gemacht. Wir haben bereits Berichte über schwarze Drachen in der Gegend gehört...\n\nDa meine Leute sich auf ihre Pflichten konzentrieren müssen, brauchen wir jemanden, der die Dämonen im Zaum hält. Um das Portal herum werdet Ihr drei Hauptleute der Dämonen finden. Tötet sie.", sourceObjective = "Tötet Jarroc Flügelriss, Shahandana und Gomegaz.", completion = "Wir wissen Eure Arbeit zu schätzen, Soldat.\n\n<Der Kommandant beugt sich vor und beginnt zu flüstern:>\n\n{race}... Wenn Ihr noch interessiert seid, ich habe da eine kleine Aufgabe für Euch...", sourceObjectiveStatus = "unverified-source-field" }
quests[26174] = { id = 26174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachhut", description = "<Wachkommandant Reldorn Netherschwund schlägt einen verschwörerischen Ton an.>\n\nIch habe Befehle von... oben... für die Ihr bestens geeignet seid. Ich habe gesehen, dass die Horde regelmäßig einen Blick in den Stapel Papiere dort auf dem Fass wirft. Ich möchte, dass Ihr Euch diese Papiere anschaut und herausfindet, was sie vorhaben. Meine Pflicht und mein Posten erlauben mir nicht, solch eine fragwürdige Aufgabe durchzuführen - aber Ihr seid ein Neuankömmling und könntet unbemerkt hineinschlüpfen...", sourceObjective = "Untersucht die Pläne der Horde am Dunklen Portal, ohne erwischt zu werden.", progress = "Habt Ihr einen Blick auf die Pläne erhaschen können, {name}?", completion = "Ihr seid sicher, dass Euch niemand beobachtet hat? Gut.\n\n<Netherschwund hört aufmerksam Eurem Bericht über die Informationen, die Ihr gesehen habt, zu.>\n\nHmpf... ziemlich harmloses Zeugs. Entweder ist die Horde dumm genug, NICHTS gegen uns unternehmen zu wollen... oder sie verstecken ihre Informationen besser, als ich erwartet habe. Wie auch immer - gut gemacht, Soldat.", sourceObjectiveStatus = "unverified-source-field" }
quests[26175] = { id = 26175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surwich", description = "Abgesehen von dem, was Ihr gesehen habt, ist das Portal überraschend ruhig. Leider kann ich Euch kaum noch Arbeit geben.\n\nWenn Ihr nach Ärger sucht, könntet Ihr es im Fischerdorf der Gilneer im Südwesten versuchen. Surwich, so heißt es, glaube ich.\n\nIch weiß, dass wir eigentlich mit den Gilneern befreundet sein sollten, aber mal ehrlich? Worgen? Es fiel mir schon schwer, mich an die Draenei zu gewöhnen.", sourceObjective = "Meldet Euch bei Bürgermeister Carl Connisport in Surwich in den Verwüsteten Landen.", completion = "Willkommen in Surwich, {race}. Seht Euch ruhig um.", sourceObjectiveStatus = "unverified-source-field" }
quests[26176] = { id = 26176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Thelsamar", description = "Ihr habt uns hier sehr geholfen. Falls Ihr aufbrechen wollt, würde ich Euch gerne bitten, diesen Statusbericht nach Thelsamar zu bringen.\n\nFolgt der Straße in Richtung Norden und Ihr könnt es nicht verfehlen. Der Statusbericht muss zu Gebirgsjäger Kadrell.", sourceObjective = "Bringt den Statusbericht von Hauptmann Rugelfuß zu Gebirgsjäger Kadrell in Thelsamar.", progress = "Wie kann ich Euch helfen?", completion = "Gut, dass Ihr Euch um die Troggs gekümmert habt. Dann lasst uns mal den Bericht ansehen und...\n\n...ist das ein Bierfleck?", sourceObjectiveStatus = "unverified-source-field" }
quests[26177] = { id = 26177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lust auf Krebs?", description = "Frische Krabbenbeine waren schon immer eine der Lieblingsspeisen des Königs. Wir hatten in den letzten Wochen viel Erfolg beim Krebsfangen in den Kanälen. Könnt Ihr mir helfen und ein paar für mich fangen? Sie müssen lebendig gefangen werden, tot nützen sie mir nichts - für den König ist nur der frischeste Fang gut genug.", sourceObjective = "Sammelt 6 Kanalkrebse und bringt sie zu Robby Flay in Sturmwind.", progress = "Ihr müsst schnelle Hände haben! Ich kann kaum glauben, dass Ihr alle Krebse in so kurzer Zeit fangen konntet!", completion = "Diese Krebse sehen toll aus! Ich werde sie säubern und sicherstellen, dass der König von Eurer Hilfe erfährt. Danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[26178] = { id = 26178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zukunftsplanungen", description = "Um unser Überleben zu sichern, müssen wir entschlossen gegen die Wolvar vorgehen. Ich mache mir jedoch Sorgen, dass wir in unserem Eifer zu viele von ihnen erschlagen werden.\n\nDie Schneewehenwolvar haben genauso wie wir das Recht zu überleben – also werden wir beide dafür sorgen, dass sie dieses Recht auch bekommen.\n\nWenn er es nicht schon längst getan hat, dann wird Euch Ältester Ko'nani darum bitten, mit den Wolvar fertigzuwerden. Und aus diesem Grund möchte ich auch, dass Ihr ihre Jungen einfangt und sie zu mir bringt, wenn Ihr Euch auf der Lichtung im Norden befindet.", sourceObjective = "Sammelt 12 Schneewehenwelpen und liefert sie anschließend bei Fallensteller Mau'i im Hafen Moa'ki ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[26179] = { id = 26179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Venture Company", description = "Das erklärt auch die Aufstockung von Angestellten und Ausrüstung der Venture Company, die wir in Mulgore gesehen haben. Diese Goblins... ihre Firma wächst viel zu schnell, als dass es gut für sie wäre. Es heißt doch, zeigt man einem Goblin etwas, kann man gleich im Hintergrund die Registrierkasse klingeln hören.\n\nGierige kleine Teufel. Bedauerlich für ihre geschäftlichen Vorhaben, aber wir Tauren können es nicht zulassen, dass sie ihre Arbeiten hier in unserem Land durchführen. Begebt Euch zu ihrer Mine nordöstlich der Überfallenen Karawane und schickt ihnen eine Nachricht.", sourceObjective = "Tötet 7 Tagelöhner der Venture Co. für Morin Wolkenpirscher in der Nähe des Dorfs der Bluthufe.", completion = "Ich glaube nicht, dass man dieses Signal fehldeuten oder ignorieren kann, oder? Die Venture Company wird die {race} nicht mehr auf die leichte Schulter nehmen oder so arrogant sein zu glauben, dass wir ihren Diebstahl der natürlichen Rohstoffe um uns herum einfach so widerstandslos hinnehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26180] = { id = 26180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorsteher Zischelspross", description = "Laut der Dokumente, die Ihr von der Karawane geborgen habt, hat die Venture Company viele Pläne parat, um zu versuchen, uns von unserem Land hier zu vertreiben und damit freie Bahn zur Plünderung des Landes zu haben.\n\nIch bin entsetzt und es stößt mich ab, auf welches Niveau man sich herablassen kann, um seine Ziele durchzusetzen; ich will, dass der führende Kopf hinter ihren Plänen vernichtet wird. Er heißt Vorsteher Zischelspross; Ihr findet ihn in der Mine der Venture Co. östlich der Überfallenen Karawane. Bringt mir sein Klemmbrett, vielleicht finden wir damit ja etwas Nützliches heraus.", sourceObjective = "Tötet Vorsteher Zischelspross und nehmt sein Klemmbrett an Euch.", progress = "Bei dem Gedanken an die Abscheulichkeiten, die die Venture Company im Namen des Gewinns geplant haben, koche ich fast über vor Ärger.", completion = "Die Nachricht vom Tod des Bösewichts Zischelspross hat meine Wut etwas abgekühlt. Ich werde seine persönlichen Habseligkeiten durchsehen, um herauszufinden, ob es weitere Informationen über die Zukunftspläne der Venture Company gibt. Vielen Dank für Eure Bemühungen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26181] = { id = 26181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zur Dämmerbucht", description = "IHR MÜSST ZURÜCK… ZUR… DÄMMERBUCHT. ERUNAK STEINSPRECHER ERWARTET… EUCH DORT.\n\nICH STERBE JETZT...", sourceObjective = "Sprecht mit Erunak Steinsprecher in der Dämmerbucht in Vashj'ir.", completion = "Willkommen zurück, {class}.\n\nIch habe gespürt, wie L'ghorek starb. Es ist eine Schande, dass so ein fantastisches Wesen nicht mehr unter uns weilt.\n\nWenn wir Neptulon nicht unterstützen, wird uns alle das gleiche Schicksal ereilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26182] = { id = 26182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zur Schattenhöhle", description = "IHR MÜSST ZURÜCK… ZUR… SCHATTENHÖHLE. ERUNAK STEINSPRECHER ERWARTET… EUCH DORT.\n\nICH STERBE JETZT...", sourceObjective = "Sprecht mit Erunak Steinsprecher in der Schattenhöhle in Vashj'ir.", completion = "Willkommen zurück, {class}.\n\nIch habe gespürt, wie L'ghorek starb. Es ist eine Schande, dass so ein fantastisches Wesen nicht mehr unter uns weilt.\n\nWenn wir Neptulon nicht unterstützen, wird uns alle das gleiche Schicksal ereilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26183] = { id = 26183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Königs Apfelwein", description = "Ich stehe für immer in der Schuld des Königs. Für alles, was er für uns getan hat. Ich kann ihm nicht viel anbieten, aber sein Lieblingsgetränk kann ich ihm brauen! Glücklicherweise wachsen die Zutaten für dieses köstliche Getränk hier in Sturmwind. In jedem Distrikt stehen Apfelbäume. Die Bäume sind zu hoch, um die Äpfel zu pflücken, aber die, die auf den Boden gefallen sind kann man leicht aufsammeln.", sourceObjective = "Sammelt 12 saftige Äpfel und bringt sie zu Robby Flay in Sturmwind.", progress = "Habt Ihr genug saftige Äpfel finden können?", completion = "Das sind gute Äpfel, {name}. Ich werde mich gleich daran machen, den Apfelwein zu brauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26184] = { id = 26184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wurmdorns Traum", description = "Es wird Euch nicht überraschen, dass die meisten Einwohner von Surwich nicht wegen der angenehmen Atmosphäre in die Verwüsteten Lande gekommen sind. Sie kamen, weil sie dem Traum eines idealistischen Druiden folgten: Marl Wurmdorn. Wurmdorn glaubte, dass die Faulende Narbe geheilt werden könnte und versuchte, sie wachsen zu lassen.\n\nEr hat sich wohl geirrt. Er ließ seinen Wald wachsen, aber das Land wird immer noch von Dämonen heimgesucht und sein großer Baum ist verwachsen und knorrig.\n\nTrotzdem hoffe ich noch. Wenn wir uns in den Besudelten Wald begeben und einen Teil der Besudelung entfernen könnten...", sourceObjective = "Tötet 5 Zerstörer der Verdammniswache, 5 Schreckenslordschänder, 5 verderbte Dunkelwaldtreants und 3 Teufelssporensumpflords im Besudelten Wald.", completion = "Ihr sagt, all die Dämonen hätten den Baum angebetet?\n\n<Der Bürgermeister seufzt.>\n\nWie ich befürchtet hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[26185] = { id = 26185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rat vom Zirkel des Cenarius", description = "Ich glaube, dass die Besudelung der Verwüsteten Lande ihren Einfluss auf meinen Freund Wurmdorn ausgeweitet hat. Sein Experiment ist gescheitert und sein großer Baum dient nur noch den Dämonen als Versammlungsort.\n\nDer Baum muss fallen und Wurmdorn mit ihm. Sprecht mit der cenarischen Beobachterin auf der anderen Seite des Orts. Sie sollte wissen, was als Nächstes zu tun ist.\n\n{name}: Die Einwohner von Surwich dürfen nichts von unseren Plänen erfahren. Ihre Stimmung ist schon schlecht genug.", sourceObjective = "Meldet Euch bei der cenarischen Beobachterin Shayana in Surwich in den Verwüsteten Landen.", completion = "Es überrascht mich zwar, dass Connisport gewillt ist, seinen Plan umzusetzen, aber es erleichtert mich auch. Ich habe gesehen, wie sich die Dämonen um Maldraz versammeln. Ich teile seine Furcht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26186] = { id = 26186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonisches Gefäß", description = "Wir müssen Wurmdorns Aufmerksamkeit erregen. Wir brauchen etwas, das ihn aus seiner Trance holt. Etwas, das garantiert funktioniert.\n\nDie wenigen Wildtierarten, die es geschafft haben, sich im Besudelten Wald anzusiedeln, sind zweifellos von den latenten Energien des Landes in Mitleidenschaft gezogen worden. Eure Aufgabe ist es, ihre Kadaverteile einzusammeln und eine Möglichkeit zu finden, sie in ein Gefäß umzuwandeln. Egal, ob Wurmdorns Trance druidischer oder dämonischer Natur ist, ein Gefäß mit besudeltem Tierfleisch, das groß genug ist, sollte in der Lage sein, diese zu durchbrechen.", sourceObjective = "Tötet besudelte Schwarzbären, besudelte Nachtpirscher und besudelte Kreischer im Besudelten Wald und versucht, ihre Kadaverteile zu einem dämonischen Gefäß zusammenzusetzen.", progress = "Shayanas Plan ist gut. Habt Ihr das Gefäß, {name}?", completion = "<Bürgermeister Carl Connisport blickt voller Argwohn auf das Gerät, dass Ihr zusammengesetzt hab.>\n\nNun gut, {name}. Wir haben, was wir brauchen, um Marls Trance zu durchbrechen und sowohl ihm als auch seinem Experiment ein Ende zu bereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26187] = { id = 26187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fall des Marl Wurmdorn", description = "Wenn sich herumspricht, was wir getan haben... kann niemand sagen, wie die Bürger von Surwich reagieren werden. Sie klammern sich an Wurmdorns Traum...\n\n...aber trotzdem müssen wir es tun. Nehmt das dämonische Gefäß und benutzt es gegen Marl Wurmdorn, um ihn aus seiner Trance zu holen. Kehrt zu mir zurück, wenn er nicht mehr unter uns weilt.", sourceObjective = "Tötet Marl Wurmdorn bei Maldraz in den Verwüsteten Landen. Ihr könnt das dämonische Gefäß benutzen, um ihn aus seiner Trance zu holen.", completion = "Danke, {name}. Ich und die Bürger von Surwich stehen in Eurer Schuld.\n\nNehmt ruhig eins von diesen hier. Wir haben zwar nicht viel, aber wir belohnen gern die, die uns beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26188] = { id = 26188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mazzranach", description = "Mein Großvater erzählte mir Geschichten von seinen Kämpfen gegen einen Schreiter namens Mazzranach. Er erzählte mir von seinen dämonischen roten Augen, seinen rasiermesserscharfen Krallen und seinem giftigen Biss.\n\nWie der Zufall so spielt, stieß ich auf einer meiner Reisen durch die Ebene auf ihn und trug eine üble Bisswunde an meiner Schulter davon. Er war so Furcht erregend, wie ihn mein Großvater beschrieben hatte. Ich habe alle Zutaten für das Gegengift, das ich für meine Heilung benötige, zusammen... bis auf einen Knochen eines Flachlandpumas.\n\nIch werde von Minute zu Minute schwächer... bitte helft mir.", sourceObjective = "Bringt einen Knochen eines Flachlandpumas zu Maur Regenrufer im Dorf der Bluthufe.", progress = "Mein Fieber wird immer schlimmer und ich merke, wie ich langsam in schreckliche Alpträume abgleite... Ich hätte wissen müssen, dass ich keine Bestie bewältigen kann, die selbst mein Großvater nicht besiegen konnte...\n\nHabt Ihr die Zutaten für die Arznei? Ich fürchte, wenn ich die Infektion nicht bald säubere, wird das mein Ende sein.", completion = "Ah, danke, {name}. Mit den Dingen, die Ihr mir gebracht habt, kann ich die Arznei herstellen, mit der ich die Ausbreitung der Infektion unterbinden und die Krankheit endgültig heilen kann. Ich schulde Euch meinen lebenslangen Dank.\n\nAber ich werde nie diesen schrillen Schrei vergessen, als sich Mazzranach auf mich stürzte, diese Explosion von Farben, als sich sein Schnabel senkte...\n\nSeid vorsichtig auf Euren Reisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26189] = { id = 26189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grollhauerbedrohung", description = "Als wir uns hier oben hin zurückzogen, um den Raptoren zu entgehen, landeten wir genau neben jeder Menge Drachenmalorcs!\n\nIn Menethil habe ich Geschichten gehört - dass die Orcs des Drachenmals noch barbarischer als andere Orcs sind, dass sie schwarze Drachen mit bloßen Händen erwürgen... Ich weiß nicht, was davon stimmt, aber wir können sie nicht in den Hügeln sitzen lassen.\n\nIhr habt genug Mut dafür, {name}. Geht nach Osten zum Lager der Grollhauer, kümmert Euch um diese Orcs und vor allem um ihren Anführer!", sourceObjective = "Tötet Gorfax Grollhauer und 16 Orcs des Drachenmals im Lager der Grollhauer.", completion = "Schön, dass Ihr heil zurückgekehrt seid, {name}! Ihr seid ganz schön hart.\n\nIch werde Hauptmann Starkfaust erzählen, wie Ihr die Orcs erledigt habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[26190] = { id = 26190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Fischerschmaus", description = "Wenn der König ein Lieblingsessen hat, dann ist es frischer Wels. Wels ist leicht zuzubereiten aber schwer zu fangen. Genau - hier kommt Ihr ins Spiel. Wir haben in Sturmwind viele gigantische Welse und der Wettbewerb, sie zu fangen, ist sehr intensiv, um es vage zu formulieren. Findet für mich einen Weg, diese feinen Welse für den König zu erhaschen. Ihr werdet am Ufer des Kanals überall in der Stadt Fischer finden. Den Rest des Planes findet Ihr sicherlich selber heraus.", sourceObjective = "Bringt 5 gigantische Welse in Euren Besitz und bringt sie zu Robby Flay in Sturmwind.", progress = "Konntet Ihr den Fisch klauen?", completion = "Ich danke Euch, {name}. Ich werde die Welse sofort für den König entschuppen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26191] = { id = 26191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gipfel unserer Bemühungen", sourceObjective = "Jeden Tag treffen weitere Krieger unter dem Befehl Azsharas ein. Bald wird Neptulon der Gezeitenjäger von unseren Vorbereitungen erfahren, aber dann ist es zu spät um aufzuhalten, was wir in Bewegung gesetzt haben. Wir werden zu viele und unsere Verbündeten zu mächtig sein. Der Sieg ist nur eine Frage der Zeit.\n\nIm Namen Azsharas.", sourceObjectiveStatus = "unverified-source-field" }
quests[26192] = { id = 26192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auch Waisen mögen Kekse!", description = "Die Waisenkinder Sturmwinds werden oft vergessen, aber nicht heute. Der König hat nach einer Sonderlieferung Kekse gefragt, die umgehend zum Waisenhaus geschickt werden soll. Mit der letzten Ladung war ich fast fertig, aber dann ging mir der Puderzucker aus. Könnt Ihr schnell los und mir welchen besorgen? Jeder Gemischtwarenladen in der Stadt oder auch die Gasthäuser sollten welchen haben.", sourceObjective = "Bringt 4 Säcke Puderzucker zu Robby Flay in Sturmwind.", progress = "Konntet Ihr Puderzucker finden?", completion = "Ja, das sollte genug sein, {name}. Ich freue mich schon auf die glücklichen Gesichter der Waisenkinder.", sourceObjectiveStatus = "unverified-source-field" }
quests[26193] = { id = 26193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung des Abgrunds", description = "Das Flüstern der Elemente summt in meinen Gedanken, {name}…\n\nDer Thron der Gezeiten wird belagert!\n\nIch kann nicht tatenlos zusehen, wie die Naga Neptulons Reich bedrohen. Wir müssen einen Weg finden, ihm beizustehen.\n\nKapitän Taylor wird mich in die Tiefen begleiten, wo ich direkt mit Neptulon sprechen kann.\n\nIch muss euch bitten, einen gewalttätigeren Weg einzuschlagen. Lenkt die feindlichen Truppen ab, bis ich sicher am Eingang zum Thron der Gezeiten angelangt bin.\n\nMögen uns die Geister beistehen, {name}.", sourceObjective = "Tötet 15 beliebige Naga beim Wirbelnden Abgrund.", completion = "NEIN!\n\nEs ist NICHT vorbei!", sourceObjectiveStatus = "unverified-source-field" }
quests[26194] = { id = 26194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung des Abgrunds", description = "Das Flüstern der Elemente summt in meinen Gedanken, {name}…\n\nDer Thron der Gezeiten wird belagert!\n\nIch kann nicht tatenlos zusehen, wie die Naga Neptulons Reich bedrohen. Wir müssen einen Weg finden, ihm beizustehen.\n\nNazgrim wird mich in die Tiefen begleiten, wo ich direkt mit Neptulon sprechen kann.\n\nIch muss euch bitten, einen gewalttätigeren Weg einzuschlagen. Lenkt die feindlichen Truppen ab, bis ich sicher am Eingang zum Thron der Gezeiten angelangt bin.\n\nMögen uns die Geister beistehen, {name}.", sourceObjective = "Tötet 15 beliebige Naga beim Wirbelnden Abgrund.", completion = "Sie denken vielleicht, sie hätten gewonnen, aber meine Axt und ich sind da anderer Meinung!", sourceObjectiveStatus = "unverified-source-field" }
quests[26195] = { id = 26195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer hütet den Sumpfhüter", description = "Der Sumpfhüter war eine lokale Legende. Viele hielten ihn für einen Mythos... den Pflanzenmann, Beschützer des Sumpflands. Die Nachtelfen kamen ausschließlich hierher, um ihn zu finden. Als ihnen das gelang, ließen sie sich im Osten nieder.\n\nEs gibt dort einen ganzen Hain, der über den Sumpfhüter wachen soll, und ich habe gehört, dass er den Nachtelfen Probleme macht. Er ist wütend über die Überflutungen und die Schädigung des Landes.\n\nDas sind gute Elfen. Sie könnten Hilfe von jemandem wie Euch brauchen. Wenn sich die Gelegenheit ergibt, dann sagt dem Anführer der Druiden, was Ihr hier getan habt.", sourceObjective = "Sprecht mit Ferilon Laubkind im Hain des Sumpfhüters im Sumpfland.", completion = "Willkommen im Hain des Sumpfhüters, {class}. Es freut mich, dass Whelgar von uns erzählt hat.\n\nFür Eure Unterstützung wäre ich Euch sehr dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[26196] = { id = 26196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Langzopf der Grimmige", description = "Die Zwerge von Dun Modr kämpfen Tag und Nacht gegen die Dunkeleisenzwerge, die in ihre alte Heimat eingedrungen sind. Wir können es zwar unseren Wächtern nicht erlauben, ihr Leben für sie zu riskieren, aber wir schicken ihnen dringend benötigte Vorräte, damit sie ihre Wache fortsetzen können.\n\nWenn es geht, könntet Ihr Langzopf dem Grimmigen nördlich von hier dieses Paket bringen? Seine Leute können den Inhalt sicherlich gut gebrauchen.", sourceObjective = "Bringt Ferilons Überlebenspaket zu Langzopf dem Grimmigen in Dun Modr.", progress = "Oh, was habt Ihr da für mich?", completion = "Vorräte von Ferilon? Guter Mann.\n\nWir haben genug zu essen, aber uns gehen die Kugeln aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[26197] = { id = 26197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zukunft von Gnomeregan", description = "Jeder Überlebende, den wir aus den vergifteten Hallen von Gnomeregan befreien können, ist wie ein Sieg für uns. Kämpfer wie Ihr werden eine wichtige Rolle bei der Zukunft von Gnomeregan spielen. Aus diesem Grund hat unser Herrscher, Hochtüftler Mekkadrill, ein Team von Lehrern zusammengestellt, die Euch helfen werden, Eure Künste zu erlernen.\n\nBipsi Frostschleuder wird Eure Ausbildung und Eure Anpassung an das Leben auf der Oberfläche überwachen. Sie erwartet Euch im Erdgeschoss des großen Gebäudes im Nordosten.", sourceObjective = "Trefft Bipsi Frostschleuder in Neu-Tüftlerstadt.", completion = "{name}, nicht wahr? Schön, Euch endlich kennenzulernen. Während Ihr Euch gesäubert habt, hat mir Nevins Team alles über Eure Flucht aus Gnomeregan erzählt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26198] = { id = 26198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Künste eines Magiers", description = "Während Ihr wilde Abenteuer bestreitet und Eure Kräfte steigert, werdet Ihr neue Verbindungen zum Arkanen knüpfen und neue Zauber erhalten.\n\nIhr werdet es sehen. Los, tut es! Zeigt mir, was Ihr lernt! Ich werde hier sein.", sourceObjective = "Ihr müsst Stufe 3 erreichen, um Frostnova zu erlernen. Wenn Ihr den Zauber gelernt habt, wendet ihn zweimal erfolgreich auf eine Trainingsattrappe in Neu-Tüftlerstadt an.", completion = "Das habt Ihr schnell gelernt. Ich kann es kaum erwarten, Euch meine anderen Lieblingstricks zu zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26199] = { id = 26199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zukunft von Gnomeregan", description = "Jeder Überlebende, den wir aus den vergifteten Hallen von Gnomeregan befreien können, ist ein Sieg für uns. Kämpfer wie Ihr werden eine wichtige Rolle bei der Zukunft von Gnomeregan spielen. Aus diesem Grund hat unser Herrscher, Hochtüftler Mekkadrill ein Team von Lehrern zusammengestellt, die Euch helfen werden, Eure Künste zu erlernen. \n\n\"Doc\" Raddreh wird Eure Ausbildung und Eure Anpassung an das Leben auf der Oberfläche überwachen. Sie erwartet Euch neben der Gebäudeansammlung im Norden.", sourceObjective = "Trefft \"Doc\" Raddreh in Neu-Tüftlerstadt.", completion = "Schön, Euch kennenzulernen, {name}. Eure Zeit in Gnomeregan hat Euch sicherlich ausreichend Gelegenheit verschafft, Eure Künste auszuüben. Hier ist es etwas sicherer, aber Eure Talente werden nie brach liegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26200] = { id = 26200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Künste eines Priesters", description = "Wisst Ihr, wenn Ihr in diese verrückte Welt rausgeht und stärker werdet, werdet Ihr neue Kräfte entdecken, die Ihr vorher noch nicht gekannt habt.\n\nZieht einfach los, sammelt neue Erfahrungen und kommt dann wieder und zeigt mir, was Ihr gelernt habt.", sourceObjective = "Ihr müsst Stufe 3 erreichen, um Schattenwort: Schmerz zu erlernen. Setzt es 5-mal auf Trainingsattrappen in Neu-Tüftlerstadt an.", sourceObjectiveStatus = "unverified-source-field" }
quests[26201] = { id = 26201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht eines Hexenmeisters", description = "Es überrascht mich überhaupt nicht, dass es <einem Hexenmeister/einer Hexenmeisterin> wie Euch gelungen ist, sich den Weg aus Gnomeregan freizukämpfen. Nur Wenige - selbst hier bei den Gnomen - verstehen den vollen Umfang der Macht, die wir ausüben.\n\nWenn Ihr mächtiger werdet, werdet Ihr Stimmen vernehmen, die Euch ihre Geheimnisse verraten und neue Zauber beibringen.\n\nIch möchte, dass Ihr noch mehr Erfahrungen sammelt. Wenn Ihr etwas Neues gelernt habt, zeigt es mir.", sourceObjective = "Ihr müsst Stufe 3 erreichen, um Verderbnis zu erlernen. Wirkt sie dann 5-mal auf eine Trainingsattrappe in Neu-Tüftlerstadt an.", completion = "Wenn Ihr noch mächtiger geworden seid, kehrt zu mir zurück und ich werde Euch neue Zauber und Techniken lehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[26202] = { id = 26202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zukunft von Gnomeregan", description = "Jeder Überlebende, den wir aus den vergifteten Hallen von Gnomeregan befreien können, ist wie ein Sieg für uns. Wir werden all die Hilfe brauchen, die wir kriegen können, um unsere Heimat von den Troggs und den bestrahlten Gnomen zu befreien. Aus diesem Grund hat unser Herrscher, Hochtüftler Mekkadrill ein Team von Lehrern zusammengestellt, die Euch helfen werden, Eure, ähem... Künste zu erlernen.\n\nAlamar Grimm hält sich in dem Gebäude westlich von diesem hier auf. Er besitzt Kräfte, die den Euren gleichen. Er wird Euch helfen, Euch einzugewöhnen.", sourceObjective = "Sucht Alamar Grimm in Neu-Tüftlerstadt auf.", completion = "Ah, wieder einer von Nevins \"geretteten\" Überlebenden, richtig? Wahrscheinlicher ist, dass Ihr ihn vor den Troggs dort unten beschützt habt. Hat seine Stimme gezittert, als er mich erwähnte? Der Mann hat einen gesunden Respekt vor den dämonischen Kräften, die wir kanalisieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[26203] = { id = 26203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zukunft von Gnomeregan", description = "Jeder Überlebende, den wir aus den vergifteten Hallen von Gnomeregan befreien können, ist wie ein Sieg für uns. Kämpfer wie Ihr werden eine wichtige Rolle bei der Zukunft von Gnomeregan spielen. Aus diesem Grund hat unser Herrscher, Hochtüftler Mekkadrill, ein Team von Lehrern zusammengestellt, die Euch helfen werden, Eure Künste zu erlernen.\n\nAusbildungsoffizier Dampfkurbel wird Eure Ausbildung und Eure Anpassung an das Leben auf der Oberfläche überwachen. Er erwartet Euch auf dem kleinen Übungsfeld auf der anderen Straßenseite.", sourceObjective = "Sucht Ausbildungsoffizier Dampfkurbel in Neu-Tüftlerstadt auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[26204] = { id = 26204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Künste eines Kriegers", description = "Lernen ist die beste Methode, um sich zu verbessern. Wenn Ihr mehr lernt, werdet Ihr herausfinden, dass Ihr Dinge tun könnt, die Ihr vorher nicht für möglich gehalten hättet!\n\nLos, sammelt noch mehr Erfahrungen und erlernt eine neue Technik. Kehrt dann zurück und demonstriert sie an einer Trainingsattrappe.", sourceObjective = "Ihr müsst Stufe 3 erreichen, um Sturmangriff zu erlernen. Wendet dann Sturmangriff an einer Trainingsattrappe in Neu-Tüftlerstadt an.", sourceObjectiveStatus = "unverified-source-field" }
quests[26205] = { id = 26205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Aufgabe für den Multi-Bot", description = "Der Multi-Bot wird uns bei all den Aufgaben helfen, die für uns Gnome unangenehm oder gefährlich sind... sollte er funktionieren.\n\nAls Thermadraht seinen Verstrahler am Ende von Operation: Gnomeregan zündete, entstanden giftige Wolken. Giftschlamm begann unter dem alten Flugplatz südlich der Stadt hervorzubrodeln.\n\nWenn wir das nicht unter Kontrolle bekommen, könnte sich die Kontaminierung auf den Rest unseres Landes ausdehnen. Nehmt den Multi-Bot und bringt ihn in die Nähe der Geysire in den grünen Becken auf dem Toxischen Flugplatz. Der Bot sollte automatisch anspringen.", sourceObjective = "Benutzt den GS-9x Multi-Bot, um 5 toxische Geysire auf dem Toxischen Flugplatz zu säubern. Wenn Ihr nahe genug an einen Geysir herangekommen seid, wird der GS-9x Multi-Bot automatisch mit seiner Arbeit beginnen.", completion = "Wow, ich hätte nie gedacht, dass er auf Anhieb funktionieren würde!\n\nÄh, ich meine, wir hatten Erfolg! Ich frage mich, was man sonst noch mit diesem praktischen kleinen Kerl anfangen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[26206] = { id = 26206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zukunft von Gnomeregan", description = "Jeder Überlebende, den wir aus den vergifteten Hallen von Gnomeregan befreien können, ist wie ein Sieg für uns. Kämpfer wie Ihr werden eine wichtige Rolle bei der Zukunft von Gnomeregan spielen. Aus diesem Grund hat unser Herrscher, Hochtüftler Mekkadrill, ein Team von Lehrern zusammengestellt, die Euch helfen werden, Eure Künste zu erlernen.\n\nKelsey Stahlfunken, ein wichtiges Mitglied des Geheimteams Gnomeregan, wird Eure Ausbildung und Eure Anpassung an das Leben auf der Oberfläche überwachen. Ihr findet sie nordwestlich von hier im Ratszelt.", sourceObjective = "Sucht Kelsey Stahlfunken in Neu-Tüftlerstadt auf.", completion = "Schön, Euch kennenzulernen, {name}. Nevin sagte mir, dass Ihr die Gefahren von Gnomeregan durch Euren Verstand überlebt habt. Das ist genau das, was wir hier oben brauchen. Einen klugen Verstand und eine schnelle Klinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[26207] = { id = 26207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Künste eines Schurken", description = "Wenn Ihr weitere Erfahrungen macht und als <Schurke/Schurkin> besser werdet, erlernt Ihr neue Fertigkeiten.\n\nEine der wichtigsten ist das Kombinieren von Techniken. Dabei nutzt Ihr Schwächen Eures Gegners aus und erhaltet die Möglichkeit, stärkere Manöver zu einzusetzen.\n\nZieht los, sammelt weitere Erfahrungen und findet heraus, wie man es macht. Wenn Ihr soweit seid, kommt hierher zurück und probiert es aus.", sourceObjective = "Ihr müsst Stufe 3 erreichen, um Ausweiden zu erlernen. Sucht dann nach einer Trainingsattrappe in Neu-Tüftlerstadt und übt Ausweiden 3-mal.", completion = "Es überrascht mich nicht, dass Ihr so schnell lernt. Ich freue mich darauf, Euch weitere Tricks unserer Zunft beizubringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26208] = { id = 26208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kampf wird fortgesetzt", description = "Die Zwerge von Eisenschmiede nahmen uns freundlicherweise auf, als die Trogginvasion und die Strahlung uns zum ersten Mal zwangen, Gnomeregan zu verlassen. Doch selbst die Hilfsbereitschaft von Freunden, kann das Heimweh nicht unterdrücken.\n\nIch habe um die Hilfe mutiger Gnome und anderer Mitglieder der Allianz gebeten. Gemeinsam wird es uns gelingen, die Kontrolle über Gnomeregan wiederzuerlangen und den Thronräuber Thermadraht ein für alle Mal zu besiegen.\n\nWir konnten mit Operation: Gnomeregan nicht alles erreichen, was wir uns vorgenommen hatten, aber Thermadraht ist auf der Flucht und wir sind unserer Heimat einen Schritt näher.", sourceObjective = "Betrachtet den Holo-Tisch vor Hochtüftler Mekkadrill, um mehr über Operation: Gnomeregan zu erfahren.", progress = "Thermadrahts Untergang ist gewiss, aber dieser Irradiator hat ihm eine Atempause verschafft.", completion = "Im Moment wagen sich nur die Teams von S.I.C.H.E.R. hinunter in die Stadt, um nach Überlebenden zu suchen. Währenddessen hat Thermadraht einen seiner Anhänger, Ritzelstoß, ausgesandt, um uns abzulenken und sich selbst Zeit zu verschaffen, sich einzugraben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26209] = { id = 26209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Mordfall war der Fall, den sie mir gaben", description = "So sieht's aus, <Junge/Mädchen>, wir haben es mit einem ausgewachsenen Mordfall zu tun. Doppelter Homizid... Einfacher Pferd... izit.\n\nUnd was noch schlimmer ist, wir befinden uns hier in Westfall. Hier kann man mit einem einzigen Steinwurf haufenweise Landstreicher erwischen, die ein Motiv gehabt hätten, die Leute (und das Pferd) um die Ecke zu bringen.\n\nIch habe keine Ahnung, wer es war und ich bin ganz bestimmt nicht gerne hier in diesem Loch, um den Tod von ein paar Landbesetzern aufzuklären, aber ich möchte verdammt sein, wenn ich den Täter nicht dingfest machen kann. Ihr wollt helfen? Dann sprecht mit den Landstreichern. Die Vagabunden... kriegen alles mit.", sourceObjective = "Sprecht mit den verschiedenen Obdachlosen, die auf Jansens Hof leben, um Hinweise über die Brauenwirbelmorde zu sammeln.", progress = "Schon was herausgefunden?", completion = "Gnolle und Murlocs? Reiner Pferdemist, mein Junge! Das waren keine Gnolle oder Murlocs. Ich habe gesehen, was Gnolle und Murlocs mit ihren Opfern machen, und so ... sieht das nicht aus. Zu hübsch. Zu... perfekt.\n\nAußerdem haben die Brauenwirbels fünf Jahre lang auf diesem Gehöft gehockt. Nein, wer auch immer sie umgebracht hat, hatte einen Grund. Das hier ist Mord, ganz einfach, und wir werden der Sache auf den Grund gehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[26210] = { id = 26210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gammerita, Alter!", description = "Yo! Da is ne Schildkröte da draußen, die nicht wie die anderen is'. Das is' die Gammerita, Anführerin der Salzwasserschnappkiefer, 'ne richtig fiese Diebin!\n\nAlter, die hat mir meinen besten Köder geklaut. Einfach so abgebissen, hatse den! Seitdem beißen die Fisch nichmehr so an wie vorher.\n\nFinde Gammerita und hol' mir den Köder aus ihrem Bauch.", sourceObjective = "Katoom, der Angler aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr Gammerita tötet und Katooms besten Köder aus ihrem Kadaver holt.\n\nKatoom meinte, dass Gammerita sich an der Küste bei den anderen Schildkröten aufhält.", progress = "Haste ihn gefunden?", completion = "ALTER! Das ist fantastisch! Mit meinem besten Köder und ohne die Schnappkiefern da, kommen die Fische sicher in Scharen zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[26211] = { id = 26211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnappkiefer, Alter!", description = "Lasst Euch ja nicht von ihren großen Augen täuschen, Alter! Die Schnappkiefer da sind ne Bedrohung. Ich kann nicht mal für fünf Minuten angeln, ohne dass einer von diesen überdimensionalen Fisch-Staubsaugern mir meinen Köder klaut.\n\nTut mir und den Bruchhauern einen Gefallen und bringt sie um, Alter.\n\nBringt sie alle um!", sourceObjective = "Katoom der Angler aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr 10 Salzwasserschnappkiefer tötet. Kehrt zu ihm zurück, sobald Ihr Eure Aufgabe erledigt habt.", completion = "Mensch Alter! Ich kann Euch nicht genug danken! Hoffentlich ist diese Angelrute hier gut genug als Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[26212] = { id = 26212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lards vergessene Brotzeit", description = "Lard Picknick gemacht hat, an geheimen Geheimplatz, als hässlicher, fieser Blutfratzentroll Lard mit großem Stock geschlagen hat. Lard zurück ins Dorf der Bruchhauer gerannt sein, aber Lard Brotzeit vergessen hat. Lard hungrig. Ihr vielleicht zurück gehen zu geheimen Geheimplatz und holen Brotzeit von Lard? Lard hat Angst. Gehen Norden! Insel dort im Norden seien geheimer Geheimplatz.", sourceObjective = "Lard aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr Lards Brotzeit wieder findet. Kehrt nach Erfüllung dieser Aufgabe zu ihm zurück.\n\nLard erwähnte, dass er es auf der Insel im Norden vergessen habe. Achtet auf die Trolle der Blutfratzen.", progress = "<Lard streicht sich über seinen riesigen Bauch.>\n\nLard so hungrig.", completion = "<Lard nimmt die riesige Fleischkeule von Euch und stopft sie sich in den Mund.>\n\nErste Sahne! Schön'n Dank.\n\nLard Euch machen tollen Picknickkorb für helfen Lard.", sourceObjectiveStatus = "unverified-source-field" }
quests[26213] = { id = 26213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf heißer Spur: Der Flusspfotenklan", description = "Da wir keine anderen Anhaltspunkte haben, können wir genauso gut auch den Informationen nachgehen, die Ihr erhalten habt.\n\nEs gibt einige Lager der Flusspfotengnolle hier in der Nähe. Macht sie ausfindig und sucht nach Hinweisen. Bringt mir was Ihr finden könnt. Beschränkt Eure Suche auf die Gnolle und die Späher der Flusspfoten.", sourceObjective = "Erhaltet den Hinweis der Flusspfotengnolle.", progress = "Habt Ihr etwas über die Gnolle herausgefunden?", completion = "Soll das so eine Art Witz sein? Ich lache nämlich nicht. Fetzen von rotem Stoff? Was zur Hölle soll das denn heißen?", sourceObjectiveStatus = "unverified-source-field" }
quests[26214] = { id = 26214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Spur: Murlocs", description = "Egal für wie sinnlos ich diese Sache halte, wir müssen allen unseren Anhaltspunkten auf den Grund gehen.\n\nIch möchte, dass Ihr Euch hinaus zur Endlosen Küste begebt und den Murlocs dort ein wenig einheizt. Versucht einen Hinweis oder Informationen aufzuspüren, die etwas Licht in diesen Mordfall bringen können.\n\nKehrt zu mir zurück, falls Ihr Erfolg habt.", sourceObjective = "Findet den Murlochinweis.", progress = "Wie läuft die Murlocjagd?", completion = "Na klasse. Ich glaube, davon habe ich einen ganzen Stapel auf meinem Schreibtisch im Wachhaus. Wir stehen also wieder ganz am Anfang. Was wissen wir? Jemand, der gern Geschichten über die Vergangenheit schreibt hat den Brauenwirbels einen Brief geschickt.\n\nWir stecken anscheinend mitten in einer Geschichts...geschichte.", sourceObjectiveStatus = "unverified-source-field" }
quests[26215] = { id = 26215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Treffen mit Lou Zweischuh", description = "Anscheinend haben wir hier einen echten Fall, Grünschnabel. Leider wollen die Anwohner offenbar nicht reden und die Anhaltspunkte, die Ihr von den Gnollen und Murlocs gewonnen habt, sind so gut wie wertlos. Wir müssen auf Plan... \"Haltet nach Lou Zweischuh Ausschau\" zurückgreifen.\n\nLou Zweischuh ist ein alter Informant von mir, der sich auf dem alten Kürbishof der Brauenwirbels niedergelassen hat. Geht nach Westen zu dem Gehöft und findet heraus, was Lou weiß.\n\nFalls er Euch irgendwelchen Mumpitz erzählt, sagt ihm, dass Horatio Euch schickt.", sourceObjective = "Sprecht mit Lou Zweischuh auf Brauenwirbels Kürbishof in Westfall.", completion = "Ganz ehrlich, wir haben einfach keinen Platz mehr für...\n\nHoratio schickt Euch? Na gut... ähm, wie kann ich Euch denn helfen?\n\nEr is' doch nich' hier, oder? Haha, er weiß doch sicher, dass ich mich nich' vor ihm versteckt hab. Hab mich nur für ein Weilchen bedeckt gehalten, versteht Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[26219] = { id = 26219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kreis schließt sich", description = "Wir haben die Bestie gefunden, die unsere Schiffe zerstört hat. Sie hat Ihr Nest in der Dämmerbucht, einer riesigen Unterwasserhöhle am Rand des Abgrunds.\n\nDieses Mal sind wir bereit. Die Gnome haben in Sturmwind eine wahre Schönheit für uns gebaut. Sie steckt so voller Feuerkraft, dass das Scheusal sich in die Hosen machen wird vor Angst.\n\nWenn die Zange X2 an das Schiff andockt, begebt Euch an Bord und schaut, wie Ihr helfen könnt. Wir sind direkt hinter Euch.", sourceObjective = "Geht von der Voldrins Mut aus an Bord der Zange X2 und helft dabei, Dämmerbucht zu sichern.", completion = "Gut gemacht, Gefreiter {name}.\n\nDie Chöhle ist unser, aber die Bestie ist entkommen. Wenn sie ihren chässlichen Kopf wieder zeigt, wir werden sie aus dem Wjasser sprengen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26220] = { id = 26220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speck macht alles besser", description = "Eine Armee hungriger Orcs zu füttern ist nie einfach. Wir haben hier glücklicherweise gute Vorräte an Fleisch von ausgewachsenen Schweinen von den Schweinehöfen südlich von Orgrimmar. Tut mir einen Gefallen und schlachtet ein paar dieser Schweine für ihre köstlichen Schweinebäuche. Ich werde sie schneiden und gebratenen Speck für das Frühstück der Truppen vorbereiten.", sourceObjective = "Schlachtet einige der ausgewachsenen Schweine südlich von Orgrimmar und bringt mir 6 Schweinebäuche. Ich werde hier in der Gasse auf Euch warten.", progress = "Habt Ihr die Schweine schon geschlachtet?", completion = "Gute Arbeit, {name}. Das wird köstlicher Speck.", sourceObjectiveStatus = "unverified-source-field" }
quests[26221] = { id = 26221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kreis schließt sich", description = "Wir haben die Bestie gefunden, die unsere Schiffe zerstört hat. Sie hat ihr Nest in der Schattenhöhle, einer riesigen Unterwasserhöhle im Wirbelnden Abgrund.\n\nDieses Mal sind wir bereit. Die Goblins haben sich als wertvolle Verbündete erwiesen und im Bilgewasserhafen eine bösartige Maschine für uns gebaut. Sie steckt so voller Feuerkraft, dass das Scheusal sich in die Hosen machen wird vor Angst.\n\nWenn die Verne an das Schiff andockt, begebt Euch an Bord und schaut, wie Ihr helfen könnt. Wir sind direkt hinter Euch.", sourceObjective = "Geht von der Höllenjuwel aus an Bord der Verne und helft dabei, die Schattenhöhle zu sichern.", completion = "Gut gemacht, {class}.\n\nDieses glitschige Vieh ist entkommen! Ich werde ein paar Verbesserungen vornehmen. Nächstes Mal hat es nicht so viel Glück.", sourceObjectiveStatus = "unverified-source-field" }
quests[26222] = { id = 26222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteilte Teile", description = "Es gibt so viel zu tun und so wenige Gnome, die in der Lage sind, mir zu helfen! Der Hochtüftler hat mich gebeten, einige alte Bots und Teile der Operation: Gnomeregan auszuschlachten. Mit ein wenig Glück kann ich eine neue Reihe Multi-Bots demnächst in der Praxis testen!\n\nHättet Ihr vielleicht Zeit, um mir zu helfen? Es liegen alle möglichen Teile hier herum. Hebt alles auf, was Ihr findet, und bringt es mir. Wer weiß, was sich davon als nützlich erweist!", sourceObjective = "Bringt 7 Ersatzteile zu Ingenieur Schleiffunke in Neu-Tüftlerstadt.", progress = "Habt Ihr die Teile bekommen?", completion = "Die sind phantastisch! Mal sehen, was sich daraus basteln lässt. Hättet Ihr Interesse daran, den Prototyp zu testen, wenn ich fertig bin?", sourceObjectiveStatus = "unverified-source-field" }
quests[26223] = { id = 26223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pirsch auf die Pirscher", description = "Viele mutige Trolle sind in der Wildnis von Hinterland verlorengegangen. Die Silbermähnenwölfe sind unseren Jägern die größte Gefahr. Sie lauern versteckt zwischen den Büschen und der Landschaft und greifen an, wenn es eine gute Gelegenheit gibt.\n\nWildheit dieser Art kann nicht ungestraft davonkommen!\n\nIhr müsst denken wie ein Silbermähnenwolf. Ihr müsst ihnen auflauern. Ihr müsst sie alle töten!", sourceObjective = "Tötet 8 Silbermähnenpirscher.", completion = "Gute Arbeit, {name}. Die Bruchhauer sind für Eure Hilfe sehr dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[26224] = { id = 26224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagt die Wilden", description = "Unter all den bösartigen Tieren der Wildnis des Hinterlandes, sind auch die Eulenbestien zu finden. Schon so manche gute Krieger der Bruchhauer verloren wir an die grausamen Krallen und die Schnäbel der Biester.\n\nTötet jede wilde Eulenbestie, die Ihr finden könnt, {race}. Kehrt zu mir zurück, sobald Ihr von dem Blutbad genug habt. Euer Beitrag wird dann genau gewogen, abgemessen und bewertet.", sourceObjective = "Tötet 10 Wilde Eulenbestien.", completion = "Ihr habt Euch als ein wahrer Verbündeter der Bruchhauer erwiesen, {name}. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26225] = { id = 26225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pupellyverbos' Portwein", description = "Ihr da! Wusstet Ihr, dass am Strand nördlich von hier dutzende Flaschen, wenn nicht hunderte Flaschen feinen Weins angeschwemmt wurden?\n\n...nun, jetzt wisst Ihr es!\n\nIch würde so viele nehmen, wie ich mit beiden Armen packen kann, wenn die Schildkröten nicht immer hinter mir her wären. Ich könnte schwören, sie wollen mein Blut!\n\nDa bezahle ich Euch doch lieber. Bringt mir 12 Flaschen Pupellyverbos' Portwein und ich werde ihn Euch \"abkaufen\", {class}.", sourceObjective = "Sammelt 12 Flaschen Pupellyverbos' Portwein.", progress = "Habt Ihr zwölf Flaschen? Zählen kann ich, keine Sorge!", completion = "Wunderbar. Ich wüsste nicht, wo ich das Zeug herkriegen würde, wenn nicht immer wieder betrunkene Menschen mit ihren Schiffen aufliefen.\n\nNormalerweise würde ich auch erstmal mit Euch feilschen, aber Ihr habt Glück, denn ich kann es kaum erwarten, mir ein Schlückchen zu genehmigen. Prost!", sourceObjectiveStatus = "unverified-source-field" }
quests[26226] = { id = 26226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flusskrebs à la Créole", description = "Um Orgrimmar herum befinden sich mehrere kleine Seen. In den Seen wimmelt es jedes Jahr von Flusskrebsen. Hier kommt Ihr ins Spiel, {name}. Ihr müsst für mich diese köstlichen Krustentiere fangen und sie mir bringen, wenn Ihr fertig seid. Wenn Ihr erfolgreich seid, wird unsere Armee heute abend ein Festmahl genießen.", sourceObjective = "Fangt 10 schlammige Flusskrebse in Orgrimmar und bringt die Krustentiere zu Marogg, wenn Ihr fertig seid.", progress = "Konntet Ihr ein paar Flusskrebse fangen?", completion = "Uff, gerne gekocht habe ich diese schleimigen Dinger nie. Danke für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26227] = { id = 26227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Achtung, die Frucht beißt zurück!", description = "Manchmal wollen unsere Streitkräfte auch etwas Süßes. Ich geben ihnen nicht immer, was sie wollen, aber heute werde ich eine Ausnahme machen. Sicherlich habt Ihr schon die einheimischen Kakteen gesehen, die in Orgrimmar wachsen. Die Kakteen tragen eine sehr leckere Delikatesse, die Kaktusfeigenfrucht. Das Problem ist, dass die Frucht voller Kaktusnadeln ist! Passt auf Eure Hände auf und bringt mir ein paar Früchte.", sourceObjective = "Sammelt 8 Kaktusfeigen und bringt sie zu Marogg in Orgrimmar.", progress = "Konntet Ihr genug Früchte finden?", completion = "Lasst mich Eure Hände sehen... aha! Ihr seid beim Pflücken dieser Frucht auch nicht besser als ich!", sourceObjectiveStatus = "unverified-source-field" }
quests[26228] = { id = 26228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie die Made im Speck", description = "Hört zu, eigentlich sollte ich gar nich' mit Euch reden, aber ich schulde Horatio den einen oder anderen Gefallen. Ich weiß eigenlich gar nichts darüber, was mit den Brauenwirbels passiert is', aber vielleicht kann ich Euch trotzdem weiterhelfen.\n\n<Lou reicht Euch eine große Kiste.>\n\nDiese Kiste war mein Zuhause, bevor ich reich geworden bin. Jetzt führ' ich ein Leben, von dem jeder Landstreicher träumt!\n\nAlso, Ihr schnappt Euch jetzt mal diese Wohnkiste hier und macht Euch auf zum Jangoschacht südwestlich von hier. Dringt bis ans Ende der Mine vor und versteckt Euch dort in der Kiste.", sourceObjective = "Benutzt Lou Zweischuhs altes Haus am Ende des Jangoschachtes in Westfall.", progress = "Seid mit meinem alten Haus schön vorsichtig. Das will ich meinen Kindern vermachen, wenn sie ausziehen.", completion = "<Lou hält sich die Ohren zu und fängt an, laut zu sprechen.>\n\nHALT! HALT! HALT! Ich will's gar nich' hören! Ich will's nich' wissen und egal is' es mir auch! Solche Informationen können einen in der Gegend hier das Leben kosten.\n\nEins kann ich Euch noch verraten und das war's dann!", sourceObjectiveStatus = "unverified-source-field" }
quests[26229] = { id = 26229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Ich NEHMEN Kerze!\"", description = "Bevor diese verdammten Kobolde mir mein Hinkebein verpasst haben, war ich William Pestles bester Kerzenlieferant. Von mir kommt sogar der Ausspruch \"ICH NEHMEN KERZE!\" Jep, das war ich. Die Kobolde haben immer gerufen \"Du nicht nehmen Kerze!\" und ich hab geantwortet \"ICH NEHMEN KERZE!\" und ihnen den Schädel eingeschlagen!\n\n<Jimb träumt einen Moment lang.>\n\nDas waren gute Zeiten... Die besten Zeiten.\n\nUnd jetzt? Ich kann noch nicht mal ohne Hilfe auf die Toilette gehen. Wollt Ihr mir helfen? Tötet ein paar Kobolde für mich. Ihr solltet einen ganzen Haufen von denen in der Mine hier in der Nähe finden.", sourceObjective = "Tötet 12 Koboldbuddler.", completion = "Ah, SÜSSE Gerechtigkeit! Diese Kobolde abzuschlachten wird mich nicht dazu bringen, wieder wie ein normaler Mensch zu laufen, und es wird mir auch mit Sicherheit keine Arbeit einbringen, aber es tut auf jeden Fall verdammt gut.\n\n<Jimb greift in einen schmutzigen, alten Beutel.>\n\nHier, ich habe da etwas für Euch aus meiner Zeit als Koboldjäger. Vielleicht könnt Ihr damit etwas anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26230] = { id = 26230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festmahl oder Hungersnot", description = "Das Leben in Westfall ist schwer, <Söhnchen/Mädchen>! Jeder Tag ist ein Kampf. Manchmal vergehen Wochen zwischen anständigen Mahlzeiten. Deswegen ist es so wichtig, dass wir uns gegenseitig beistehen. Vielleicht könnt Ihr ja mit anpacken, hm? Ich backe Matschkuchen und benötige noch ein paar Zutaten.\n\nBesorgt mir etwas frischen Matsch vom Kürbisbeet vor dem Haus und ein paar Kojotenschwänze. Ihr könnt überall in der Wildnis von Westfall Kojoten finden.\n\nAn die Arbeit! Wir haben Mägen zu füllen.", sourceObjective = "Sammelt 6 Kojotenschwänze und 5 Handvoll frischen Matsch.", progress = "Matschkuchen backen sich nicht von selbst - normalerweise.", completion = "Mir knurrt schon der Magen, wenn ich Euch nur rieche! Wir werden heut' Abend fürstlich essen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26232] = { id = 26232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lous Abschiedsworte", description = "So ein paar Rohlinge sind vor kurzem auf dem Gehöft aufgetaucht und haben 'ne Menge Ärger verursacht. Keine Ahnung, wo die herkommen oder für wen die arbeiten, aber ich bin mir SICHER, dass sie nichts Gutes im Schilde führen. Ich hab' sie vielleicht über so ein paar Dinge sprechen hören, die Euch interessieren könnten.\n\nWenn Ihr Interesse habt, findet ihr die Rohlinge hinter'm Bauernhaus. Wenn man Euch ertappt oder umbringt, ich weiß nichts von Euch. Hab Euch noch nie im Leben gesehen!\n\nViel Glück, <Junge/Mädel>.", sourceObjective = "Belauscht die Rohlinge hinter dem Bauernhaus auf Brauenwirbels Kürbishof in Westfall.", completion = "Wir haben es hier mit einer Organisation zu tun, Grünschnabel. Niemand bringt so einfach am helllichten Tage den reichsten Landstreicher von Westfall um, ohne dabei Zeugen zu hinterlassen. Hinter diesen Morden steckt jemand mit einer Menge Macht. Was habt Ihr bisher in Erfahrung bringen können?", sourceObjectiveStatus = "unverified-source-field" }
quests[26233] = { id = 26233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus den eigenen Reihen stehlen", description = "Wie Ihr wisst, {name}, hat Garrosh die Trolle von Orgrimmar in die westlichen Außengebiete der Stadt befehligt. Zu unserem Glück bedeutet das, dass wir leicht an ihre Vorräte kommen. Ich bereite gerade eine große Portion Jambalaya für die Infanterie vor und brauche so viel Reis, wie ich bekommen kann. Die Trolle lagern Reis in den Fässern in der Nähe ihrer Behausungen. Bringt mir die Fässer mit Dunkelspeerreis und ich kann das Gericht fertigstellen.", sourceObjective = "Bringt 6 Fässer mit Dunkelspeerreis in Euren Besitz und bringt sie zu Marogg in Orgrimmar.", progress = "Konntet Ihr den Reis besorgen?", completion = "Ihr habt auch Talent im Stehlen, wie ich sehe, {name}. Sorgt Euch nicht, wir werden den Reis zurückbringen, wenn wir fertig sind... oder auch nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26234] = { id = 26234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus den eigenen Reihen stehlen", description = "Wie Ihr wisst, {name}, hat Garrosh die Goblins von Orgrimmar in die westlichen Außengebiete der Stadt befehligt. Zu unserem Glück bedeutet das, dass wir leicht an ihre Vorräte kommen. Ich bereite gerade eine große Portion Jambalaya für die Infanterie vor und brauche so viel Reis, wie ich bekommen kann. Die Goblins lagern Reis in den Fässern in der Nähe ihrer Behausungen. Bringt mir die Fässer mit Kezanreis und ich kann das Gericht fertigstellen.", sourceObjective = "Bringt 6 Fässer mit Kezanreis in Euren Besitz und bringt sie zu Marogg in Orgrimmar.", progress = "Konntet Ihr den Reis besorgen?", completion = "Ihr habt auch Talent im Stehlen, wie ich sehe, {name}. Sorgt Euch nicht, wir werden den Reis zurückbringen, wenn wir fertig sind... oder auch nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26235] = { id = 26235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auch Diebe bekommen Hunger", description = "Seit ein paar Wochen haben wir hier in Orgrimmar Probleme mit Dieben, die die Rationen der Infanterie stehlen. Vor Kurzem habe ich Informationen darüber erhalten, wo diese Diebstähle stattfinden. Wenn Ihr irgendwo Kisten und Vorräte seht, könnt Ihr davon ausgehen, dass die Diebe nicht weit sind. Ich möchte, dass Ihr diese Diebe ausfindig macht und die gestohlenen Rationen findet. Kehrt zu mir zurück, wenn Ihr fertig seid.", sourceObjective = "Findet 3 Infanterierationen der Horde und bringt sie zu Marogg in Orgrimmar.", progress = "Konntet Ihr die Rationen finden?", completion = "Gute Arbeit, {name}! Ich werde dafür sorgen, dass die Rationen umgehend wieder zu unseren Truppen kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26236] = { id = 26236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vernehmung der Saldeans", description = "Was wissen wir also bisher? Wir müssen unseren Anhaltspunkten folgen.\n\nDrüben auf Jansens Hof habt Ihr einen durchnässten Brief und ein paar rote Stofffetzen gefunden. Hier auf dem Hof der Brauenwirbels habt Ihr ein Gespräch zwischen einer merkwürdigen Gestalt und einem Ogermagier belauscht. Ihr habt außerdem die Geständnisse von ein paar Schlägern, den Mord begangen zu haben - woraufhin Ihr die Schläger getötet habt.\n\nDa passt Einiges nicht zusammen, Grünschnabel.\n\nSüdöstlich von hier lebt ein älteres Ehepaar auf Saldeans Hof. Macht Euch auf den Weg dorthin und sprecht mit Bauer Saldean. Findet heraus, was er weiß.", sourceObjective = "Sprecht mit Bauer Saldean auf Saldeans Hof in Westfall.", completion = "Horatio Laine? Der Mann ist ein Drecksack. So dreckig wie meine Unterwäsche.\n\nHört zu, mein Freund, ich erteile nicht oft solche Ratschläge, aber Ihr scheint mir ein aufrichtiger Mann zu sein. VERSCHWINDET AUS WESTFALL. Ihr steckt schon bis über beide Ohren im Mist. Was Ihr da gerade macht ist so, als würdet Ihr Euren Kopf unter's Beil legen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26237] = { id = 26237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zeiten sind schwer", description = "Das sind schwere Zeiten, <Bruder/Schwester>. Da jetzt die geknechteten Massen aus Sturmwind hierher nach Westfall auswandern, sind unsere Vorräte knapper denn je. Das Volk ist unruhig und braucht Hilfe.\n\nUnser Farmhaus dient schon seit Jahren als Behelfsunterkunft. Salma gibt sich alle Mühe, unsere Gäste am Leben zu erhalten, aber manchmal werden sie von den Erntebehütern erwischt. Das sind diese missratenen Ungetüme, die sich auf meinem Feld herumtreiben - ein kleines Geschenk, das die Defias zurückgelassen haben, als sie vertrieben wurden. Helft uns!", sourceObjective = "Tötet 10 Erntebehüter.", completion = "Danke, Bruder. Ihr habt Salma und mir einen großen Dienst erwiesen und ich verspreche Euch, dass wir das so schnell nicht vergessen werden. Viel Geld habe ich nicht, aber Ihr könnt Euch gern an dem bisschen bedienen, das ich habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[26238] = { id = 26238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die wilden Zwerge", description = "Die Horde hat für uns Bruchhauer viel getan und Trittbrettfahrer sind wir sicherlich nicht. Die anderen Waldtrollstämme wurden zurückgedrängt und wir sind dabei, im Namen der Horde neue Ländereien zu sichern.\n\nJetzt sind uns aber die Wildhammerzwerge in den Weg gekommen. Wenn sie Krieg wollen, so werden sie Krieg bekommen... und ich habe nicht vor, einen Krieg gegen jemanden zu verlieren, der nur halb so groß ist wie ich.\n\nGeht los und tötet ein paar Zwerge für mich.", sourceObjective = "Tötet 10 Krieger der Wildhämmer oder Schamanen der Wildhämmer.", completion = "Das wird den Wildhammerzwergen klar machen, dass sie auf unseren Ländereien nichts zu suchen haben!\n\nDie verrückten Zwerge hätten einfach in den Bergen bleiben sollen...", sourceObjectiveStatus = "unverified-source-field" }
quests[26240] = { id = 26240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Takt", description = "Unsere Krieger kämpfen hart, um die üblen Wildhammerzwerge auszuschalten, damit wir hier im Dorf wieder in Sicherheit sind. Wir müssen tun, was wir können, um sie zu unterstützen.\n\nEs gibt etwas, das bei jedem Troll seine besten Kampfkünste herauskommen lässt: der hämmernde Rhythmus der Trommeln lässt sie fester zuschlagen und ruft die Geister dazu auf, über die Krieger zu wachen. Nehmt meine Trommeln mit auf das Schlachtfeld. Spielt sie für unsere Krieger und zeigt den Wildhammerzwergen, wem dieses Land gehört!", sourceObjective = "Spielt die Kriegstrommeln der Bruchhauer für 6 Krieger der Bruchhauer.", completion = "Es macht einen großen Unterschied, nicht wahr? Das wird diesen Zwergen eine Lektion erteilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26241] = { id = 26241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Westfalleintopf", description = "Hallo, <mein Lieber/meine Liebe>. Willkommen in unserem Zuhause. Hmm, Ihr seht aber nicht aus, als ob Ihr obdachlos wärt. Seid Ihr hier, um uns zu helfen? Wenn das so ist, dann kommt Ihr gerade rechtzeitig! Ich plane ein Abendessen für die Kinder und ich brauche ein paar einfache Zutaten.\n\nWenn Ihr mir ein paar Okraschoten, Geiferzahnflanken und sehniges Fleischreißerfleisch bringt, kann ich meinen berühmten Westfalleintopf zubereiten. Ihr könnt all diese Zutaten in der Nähe unserer Farm finden. Nehmt Euch nur vor den Erntebehütern in Acht. Das sind gnadenlose Vernichtungsmaschinen.", sourceObjective = "Sammelt 6 Okraschoten, 6 Stück sehniges Fleischreißerfleisch und 6 Geiferzahnflanken.", progress = "Das Essen ist fertig, sobald ich alle Zutaten habe. Beeilt Euch!", completion = "Seid gesegnet, mein Lieber. Diese armen Waisen haben schon seit Tagen keine warme Mahlzeit mehr bekommen.\n\nEs sieht so aus, als hätten wir genug übrig, um noch viele weitere Obdachlose Westfalls zu versorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26243] = { id = 26243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Weltensäule", description = "Die Säule in diesem Zimmer stützt mehr als nur den Tempel der Erde.\n\nDiese gesamte Existenzebene stürzt bald in unsere Welt, wenn wir sie nicht wieder aufbauen.\n\nEs ist schon bald Zeit zu handeln. {name}. Aber zunächst müsst Ihr Euch anhören, was ich Euch zu sagen habe.", sourceObjective = "Befragt Maruut Steinbinder zur Weltensäule.", sourceObjectiveStatus = "unverified-source-field" }
quests[26244] = { id = 26244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erde nimmt sich alles", description = "Wir befinden uns auf der Ebene der Erde, {name}. Nach und nach wird das Land alles in sich aufnehmen.\n\nDie Sturmfuror wird bald nichts als Staub sein. Dann können wir keine Erkenntnisse aus ihren Resten mehr gewinnen.\n\nGeht und vernichtet die Elementare, die das Schiff auseinandernehmen. Wir zögern das Unvermeidliche nur heraus, aber wir müssen uns etwas Zeit verschaffen, wenn wir alle Teile der Weltensäule finden wollen.", sourceObjective = "Vernichtet 5 Tiefensteinelementare.", completion = "Ihr habt getan, was notwendig war, {name}. Ich merke schon, dass Ihr genau die Sorte {class} seid, mit der es sich gut leben lässt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26245] = { id = 26245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luftschiff am Boden", description = "Der Abschlussstein wurde in einem Luftschiff der Horde namens Sturmfuror transportiert.\n\nDas Luftschiff ist südlich von hier abgestürzt. Laut unseren Untersuchungen befindet sich der Abschlussstein nicht mehr an Bord.\n\nDurchsucht das Schiff nach Hinweisen darauf, was passiert sein könnte.", sourceObjective = "Sucht im Wrack der Sturmfuror in Tiefenheim nach Hinweisen.", completion = "Die Hinweise deuten auf das Offensichtliche. Vielleicht zu offensichtlich…", sourceObjectiveStatus = "unverified-source-field" }
quests[26246] = { id = 26246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Logbuch des Kapitäns", description = "<Ihr blättert zum letzten, abgebrochenen Eintrag.>\n\n… nähern uns dem Tempel der Erde bei 300 Knoten und beginnen die Landemanöver gemäß der neuen Route. Wir haben ein Niedrigdrucksystem im Norden notiert und ziehen jetzt unser…\n\nBLUT UND DONNER! ABSCHAUM DER ALLIANZ NÄHERT SICH!", sourceObjective = "Bringt das Logbuch des Kapitäns zu Maruut Steinbinder beim Tempel der Erde in Tiefenheim.", completion = "Warum sollte die Allianz die Horde angreifen, wenn sie uns gerade ein Stück der Weltensäule bringen?", sourceObjectiveStatus = "unverified-source-field" }
quests[26247] = { id = 26247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diplomatie hat Vorrang", description = "Der Irdene Ring ist eine neutrale Gemeinschaft, {name}. Wir können uns im Krieg zwischen der Horde und der Allianz auf keine Seite schlagen.\n\nSeht Euch um. Wir haben Mitglieder verschiedenster Herkunft. Wenn wir die Spannungen zwischen den einzelnen Völkern über unser Ziel stellen würden, wäre unsere Mission in Gefahr. Lasst uns dies also vertraulich behandeln, bis wir weitere Informationen gesammelt haben.\n\nWir dürfen keine voreiligen Schlüsse ziehen. Ich schicke Euch zusammen mit einem unserer neuen Mitglieder los, um das Kanonenboot der Allianz zu suchen.\n\nFindet heraus, was Ihr könnt, ohne uns in den Konflikt hineinzuziehen.", sourceObjective = "Trefft Euch mit Sturmruferin Mylra auf dem Kanonenboot der Allianz.", completion = "He, {name}! Man hat mir gesagt, dass ich bald Gesellschaft bekomme.", sourceObjectiveStatus = "unverified-source-field" }
quests[26248] = { id = 26248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All unsere Freunde sind tot", description = "Irgendwas ist hier nicht in Ordnung, {name}.\n\nDie Besatzung des Schiffes wurde erschlagen. Und doch sehe ich kein vergossenes Blut oder Schäden am Schiffskörper.\n\nDas war nicht das Werk der Horde.\n\nWir müssen mit den Geistern der Toten sprechen, um Antworten zu finden. Sie haben diese Welt noch nicht verlassen.\n\nNehmt dieses Totem und stellt es neben den Leichnamen der Gefallenen auf. Dann könnt Ihr ihre letzten Gedanken hören.\n\nAber seid vorsichtig! Es ist schwer zu sagen, wie die Geister der Toten auf unsere Nachforschungen reagieren werden.", sourceObjective = "Benutzt das Geistertotem in der Nähe von 6 Leichnamen erschlagener Besatzungsmitglieder.", progress = "Die Geister haben immer eine Geschichte für die zu erzählen, die zuhören.", completion = "Es war nur eine Frage der Zeit, bis wir auf Mitglieder des Schattenhammers trafen, {name}. Wenn sie hinter all dem stecken, dann haben sie sicher auch das Fragment der Weltensäule in ihrer Gewalt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26249] = { id = 26249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kajüte des Admirals", description = "Möglicherweise finden wir in der Kajüte des Admirals weitere Spuren. Sie befindet sich direkt unter uns.\n\nSchaut, ob es dort unten irgendwelche Überlebenden oder Informationen gibt, die uns nähere Hinweise zum Verbleib des Weltensäulenfragments geben können. Seid vorsichtig, {name}. Wer auch immer die Besatzung auf dem Gewissen hat, könnte noch dort sein.", sourceObjective = "Haltet in der Kajüte des Admirals auf dem Kanonenboot der Allianz nach Hinweisen Ausschau.", completion = "Dieses Schiff ist voller Ratten…", sourceObjectiveStatus = "unverified-source-field" }
quests[26250] = { id = 26250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ach, einen Gefangenen sollten wir doch nehmen", description = "Es ist nicht zu spät, {name}. Die Kultisten sind bestimmt immer noch hier.\n\nGeht unter Deck, findet heraus, wer das Sagen hat und unterwerft ihn.\n\nWir werden Antworten auf unsere Fragen bekommen, auf die eine oder andere Art.", sourceObjective = "Unterwerft Mor'norokk den Hasserfüllten auf dem Kanonenboot der Allianz in Tiefenheim.", progress = "Grüße, {name}.", completion = "Uff, das war ein schwerer Brocken! Er hat meinem armen Greifen fast den Rücken gebrochen!\n\nSeid Ihr bereit, den Oger zu befragen, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[26251] = { id = 26251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht keine Gefangenen", description = "Sieht aus, als wäre der Schattenhammer noch immer auf dem Schiff. Geht unter Deck und macht kurzen Prozess mit ihnen.\n\nSeid vorsichtig, {name}. Ich habe das Gefühl, dass sie nicht hier sind, um ihr spirituelles Gleichgewicht zu finden, wenn Ihr versteht, was ich meine.", sourceObjective = "Tötet 6 Zwielichtsaboteure.", progress = "Habt Ihr es erledigt, {name}?", completion = "Gut gemacht, {name}. Der Schattenhammer ist ein Übel, das wir an allen Ecken und Enden bekämpfen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26252] = { id = 26252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herz des Behüters", description = "Ihr habt etwas gefunden, das offenbar das Herz eines Erntebehüters ist.\n\nDem Geräusch nach zu urteilen, das von dem Gerät ausgeht, ist es noch immer voll funktionsfähig. Vielleicht solltet Ihr es zu Bauer Saldean zurückbringen.", sourceObjective = "Bringt das Herz eines Erntebehüters zurück zu Bauer Saldean auf Saldeans Hof.", progress = "Was habt Ihr denn da, {name}?", completion = "Ist das etwa... Ist das das Herz eines der Behüter? Ich habe Geschichten darüber gehört, wie man eins von diesen Dingern dazu benutzen kann, einen Behüter für den Eigengebrauch anzutreiben. Natürlich bin ich selbst nicht mehr in der Verfassung, solche Dinge selbst zu versuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26254] = { id = 26254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erklärt Euch!", description = "Springt auf, {name}. Mal sehen, was Herr Ogervisage hier zu seiner Verteidigung zu sagen hat.\n\nNur keine Scheu. Sturmschnabel hat erst ein paar Mal einen Reiter fallenlassen.", sourceObjective = "Springt auf Sturmschnabel und beobachtet Mor'norokks Befragung.", progress = "Ja, {name}?", completion = "Wir haben unsere Antworten, {name}. Melden wir uns zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[26255] = { id = 26255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Tempel der Erde", description = "Ihr müsst die anderen am Tempel informieren. Wahrscheinlich bringen sie das Fragment gerade an einen sicheren Ort.\n\nBerichtet Maruut, was Ihr wisst. Ich werde diesen Zwielichtrat in der Zwischenzeit unter die Lupe nehmen.", sourceObjective = "Sprecht mit Maruut Steinbinder im Tempel der Erde in Tiefenheim.", completion = "Wir müssen Eure Erkenntnisse genauer untersuchen, aber wir dürfen die Spur des Fragments nicht verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[26256] = { id = 26256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst die Blutformer bluten", description = "Der Schattenhammer wirkt hier bösartige Magie, {name}. Sie beleben die Überreste von Todesschwinges Blut und erfüllen sie mit Energie. Statt auszutrocknen und zu verschwinden gedeiht es und wird immer mehr.\n\nErledigt einen ihrer Blutformer und presst Informationen aus ihm heraus, wo wir diesen \"Schmiedemeister\" finden.", sourceObjective = "Besorgt Euch die Schattenhammerbefehle von einem der Zwielichtblutformer in Todesschwinges Sturz.", progress = "Wir müssen uns beeilen, wenn wir die Weltensäule wieder errichten möchten, {name}.", completion = "Sie halten hier Sklaven? Wir sollten sie ohne Frage befreien, aber vielleicht können sie uns auch dabei helfen, den Schmiedemeister zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26257] = { id = 26257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es lebt!", description = "Soweit ich gehört habe, müsst Ihr nur einen geeigneten Erntegolem finden und rein mit dem Herzen. Sobald das erledigt ist, solltet Ihr die volle Kontrolle über das Geschöpf haben.\n\nIch glaube, es gibt ein ganzes Feld mit überladenen Erntegolems westlich von hier auf dem Hof der Molsens. Haltet nach den Lichtbögen Ausschau.\n\nFalls Ihr einen zum Laufen bringen könnt, benutzt den Golem, um die aufgeladenen Ernteschnitter auf dem alten Molsenhof zu zerstören. Die Monster dort sind viel zerstörerischer als die auf unserem Hof hier.", sourceObjective = "Wendet das Herz eines Erntebehüters auf einen überladenen Erntegolem an und benutzt dann den überladenen Erntegolem, um 25 aufgeladene Ernteschnitter zu töten.", completion = "Es hat tatsächlich funktioniert? Das ist unglaublich, {name}. Hoffentlich löst das das Problem mit den Erntegolems hier in Westfall.", sourceObjectiveStatus = "unverified-source-field" }
quests[26258] = { id = 26258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesschwinges Sturz", description = "Dass der Schattenhammer etwas mit dem Verschwinden der Weltensäule zu tun hat, ist nicht verwunderlich. Hoffentlich können wir schnell genug handeln, um sie zurückzuholen.\n\n<Maruut legt seine Hand auf Eure Schulter.>\n\nIch habe ein spirituelles Band zu Euch gewirkt. Wir sollten miteinander kommunizieren können, solange Ihr in Tiefenheim seid.\n\nGeht zu Todesschwinges Sturz im Südosten und untersucht, was der Schattenhammer vorhat.", sourceObjective = "Geht zu Todesschwinges Sturz in Tiefenheim.", completion = "Das muss der Ort sein, an den sie das Säulenfragment gebracht haben. Lasst uns einen genaueren Blick darauf werfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26259] = { id = 26259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut des Erdwächters", description = "Als Todesschwinge nach Tiefenheim geflohen ist, war seine Verderbtheit stark ausgeprägt, aber vielleicht noch nicht vollständig.\n\nDie Kultisten in Todesschwinges Sturz ernten sein übrig gebliebenes verderbtes Blut und formen es in lebende Wesen, um deren Energie aufzunehmen.\n\nWas, wenn eine kleine Spur der Essenz des Erdwächters geblieben ist? Schließlich war Neltharion der Aspekt der Erde, bevor er zum Aspekt des Todes wurde.\n\nSammelt Proben des lebenden Blutes, das die Kultisten erschaffen, und wir überprüfen, ob eine Spur des Erdwächters darin verblieben ist.", sourceObjective = "Sammelt 5 Proben des Blutes von Neltharion vom lebenden Blut in Todesschwinges Sturz.", progress = "Ihr seid zurück, {name}. Habt Ihr das Blut bekommen?", completion = "In diesem Blut schlummert immer noch viel Macht, {name}. Ich kann sie sogar jetzt spüren.\n\nUnd dennoch spüre ich auch viel Verderbtheit. Ich bin mir nicht sicher, ob wir daraus die Essenz des Erdenwächters gewinnen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[26260] = { id = 26260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Logbuch des Schmiedemeisters", description = "Geht zu dem Turm, von dem der Sklave gesprochen hat. Ihr solltet ihn am nordöstlichen Ende des Lagers finden.\n\nWenn wir schnell genug handeln, können wir vielleicht das Treffen des Schmiedemeisters belauschen.", sourceObjective = "Findet das Logbuch des Schmiedemeisters in Todesschwinges Sturz in Tiefenheim.", completion = "Ein Eintrag berichtet von einem anstehenden Treffen in den Oberen Silbermarschen.\n\nDer Schmiedemeister muss sich dort aufhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26261] = { id = 26261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befragt die Sklaven", description = "Laut den Befehlen, die Ihr gefunden habt, soll sich in einem Zelt am südöstlichen Ende von Todesschwinges Sturz ein Schlüssel befinden.\n\nBesorgt ihn Euch und befreit die Sklaven im Steinbruch im Süden.", sourceObjective = "Besorgt Euch den Schlüssel des Zwielichtsklavenhändlers und befreit 6 versklavte Minenarbeiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[26263] = { id = 26263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thornar Donnerknall", description = "Wir haben versucht, den Kommandanten der eindringenden Wildhammerzwerge auszuschalten – bisher jedoch ohne Erfolg.\n\nThornar Donnerknall befindet sich in der Sicherheit seines Kommandopostens und man kann nur seine Stimme hören, die die Zwerge auf dem Schlachtfeld donnernd antreibt. Wir glauben, dass wir ihn zum Schweigen bringen müssen.\n\nErledigt Thornar und wir werden mit dem Rest seiner Truppen problemlos fertigwerden.", sourceObjective = "Tötet Thornar Donnerknall.", completion = "Gut gemacht, Mann. Ihr seid ein echter Held der Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[26264] = { id = 26264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zurückgelassenen", description = "Die meisten von uns haben die kranken und irren Gnome gesehen, die unter den Folgen der Gifte und der Strahlung in Gnomeregan leiden. Ihr Niedergang ist erst vollendet, wenn aus ihnen hirnlose, aber größtenteils harmlose Pfützen aus toxischem Schlick werden.\n\nMeine Nachforschungen lassen darauf schließen, dass wir sie selbst in diesem Zustand noch retten können. Reist zum Toxischen Flugplatz im Süden, unterwerft den toxischen Schlick, von dem ich Euch erzählt habe, und bringt mir den Besitz der Gnome, die sie einst waren.", sourceObjective = "Beschafft 6 zurückerlangte Besitztümer von toxischem Schlick auf dem Toxischen Flugplatz.", progress = "Konntet Ihr den Besitz einiger bestrahlter Gnome bergen?", completion = "Ich kann es kaum erwarten, diese neue Technologie auszuprobieren! Zahllose Gnome sind der Strahlung zum Opfer gefallen. Es wird Zeit, den Prozess umzukehren!", sourceObjectiveStatus = "unverified-source-field" }
quests[26265] = { id = 26265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stoppt die Verseuchung", description = "Tock Flinkspross hat eine verrückte Theorie. Er glaubt, bei den toxischen Schlickpfützen handele es sich um die Überreste von Gnomen, deshalb haben meine Männer Befehl, sie erst einmal nicht anzugreifen.\n\nAllerdings wimmelt es auf dem Toxischen Flugplatz südlich von hier von lebenden Verseuchungen. Dabei handelt es sich um Elementare, die aus verseuchtem Wasser und anderen toxischen Materialien bestehen. Wenn wir uns nicht um sie kümmern, werden sie die Stadt überrennen. Würdet Ihr uns helfen, sie loszuwerden?", sourceObjective = "Zerstört 6 lebende Verseuchungen auf dem Toxischen Flugplatz.", progress = "Konntet Ihr die Verseuchungen beseitigen?", completion = "Welch eine Erleichterung! Ich danke Euch für Eure Hilfe. Ich hoffe, dass Dingsda, an dem Ingenieur Schleiffunke gearbeitet hat, hilft uns, den Flugplatz endgültig zu säubern.", sourceObjectiveStatus = "unverified-source-field" }
quests[26266] = { id = 26266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoffnung für das Volk", description = "Vor ungefähr vier Jahren stolperte ein kleines Mädchen mitten in der Nacht in unser Farmhaus und brach zusammen. Niemand kannte sie. Das arme, kleine Ding hatte keine Erinnerung daran, wer sie sein könnte oder woher sie kam - wahrlich eine verirrte Seele.\n\nBald darauf adoptierten wir die Kleine und nannten sie Hope - denn für uns bedeutete sie Hoffnung.\n\nJetzt ist sie eine junge Dame und kümmert sich um die Obdach- und Mittellosen von Westfall. Bringt meinen Westfalleintopf zu ihr zur Späherkuppe südlich von hier.", sourceObjective = "Bringt den Westfalleintopf zu Hope Saldean an der Späherkuppe.", progress = "Guten Tag werter Herr. Wie kann ich Euch dienen?", completion = "Ich rieche Westfalleintopf! Hat Mutter Euch geschickt!?", sourceObjectiveStatus = "unverified-source-field" }
quests[26267] = { id = 26267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Lauerfels aufräumen", description = "Vor vielen Jahren hatte die Horde eine Station tief im Lauerfels. Sie steht seitdem leer aber es ist immer noch eine gute Stellung, die wir wieder einnehmen sollten.\n\nDas Problem ist dass die Station voll von Schlamm ist inzwischen. Schlamme sind üble Dinger... kopflos, ätzend, und gefährlich, da sie alles essen, was ihnen in den Weg kommt.\n\nIch brauche jemand, der mutig genug ist, um sich zum Lauerfels zu begeben und die Schlamme zu beseitigen. Seid Ihr mutig genug, {name}?", sourceObjective = "Tötet 10 jadegrüne Schlamme.", completion = "Gut, dass Ihr wieder hier seid... und sogar mit allen Gliedmaßen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26268] = { id = 26268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lauerfelsvorräte", description = "Ich war im Zweiten Krieg in Lauerfels stationiert. Ich war jung, noch Jahre davon entfernt, meine Partnerin kennenzulernen, und erinner mich noch gut an das Chaos, das ausbrach, als die Allianz uns angriff. Wir sind mit den Orcs geflohen und haben keine Zeit damit verschwendet, unsere Besitztümer zu packen.\n\nWir haben alles hinter uns gelassen. In Lauerfels sind noch immer viele unserer alten Vorräte. Wir könnten sie hier im Dorf gut gebrauchen... und vor allem sollten die Wildhammerzwerge sie nicht in ihre dreckigen Hände bekommen.", sourceObjective = "Sammelt 5 schlammbedeckte Vorratskisten.", progress = "Wie viele Kisten habt Ihr gefunden?", completion = "Sie sind unversehrt! In diesen Kisten sind viele Erinnerungen festgehalten. Mal sehen, was wir hier haben...\n\nBananenbrot! Und es ist noch gut!\n\nHier, also ich nehme das hier, Ihr könnt Euch auch etwas aussuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26269] = { id = 26269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grünen Hügel des Schlingendorntals", description = "Eine Seite! Ich brauche nur noch eine Seite!\n\nMit dem Schmöker von Meister Nesingwary gab es einen kleinen... Unfall <Barnil blickt vorwurfsvoll zu Klaps>... und wir haben ein paar der Seiten verloren.\n\nIch habe die anderen Abenteurer bereits um Hilfe gebeten und sie konnten auch ein paar der Seiten wiederfinden, aber eine Seite fehlt immer noch.\n\nIhr seid sicher furchtbar beschäftigt mit anderen Sachen, aber falls Ihr sowieso im Dschungel sein solltet, würde es Euch sicherlich nicht stören, ein wenig nach der Seite Ausschau zu halten?", sourceObjective = "Findet Seite 14 von Die Grünen Hügel des Schlingendorntals.", progress = "Habt Ihr sie gefunden? Ich würde Hemet nur äußerst ungern ein fast fertiges Buch geben.", completion = "Ihr habt mir sicherlich viel Ärger erspart, {name}! Ich kann Euch gar nicht genug danken. Es wird nicht mehr lange dauern, und wir werden das Buch von Meister Nesingwary in Bibliotheken überall auf der Welt finden können!\n\nIch werde eine Kopie für Euch hierlassen, falls Ihr Euch je für das fertige Exemplar interessieren solltet. Vielen Dank, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[26270] = { id = 26270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unser Dank ist Euch gewiss", description = "Es ist viele Jahre her, dass uns Hilfe angeboten wurde, {name}. Wärt Ihr nicht gewesen, hätten wir es womöglich nicht über den nächsten Winter geschafft. Ihr habt Euch als eine selbstlose Person erwiesen - jemand, dem wir vertrauen können. Ich wünschte nur, wir hätten etwas von Wert, das wir Euch anbieten könnten.\n\nIch habe zwar keine Informationen, die Euch bei Eurem Vorhaben, die Mörder der Brauenwirbels zur Strecke zu bringen, von Nutzen sein werden, aber vielleicht kann Euch meine Frau weiterhelfen. Sprecht mit Salma im Haus und sie wird Euch sagen, was Ihr wissen müsst, bevor Ihr Euch wieder auf den Weg macht.", sourceObjective = "Sprecht mit Salma Saldean auf Saldeans Hof in Westfall.", completion = "Aber natürlich, mein Lieber. Unsere kleine Tochter arbeitet an der Späherkuppe und steht den Obdachlosen von Westfall sehr nahe. Vielleicht hat sie ja etwas mitbekommen. Bevor Ihr geht, lasst mich den Westfalleintopf einpacken und Euch ein wenig über unsere liebe kleine Tochter erzählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26271] = { id = 26271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hungrigen und die Hoffnungslosen speisen", description = "Ja, ich habe von den Brauenwirbelmorden gehört. Es ist sehr tragisch, aber solche Tragödien sind in Westfall an der Tagesordnung. Hier gibt es viele Leute, die einfach nicht mehr die Mittel oder den Willen haben, sich selbst zu versorgen. Sie haben die Hoffnung aufgegeben. Könnt Ihr Euch vorstellen, wie es ist, so hoffnungslos zu sein, dass man sich seines Lebens nicht mehr erfreuen kann? Wir müssen uns gemeinsam darum bemühen, ihnen zu zeigen, dass es noch Hoffnung gibt. Dass jeder neue Tag ein besseres Leben bringt.\n\nNehmt den Westfalleintopf meiner Mutter und helft dabei, die Obdachlosen an der Späherkuppe zu versorgen.", sourceObjective = "Benutzt den Westfalleintopf, um 20 Obdachlose an der Späherkuppe in Westfall zu speisen.", completion = "Ihr habt ein gutes Herz, {name}. Ihr habt heute eine gute Tat vollbracht und das wird Euch am jüngsten Tag nicht vergessen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26272] = { id = 26272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg der Dunkelspeere", description = "Die Trolle des Dunkelspeerstamms waren lange Zeit Opfer. Ausgestoßene. Immer wieder mussten wir fliehen und unser Zuhause verlassen. Aber diesmal hat uns nicht die Flucht hierher getrieben.\n\nVol'jin bot uns Führung durch Weisheit, und das hat uns so lange am Leben erhalten. Nun bietet uns diese Weisheit Vorzeichen einer chaotischen Zukunft für die Horde und für Garrosh Höllschrei.\n\nNein, diesmal fliehen wir nicht. Diesmal kämpfen wir für ein Zuhause, das bestehen bleibt.\n\nEs ist Zeit, mit Eurer Ausbildung zu beginnen, {name}. Sprecht mit Voldreka im Osten.", sourceObjective = "Trefft Voldreka auf dem Ausbildungsgelände der Dunkelspeere.", completion = "Noch so ein Jungblut, wie?\n\nDoch aus Eurem Blick spricht Entschlossenheit. Feurige Augen. Vielleicht wird aus Euch noch eine echte {class}.\n\nLasst uns keine Zeit mehr verschwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26273] = { id = 26273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grundlagen: Dinge schlagen", description = "Okay, Mann. Fangen wir klein an. Ich weiß, dass Ihr die Grundlagen der dunklen Künste beherrscht.\n\nGeht und macht diese Tikiziele fertig. Nehmt Euch Zeit. Bleibt ganz natürlich. Ich sehe zu, wie Ihr Eure Zauber formt. Dann sehen wir weiter.", sourceObjective = "Zerstört 6 Tikiziele.", completion = "Nicht übel, Mann. Ihr habt tiefe Macht in Euren Zaubern - vielleicht seid Ihr talentiert.\n\nNoch habt Ihr Ecken und Kanten, aber die werden wir hier schon glätten, und dabei werde ich Euch ein oder zwei neue Dinge beibringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26274] = { id = 26274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Künste eines Hexenmeisters", description = "Ich glaube, da ist etwas, das ich Euch sagen sollte.\n\nWenn Ihr stärker werdet, fangt Ihr an, diese Stimmen zu hören - sie bringen Euch neue Dinge, neue Zauber bei.\n\nLos, sammelt weitere Erfahrungen. Kommt dann zurück und zeigt mir, was Ihr gelernt habt.", sourceObjective = "Ihr müsst Stufe 3 erreichen, um Verderbnis zu erlernen. Probiert Verderbnis fünfmal an einem Tikiziel aus.", completion = "Gut Arbeit, Mann! Das scheint Euch ja leicht zu fallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26275] = { id = 26275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aller Anfang ist schwer", description = "Woll'n wir Eure Fertigkeiten mal nutzen, Mann. Ich fange ganz einfach an.\n\nDa sind Katzen unterwegs, die unsere Eber töten. Wir teilen unser Essen aber nich' gerne. Diese Eber müssen am Leben bleiben, wenn Ihr heute Abend was zu beißen haben wollt.\n\nSie sind überall auf der Insel. Bringt mir ein paar Katzenpelze!", sourceObjective = "Sammelt 6 Felle einer Wildmähnenkatze.", progress = "Sie sind sicher keine große Herausforderung, Mann, aber sie können einem ganz schön die Knöchel zerkratzen, wenn man nicht schnell genug auf den Beinen ist.", completion = "Das sind nette Pelzchen, Mädel. Die geben sicher 'n paar mächtige Mäntel ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[26276] = { id = 26276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grube der Bewährung", description = "Ihr habt Euch ganz schön gemausert, {class}. Ich bin sicher, ich könnte Euch hier und da einen Trick oder zwei beibringen, aber ich werde Eure Zeit nicht mehr mit Tikizielen verschwenden.\n\nIch habe also eine letzte Prüfung für Euch, Mann. Geht rüber zur Grube in der Mitte von diesem Gebiet und kämpft gegen einen echten Fiesling - einen, der Euch auch umbringen will. Lasst es den Gefängniswärter wissen, wenn Ihr bereit seid.", sourceObjective = "Redet mit einem Gefängnisaufseher der Dunkelspeere, betretet dann die Grube der Bewährung und besiegt einen gefangenen Späher der Gallschuppen.", progress = "Alle Trolle müssen sich beweisen, bevor wir sie weiter als zum Übungsgelände gehen lassen.", completion = "Ihr macht Euch ganz gut. Eines Tages werdet Ihr ganz schön mächtig sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[26277] = { id = 26277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr als erwartet", description = "Ihr bringt auf jeden Fall mehr als erwartet, Mann. Ich bin sicher, es gibt noch mehr wichtige Sachen, bei denen wir Eure Fähigkeiten gebrauchen können. Ihr müsst nicht mehr mit dem Nachwuchs herumhängen.\n\nGeht zum Dorf im Südosten und stellt Euch vor. Helft hier und da und ich bin sicher, dass Ihr schnell aufsteigen und mehr Ansehen erlangen werdet.", sourceObjective = "Meldet Euch bei Vol'jin in der Dunkelspeerfeste.", completion = "Ihr seid der neue Rekrut, von dem alle reden, hm? Willkommen bei den Dunkelspeeren.", sourceObjectiveStatus = "unverified-source-field" }
quests[26278] = { id = 26278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung von Grom'gol: Raptorenrisiko", description = "Throm'ka, {class}!\n\nEure Ankunft in Grom'gol kommt zu einer guten Zeit. Unsere Aufgabe, einen sicheren Weg für die Vorräte für Steinard zu finden, wird von den Ortsansässigen verhindert.\n\nIch werde Euch damit beauftragen, die Raptoren außerhalb Grom'gols für immer zu beseitigen. Macht Euch um die Raptoren selber keine Sorgen... diese jämmerlichen Jäger von Nesingwary werden sich um sie kümmern.\n\nIhr sollt die Eier der Raptoren zerstören.", sourceObjective = "Zerstört 12 Schmetterschwanzeier.", completion = "Macht mir der guten Arbeit weiter, {class}. Höllschrei hat Euch im Auge.", sourceObjectiveStatus = "unverified-source-field" }
quests[26279] = { id = 26279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung von Grom'gol: Ogerunterdrückung", description = "Als wir zuerst hier im Dschungel ankamen hatten wir nicht vor, gegen die Einheimischen einen Krieg zu führen. Unsere Aufgabe, Steinard zu versorgen, hat oberste Priorität. Es ist aber zu Komplikationen gekommen. Ein paar Oger haben die Ruinen von Mizjah südöstlich von Grom'gol eingenommen. Trotz unsere Warnungen greifen sie unsere Versorgungskarawanen weiterhin an.\n\nIch werde Euch damit beauftragen, Euch um die unkooperativen Oger zu kümmern.\n\nBegebt Euch zu den Ruinen und versucht, sie aus der Gegend zu vertreiben. Zumindest muss ihnen eine klare Nachricht geschickt werden.", sourceObjective = "Tötet 4 Schläger der Mosh'Ogg und 4 Hexendoktoren der Mosh'Ogg.", completion = "Ihr seid auch für Sachen zu gebrauchen, die etwas herausfordernder sind als das Zerschlagen von Eiern. Das ist gut. Die Horde kann einen fähigen {race} wie Euch gut gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26280] = { id = 26280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung von Grom'gol: Murlocbedrohung", description = "Die Murlocs der Düsterkiemen wurden von den Salzschuppen aus dem Ozean vertrieben und nun suchen sie in den Ruinen von Kal'ai nordöstlich von hier Zuflucht. Früher war das kein Problem, aber inzwischen ist es nicht länger tragbar.\n\nWeit entfernt von dem Ozean, ihrer Heimat, wurden die Düsterkiemen unruhig und schicken Futterwühler aus, um die Versorgungskarawanen zu überfallen. Vermittelt ihnen folgende Nachricht: solches Verhalten wird von Höllschreis Horde NICHT geduldet.", sourceObjective = "Tötet 15 Murlocs der Düsterkiemen.", completion = "Ausgezeichnete Arbeit. Hoffentlich werden die Beutezüge jetzt aufhören.\n\nIch habe noch eine weitere Aufgabe für Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26281] = { id = 26281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung von Grom'gol: Trolldiebstähle", description = "Die Trolle lassen uns eigentlich in Ruhe hier in Grom'gol. Die meisten Trolle wissen genau, dass die Horde sie leicht zerschmettern kann, wenn es sein muss, und auch die Trolle hier in Schlingendorntal sind sich dessen bewusst.\n\nDie Blutskalpe wurden in der letzten Zeit aber immer aktiver. Erst letzte Woche haben sie einen Trupp nach Grom'gol geschickt und mehrere Rationen gestohlen.\n\nDem Stehlen von Nahrung kann von jeder Art des Diebstahls noch am ehesten vergeben werden, aber ich kann trotzdem nicht zulassen, dass es vorkommt während ich das Sagen habe. Begebt Euch nach Norden zu den Ruinen von Bal'lal und holt unser Eigentum zurück.", sourceObjective = "Holt die Rationen aus Grom'gol aus den Ruinen von Bal'lal.", progress = "Mitleid hat unter meinem Kommando nichts zu suchen. Die Trolle können ihr Essen anderweitig besorgen. Der Dschungel ist groß genug.", completion = "<Aggro'gosh begrüßt Euch.>\n\nIhr habt den Dank der Horde, {name}. Grom'gol ist sicher, wenn auch nur für einen Tag.", sourceObjectiveStatus = "unverified-source-field" }
quests[26282] = { id = 26282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gunst Akil'darahs" }
quests[26283] = { id = 26283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erstklassiger Schleim", description = "Die Schleime, die in Lauerfels zu finden sind, interessieren mich mehr und mehr. Sie kommen immer wieder, egal, wie oft man sie entfernt, aber sie scheinen sich von einem einzigen Schleim selber nicht vermehren zu können.\n\nIch glaube, das in Lauerfels etwas wächst. Eine Quelle, aus der der Schleim kommt. Ich möchte sie untersuchen - findet diese Quelle und bringt mir eine Probe.", sourceObjective = "Erhaltet eine Terrorklumpenprobe von Terrorklumpen.", progress = "Und? Was habt Ihr gefunden?", completion = "Faszinierend... wie groß war es? Ich frage mich, ob es davon noch andere gibt, die funktionstüchtig sind...\n\nDiese Probe ist ausgezeichnet. Ich werde sie meinen Forscherkollegen zugänglich machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26284] = { id = 26284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermisst", description = "Für solche Aufträge bringe ich normalerweise meine ganze Belegschaft von Demolierern mit. Mit etwas Hilfe bei der Pulverherstellung, der Herstellung der Sprengladungen und dem Rest von unserem Zeug wird alles viel schneller fertig.\n\nDiese verdammten Troggs haben meine Jungs überall rund um die Höhle der Frostmähnen in Käfige gesperrt. Jetzt stehe ich ganz allein da, ohne das Personal, das ich für dieses Vorhaben brauche. Würdet Ihr die Demolierer finden, die die Troggs eingesperrt haben, und sie aus ihren Käfigen befreien?", sourceObjective = "Befreit 6 gefangene Demolierer aus ihren Käfigen in der Nähe der Höhle der Frostmähnen.", completion = "Ihr habt meinen Dank und den der Männer, die Ihr gerettet habt. Ich habe die Jungs schon die Ausrüstung in der Höhle aufstellen lassen. Bald sollte alles bereit sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[26285] = { id = 26285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt meinen Sprengstoff zurück!", description = "Wir werden jede Menge Pulver brauchen, um die Höhlen zum Einsturz zu bringen. Keine Ahnung, ob die verdammten Troggs das wussten, als sie meine Vorräte stahlen und meine Demolierer entführten! Das Ergebnis ist dasselbe.\n\nKann nichts in die Luft jagen, wenn ich kein Pulver habe.\n\nGeht nach Süden zur Höhle der Frostmähnen und tötet alle Troggs, die Ihr seht. Jeder von ihnen könnte meine Pulverfässer dabei haben.", sourceObjective = "Beschafft 7 gestohlene Pulverfässer von Knochenpflückern der Felsenkiefertroggs oder von Marodeuren der Felsenkiefertroggs bei der Höhle der Frostmähnen.", progress = "Habt Ihr meine fehlenden Vorräte gefunden?", completion = "Na, so gefällt mir das schon besser. Vielleicht sprengen wir doch noch irgendwas in die Luft.", sourceObjectiveStatus = "unverified-source-field" }
quests[26286] = { id = 26286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung Westfalls", description = "Nachdem meine Dienstzeit in den Grizzlyhügeln beendet war, bin ich nach Westfall zurückgekehrt und musste das Land in einem schlimmeren Zustand als vor meinem Einsatz vorfinden.\n\nWir haben den Krieg mit tausenden von obdachlosen Bürgern bezahlt. Jetzt wandern sie hierhin aus und lassen sich auf den verlassenen Bauernhöfen und Siedlungen dieser Gegend nieder.\n\nZu allem Überfluss werden wir jetzt auch noch von den Gnollen angegriffen. Die Westfallbrigade braucht Eure Hilfe, {name}. Tötet die angreifenden Gnolle und nehmt ihnen ihre Befehle ab. Da zieht jemand im Hintergrund die Fäden und wir müssen herausfinden, wer das ist!", sourceObjective = "Erhaltet die Angriffsbefehle der Gnolle.", progress = "Habt ihr die Angriffsbefehle?", completion = "Helix? Den Namen habe ich doch schon mal gehört. Und zwar vor gar nicht so langer Zeit, aber wer ist dieser Admiral?", sourceObjectiveStatus = "unverified-source-field" }
quests[26287] = { id = 26287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Westfallbrigade", description = "Wir waren einst als Volksmiliz bekannt. Heutzutage kämpfen wir unter der Flagge von Sturmwind mit der vollen Unterstützung von König Varian Wrynn. Wir haben viele Ziele hier in Westfall: die Unordnung, die die Defias hinterlassen haben, aufzuräumen, das Hoheitsgebiet der Allianz auszuweiten und Ordnung zu bewahren. Bisher versagen wir auf der ganzen Linie.\n\nDie Zeiten sind jetzt noch schlimmer, als zu dem Zeitpunkt, als die Defias Amok gelaufen sind. Jetzt, da die einheimischen Gnolle sich ebenfalls bewaffnet haben, sind wir in eine Ecke gedrängt worden. Helft uns, {name}!", sourceObjective = "Tötet 12 beliebige Gnolle der Flusspfoten, die die Späherkuppe angreifen.", completion = "Gut gemacht, {name}. Ihr habt uns eine Atempause von dem Sturmangriff der Gnolle verschafft, aber es gibt noch mehr zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[26288] = { id = 26288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jango Fleckfell", description = "Südlich von hier befindet sich ein Landstrich von Westfall, den wir Staubebenen nennen. Soweit wir wissen, haben die Gnolle der Region die Staubebenen zu ihrem inoffiziellen Hauptquartier erklärt. Wie bei jedem Hauptquartier gibt es auch bei diesem einen Anführer. Wenn wir diesen Angriffen einen Riegel vorschieben wollen, dann müssen wir den Gnoll ausfindig machen, der den Ton angibt, und ihm das Handwerk legen.\n\nBegebt Euch zu den Staubebenen, findet den Anführer der Gnolle, Jango Fleckfell, und tötet ihn. Erledigt auch sämtliche Gnolle, die sich Euch in den Weg stellen.", sourceObjective = "Tötet 5 Mystiker der Flusspfoten, 5 Zuchtmeister der Flusspfoten und Jango Fleckfell.", completion = "Ausgezeichnete Arbeit, {name}. Die Flusspfoten werden Wochen brauchen, um sich von dem Schlag zu erholen, den Ihr ihnen heute zugefügt habt. Bitte wählt einen Gegenstand als Belohnung für Eure Tat aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[26289] = { id = 26289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet Agentin Kearnen", description = "Der SI:7 hat die Bewegungen von Helix Ritzelbrecher genau beobachtet, seit er vor zwei Wochen seinen Fuß auf Allianzboden gesetzt hat. Der Brief, den ich von Mathias Shaw erhalten habe, erklärt, dass er eine Agentin namens Kearnen nach Westfall entsandt hat, um Helix zu beschatten. Findet Agentin Kearnen, dann werdet Ihr auch Helix Ritzelbrecher finden.\n\nKearnen war vor zwei Tagen in der Stadt, um Vorräte zu besorgen. Sie hat erwähnt, dass sie in der Nähe von Jagdrufs Turm südöstlich von hier in den Staubebenen zu finden sein würde.\n\nAbmarsch, {name}.", sourceObjective = "Findet Agentin Kearnen.", completion = "Helix steckt hinter den Gnollangriffen?\n\n<Kearnen nickt dem Turm zu.>\n\nEr ist da drin. Er ist schon seit Tagen dort. Ich warte nur auf einen Grund, ihn hopszunehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26290] = { id = 26290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse des Turms", description = "Helix hat sich oben im alten Turm von Klaven Jagdruf verschanzt. Ich werde Euch nicht belügen, {name}, er wird schwer bewacht. Ich habe allein im Freien sechs bewaffnete Söldner gezählt. Ihr schafft es nie allein in den Turm. Zu Eurem Glück sind Claire und ich hier.\n\n<Kearnen tätschelt ihr Heckenschützengewehr.>\n\nIch gebe Euch Deckungsfeuer.\n\nNehmt diesen Verschleierungstrank; Ihr werdet ihn brauchen, wenn Ihr es ins Innere geschafft habt. Trinkt ihn, sobald Ihr den Turm betretet und steigt dann den Turm hinauf. Findet heraus, was Helix dort oben versteckt!", sourceObjective = "Betretet Jagdrufs Turm und macht Helix Ritzelbrecher ausfindig.", progress = "Ich werde Euch nicht im Stich lassen, {name}.", completion = "Was um alles in der Welt könnte denn in Mondbruch los sein? Das alles schmeckt mir überhaupt nicht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26291] = { id = 26291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viel Ärger in Mondbruch", description = "Ich werde bald meinen Bericht schreiben und nach Sturmwind zurückkehren. Der SI:7 muss über die Situation in Westfall informiert werden. Ich schlage vor, Ihr tut das gleiche und erstattet Gryan Bericht.", sourceObjective = "Berichtet Marschall Gryan Starkmantel an der Späherkuppe in Westfall, was Ihr herausgefunden habt.", completion = "Wer ist wohl diese merkwürdige Gestalt? Wir müssen nach Mondbruch gelangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26292] = { id = 26292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Mondbruch!", description = "Wir haben schon eine ganze Weile ein Lager in der Nähe von Mondbruch, {name}. Einer meiner besten Soldaten ist zusammen mit einer Kompanie von der Späherkuppe in diesem Gebiet stationiert. Meldet Euch umgehend bei Hauptmann Alpert und findet heraus, ob er irgendwelche Neuigkeiten über die Vorgänge in Mondbruch hat.\n\nEin weiterer Verbündeter von mir ist auch in dem Mondbrucher Lager. Sein Name ist Thoralius. Ich habe Thoralius in Nordend während meiner Dienstzeit in Valgarde kennengelernt. Er ist ein weiser und mächtiger Schamane. Vielleicht können uns seine Fähigkeiten dabei helfen, diesen Fall zu lösen.", sourceObjective = "Meldet Euch bei Hauptmann Alpert in Mondbruch in Westfall.", completion = "Die Einheimischen werden unruhig, {name}. Ich weiß nicht, was los ist, aber die Aktivitäten der Obdachlosen in dieser Gegend haben sich in den letzten zwei Tagen vervierfacht. Wenn ich es nicht besser wüsste, würde ich sagen, die hecken etwas aus...", sourceObjectiveStatus = "unverified-source-field" }
quests[26293] = { id = 26293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsmaschinen", description = "Diese \"Weltenbrecher\" verstecken sich in einer Hochlandwildnis und besetzen die Gebiete hinter den Allianzkönigreichen im Osten. Wir werden sie vernichten, und zwar mit der mächtigsten Armee seit unseren Siegen in Nordend!\n\nIch habe unsere neuen Goblinverbündeten gebeten, eine Flotte an Kriegsmaschinen zu bauen, doch die Berichte zeigen, dass ihre Arbeitsqualität manchmal... zu wünschen übrig lässt.\n\nIch werde nicht mit fehlerhaften Maschinen in die Schlacht ziehen. Trefft Euch mit Großknecht Glibbs hier in Orgrimmar und stellt sicher, dass meine Kriegsmaschinen kampfbereit sind!", sourceObjective = "Sprecht mit Großknecht Glibbs am Hinteren Tor von Orgrimmar in Orgrimmar.", completion = "Hab zu tun. Geht weg.\n\nWartet, was? Höllschrei schickt Euch? Was… äh… was kann ich für Euch tun? Für ihn? Für uns?", sourceObjectiveStatus = "unverified-source-field" }
quests[26294] = { id = 26294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Massenversagenswaffen", description = "<Glibbs wischt sich mit einem öligen Taschentuch den Schweiß von der Stirn.>\n\nHöllschrei ist mit unserer Arbeit nicht zufrieden? Oh weh. Und wir haben \"Höllschreis Verwüster\" sogar nach ihm BENANNT. Das ist nicht gut. Meine Jungs müssen sich mehr ins Zeug legen.\n\nVielleicht könnt Ihr für uns ein Exempel statuieren. Ein neuer Satz von Höllschreis Verwüstern kam gerade aus der Produktion und ist bereit, inspiziert zu werden. Untersucht sie gründlich. Wenn Ihr Probleme findet, dann verpasst dem Chefingenieur eine Abreibung. Erinnert ihn daran, dass Höllschrei uns im Auge hat!", sourceObjective = "Untersucht Höllschreis Verwüster, bis Ihr einen fehlerhaften Verwüster findet, und erteilt dem Chefingenieur dann eine Lektion.", completion = "<Garrosh lacht.>\n\nIhr habt ihnen also ein bisschen Disziplin beigebracht, was? Gut, gut!\n\nIn meiner Horde leistet jeder seinen Beitrag, vom geringsten Peon bis hin zum stolzesten Krieger. Weniger dulde ich nicht.\n\nUnsere Vorbereitungen für die Invasion sind fast abgeschlossen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26295] = { id = 26295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Propaganda", description = "Uns ist ein Anstieg der Gewalttaten unter den Obdachlosen in dieser Gegend aufgefallen. Irgendetwas oder irgendjemand versetzt sie ganz schön in Aufruhr. Wer auch immer dahinter steckt, organisiert sich immer besser. Erst vor Kurzem ist eine Gruppe Schläger hier durchgekommen und hat Flugblätter verteilt.\n\nGeht nach Mondbruch und sucht nach Beweisen. Propaganda, Handzettel, egal was... Bringt mir alles, was Ihr finden könnt. Vielleicht können wir ja den Ursprung der Schriften finden.", sourceObjective = "Erhaltet ein Informationsflugblatt, ein geheimes Tagebuch, eine Ausgabe des Mondbrucher Blatts und mysteriöse Propaganda.", progress = "Konntet Ihr etwas finden?", completion = "V? Der einzige V, den ich kenne, ist van Cleef und der ist vor vielen Jahren gestorben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26296] = { id = 26296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweissammlung", description = "Dieses Kopftuch besteht aus dem gleichen Stoff, der auch am Tatort des Brauenwirbelmordes gefunden wurde. Ihr solltet noch mehr rote Kopftücher als Beweis sammeln und Euren Fund zu Hauptmann Alpert bringen.", sourceObjective = "Sammelt 6 rote Kopftücher.", progress = "Rote Kopftücher?!", completion = "Ich habe seit fünf Jahren keine roten Kopftücher mehr gesehen. Ob diese merkwürdige Gestalt wohl versucht, die Bruderschaft der Defias neu zu gründen?", sourceObjectiveStatus = "unverified-source-field" }
quests[26297] = { id = 26297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Anbruch eines neuen Tages", description = "Sieht so aus, als fängt die Versammlung, von der die merkwürdige Gestalt sprach, bald an. Die Obdachlosen setzen sich in Bewegung. Ich möchte, dass Ihr an der Kundgebung teilnehmt und Informationen sammelt, {name}.\n\nBegebt Euch zur Stadtmitte Mondbruchs und hört Euch die Ansprache an. Kehrt zu mir zurück und berichtet, was Ihr herausfinden konntet.", sourceObjective = "Sammelt Informationen bei der Versammlung von Mondbruch.", progress = "Was ist geschehen?", completion = "Ich konnte die Jubelschreie von hier aus hören. Wir haben es anscheinend mit einem riesigen Problem zu tun, {name}. Wir müssen die Identität dieser schattenhaften Bedrohung aufdecken, bevor wir die Hilfe Sturmwinds anfordern. Vielleicht gibt es eine andere Möglichkeit...", sourceObjectiveStatus = "unverified-source-field" }
quests[26298] = { id = 26298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach Yenniku", description = "Unheil droht. Unheil für den jüngsten Sohn meines Häuptlings, Yenniku. Der Sitte unseres Volkes nach wurde er den Gurubashitrollen von Zul'Gurub gegeben, aber nachdem mein Stamm, der Dunkelspeerstamm, mit dem Orc Thrall gegangen ist, war der arme Yenniku für uns verloren. Ich wurde aus dem fernen Orgrimmar zurück ins Schlingendorntal geschickt, um nach dem Sohn meines Häuptlings zu suchen.\n\nUnd ich glaube, dass der Blutskalpstamm ihn hat.\n\nWenn Ihr mir helfen wollt, dann jagt die Blutskalpe. Ihr könnt sie im Norden finden. Sammelt ihre Hauer und kehrt zu mir zurück.", sourceObjective = "Beschafft 6 Hauer der Blutskalpe von Blutskalptrollen in den Ruinen von Bal'lal.", progress = "{class}. Zeigt mir, dass Ihr Beute von dem Blutskalpstamm gemacht habt.\n\nZeigt mir Eure Trophäen.", completion = "Das sind gute Hauer, {name}. Ihr habt bewiesen, dass Ihr stark genug seid, um die Blutskalpe zu jagen.\n\nDas ist gut, denn die Jagd auf sie ist für Euch noch nicht vorbei.", sourceObjectiveStatus = "unverified-source-field" }
quests[26299] = { id = 26299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfjägerei", description = "Wir müssen herausfinden, ob Yenniku tot ist.\n\nErschlagt die Kopfjäger der Blutskalpe und nehmt ihnen ihre Schrumpfköpfe ab. Ihr müsst viele, viele Köpfe sammeln und ich werde sie überprüfen, um sicherzugehen, dass Yennikus Kopf nicht dabei ist.\n\nSollte Yenniku von den Blutskalpen getötet worden sein, möge ein Fluch für 600 Jahre auf den Geist ihres Häuptlings, Gan'zulah, kommen!\n\nGeht, {name}. Ihr könnt die Köpfe bei den Ruinen von Zuuldaia an der Küste im Norden finden.", sourceObjective = "Beschafft 25 Schrumpfköpfe von Blutskalptrollen in den Ruinen von Zuuldaia.", progress = "{name}. Ich fürchte um den Sohn unseres Häuptlings. Habt Ihr die Schrumpfköpfe, sodass ich sie untersuchen kann?", completion = "Ich danke Euch, {name}. Ich werde sie sogleich untersuchen, um sicherzugehen, dass der arme Yenniku der Axt der Kopfjäger entgangen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[26300] = { id = 26300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nezzliok wird es wissen", description = "Yennikus Kopf war nicht dabei und ich danke der großen Schlange dafür. Wir sind aber noch keinen Schritt weiter, ihn zu finden.\n\nWir müssen die Wahrheit erfahren und ich fürchte, nur der Hexendoktor der Blutskalpe wird uns helfen können. Als Feind der Dunkelspeere wird er nicht offen sprechen wollen und daher müssen wir die Wahrheit aus seinen toten Lippen zwingen!\n\nBringt mir den Kopf von Nezzliok dem Düsteren und platziert ihn hier im Kessel.\n\nIhr werdet ihn tief in Zul'Kunda finden. Bringt mir seinen Kopf... wir werden ihn schon zum Sprechen bringen.", sourceObjective = "Erhaltet Nezzlioks Kopf von Nezzliok dem Düsteren in Zul'Kunda.", progress = "Die grüne Brühe im Kessel brodelt.", completion = "Ihr platziert den Kopf von Nezzliok im Kessel...", sourceObjectiveStatus = "unverified-source-field" }
quests[26301] = { id = 26301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Nezzliok sprechen", description = "<Der Kopf von Nezzliok spricht.>\n\nEs stimmt. Ich weiß, wo das Kind der Dunkelspeere hingebracht wurde. Ihr habt mich besiegt und meinen Geist gebunden, aber ohne Gegenleistung sage ich nichts!\n\nDie Blutskalpe streiten mit den Schädelspaltern. Um mein Wohlwollen zu erhalten, stehlt zwei der meist geschätzten Trophäenschädel von den Schädelspaltern östlich des Flusses. Legt sie hierher zu uns, sodass mein Geist im Nether Sklaven zur Verfügung hat. Ein Schädel muss aus ihrem Trophäenstapel in Balia'mah und der zweite von Ziata'jai stammen.", sourceObjective = "Erhaltet eine Trophäe von Balia'mah und eine Trophäe von Ziata'jai aus den Ruinen der Schädelspalter.", progress = "Ich erwarte die Schädel...", completion = "Ja. Diese werden mir gute Dienste leisten. Wenn mein Geist befreit wurde, werde ich mit drei guten Dienern in den Nether eintreten!\n\nIhr seid eine Zierde Eures Klans, {race}, und Ihr habt mich beschwichtigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26302] = { id = 26302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yennikus Schicksal hinterher", description = "<Nezzliok spricht.>\n\nIhr habt mich und meinen Meister beschwichtigt und ich werde Euch die Informationen geben, nach denen es Euch verlangt...\n\nDer junge Yenniku ist verloren.\n\nEr wurde von Hexendoktor Zanzil dem Ausgestoßenen entführt. Jetzt sind sein Geist und sein Körper in Zanzils Kontrolle und nur die stärkste aller Magien kann ihn davon befreien.\n\nMagie, die Euch nicht zur Verfügung steht, {class}.\n\nVielleicht können Eure Verbündeten der Dunkelspeere in Bambala östlich von einen Hoffnungsschimmer zur Erlösung Yennikus darstellen. Aber das bezweifle ich.", sourceObjective = "Sprecht mit Kin'weelay in Bambala.", completion = "Zanzil der Ausgestoßene??\n\nWenn Yenniku von diesem Troll, einem bösartigen und mächtigen Hexedoktor, gefangen gehalten wird, dann befürchte ich, dass nur das kleinste bisschen Hoffnung übrig bleibt. Das Allerkleinste. So klein wie das kleinste aller Insekten.\n\nIch habe aber auch einen Verdacht. Ein Verdacht, der zu Yennikus Erlösung führen könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[26303] = { id = 26303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gedankenauge", description = "Das Gedankenauge befindet sich bei einem Ogermagier, im Ogerhügel der Mosh'Ogg südlich von hier. Sein Name ist Mai'Zoth. Ich kenne ihn noch von der Zeit, als sich die Dunkelspeere im Schlingendorntal aufhielten - er ist bösartig und seine Magie ist stark.\n\nUnd wenn er im Besitz des Gedankenauges ist, dann ist seine Magie noch stärker.\n\nIhr müsst gegen Mai'Zoth antreten und ihm das Gedankenauge abnehmen. Es ist eine gefährliche Aufgabe, aber es ist die einzige Hoffnung, die wir haben, Yenniku zu retten.", sourceObjective = "Erhaltet das Gedankenauge von Mai'Zoth.", progress = "Seid gegrüßt, {name}. Die Geister lobpreisen Euren Mut, aber sie sagen mir nichts von Eurem Kampf gegen Mai'Zoth.\n\nHabt Ihr das Auge?", completion = "Ihr habt das Auge geholt! Eure Macht ist der Stoff, aus dem Legenden sind, {name}!\n\nUnd da Ihr im Besitz des Auges seid, müsst Ihr Mai'Zoth besiegt und ihn in den Nether geschickt haben. Darum wollten die Geister zuvor nicht von ihm sprechen.\n\nEs ist gut, dass er diese Welt des Fleisches und der Knochen verlassen hat, aber nun, da er im Reich der Geister wandelt... fürchte ich, wird er dort erneut die Macht ergreifen.\n\nAber darum sorge ich mich ein anderes Mal.", sourceObjectiveStatus = "unverified-source-field" }
quests[26304] = { id = 26304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn es Nacht wird im Dschungel", description = "Vor einem Jahr wurde meine Mutter - die Trollfrau, die mich großzog - von den Schädelspaltern Zul'Mamwes gefangen genommen. Jung und eigen wie ich war machte ich mich auf, um sie zu retten, nur um zu sehen, wie sie von einem Dutzend Krieger auf eine riesige brennende Kohlenpfanne zugestoßen wurde. Ich versteckte mich hinter einem Baum und sah zu, wie sie sie packten und.. und..\n\n<Kil'karil senkt seinen Blick.>\n\nWenn es Nacht wird wird das Licht der Kohlenpfannen von den Bäumen reflektiert und hält mich wach. Bitte, {name}... reist nach Süden nach Zul'Mamwe und löscht die Kohlenpfannen.", sourceObjective = "Löscht 8 Kohlenpfannen von Zul'Mamwe in Zul'Mamwe im Nördlichen Schlingendorntal.", completion = "Der Geist meiner Mutter wird heute in Frieden ruhen, {name}.\n\nUnd ich auch.", sourceObjectiveStatus = "unverified-source-field" }
quests[26305] = { id = 26305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yennikus Rettung", description = "Ich habe das Gedankenauge in einen Seelenedelstein umgeformt. Somit hat er zweierlei Zwecke: Erst verwendet Ihr ihn, um Yenniku zu betäuben, und sobald er betäubt ist, legt Ihr den Seelenedelstein auf seinen Kopf, um seine Seele einzufangen.\n\nMeine anfänglichen Vermutungen waren korrekt: die Geister sagen mir, dass Yenniku nicht bei Zanzil dem Ausgestoßenen ist, sondern in den Ruinen von Zul'Mamwe im Südwesten. Kehrt zu Nimboya in Grom'gol zurück, sobald Ihr Yennikus Seele befreit habt.", sourceObjective = "Bringt den gefüllten Seelenedelstein zu Nimboya.", progress = "{name}. Kin'weelay sagte mir, er habe Euch ausgesandt, Yenniku zu finden.\n\nIst es wahr? Habt Ihr ihn?", completion = "Ihr habt es geschafft! Ihr konntet Yenniku vom Willen Zanzils und der Tyrannei der Schädelspalter befreien und so die Mission erfüllen, die ich kurz vorm Scheitern sah.\n\nZanzil ist noch immer eine Bedrohung für das Schlingendornkap, aber zumindest weiß ich jetzt, dass die Seele des Häuptlingssohnes frei ist.\n\nUnser Stamm wird Euren Namen in Liedern ehren, {name}, und wir werden Eure Geschichte in Stein ritzen, so dass sie auf ewig leben wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[26306] = { id = 26306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anfang der Zurückeroberung", description = "Heute fangen wir mit dem ersten Angriff auf das Herz des wilden Blutfratzenstamms an. Zeigt ihnen keine Gnade, {name}. Hier geht es um mehr als Rivalität unter Trollen. Jeder Sieg der Bruchhauer ist ein Sieg für die Horde!\n\nDie Kopfjäger der Blutfratzen und Hexendoktoren müssen zuerst beseitigt werden. Greift die unteren Terrassen an und erstattet mit Blut an Eurer Waffe Bericht bei mir.", sourceObjective = "Tötet 5 Hexendoktoren der Blutfratzen und 5 Kopfjäger der Blutfratzen in Jintha'Alor.", completion = "Gut gemacht, {name}! Lasst die Blutfratzen vor Angst fliehen, die ihnen durch Euren Anblick eingeflößt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[26307] = { id = 26307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod den Blutfratzen", description = "Wir werden ihnen nicht erst die Gelegenheit geben, auf unseren Angriff zu reagieren. Ihr müsst zurück nach Jintha'Alor und Euch den Weg zu den höheren Ebenen freikämpfen.\n\nDie Berserker und Schattenzauberer der Blutfratzen sind gefährliche Gegner, {name}. Wenn die anderen sehen, wie ihre Leichen über die Mauern geworfen werden, so werden sie wissen, WIE ernst wir es meinen.\n\nIch möchte kein Blutfratzenherz mehr schlagen hören!", sourceObjective = "Tötet 5 Berserker der Blutfratzen und 5 Schattenzauberer der Blutfratzen in Jintha'Alor.", completion = "Es wird nicht mehr lange dauern und wir sind die einzigen atmenden Trolle bei diesen Mauern!", sourceObjectiveStatus = "unverified-source-field" }
quests[26308] = { id = 26308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das gehört jetzt uns", description = "Nur die stärksten und bösartigsten Blutfratzen sind übrig geblieben. Die Seelenfresser und Bluttrinker, die verkommenen Anhänger des bösen Gottes Hakkar.\n\nSie sind NARREN! Sie halten an altem, falschem Glauben fest. Ich werde ihre Verbrechen gegenüber den Bruchhauern nicht länger dulden.\n\nMacht Euch zum finalen Angriff auf. Nehmt Jintha'Alor für die Bruchhauer ein... nehmt es für die Horde ein!", sourceObjective = "Tötet 5 Bluttrinker der Blutfratzen und 5 Seelenfresser der Blutfratzen in Jintha'Alor.", completion = "Nun ist niemand mehr übrig, der sich den Bruchhauern in den Weg stellen kann! Um Nachzügler können wir uns problemlos kümmern.\n\nIhr habt meinem Volk eine große Ehre erwiesen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26309] = { id = 26309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Gefäße", description = "Die Trolle der Blutfratzen hier haben früher das verdorbene Blut des Gottes Hakkars getrunken, um Macht zu erlangen. Sie haben es, bevor sie es tranken, in primitiven Kesseln gekocht - dunkle Gefäße voller unheiliger Stärke.\n\nHakkar wurde natürlich vor langer Zeit schon getötet. Doch das Interessante ist... Ich sehe immer noch Kessel, die hier oben blubbern. Bringt mir einige her und dann sehen wir, was sie so zusammenbrauen.", sourceObjective = "Beschafft 5 Gefäße mit besudeltem Blut aus Jintha'Alor.", progress = "Seid vorsichtig in der Nähe der Kessel, {class}. Die Blutfratzen werden nicht kampflos zulassen, dass Ihr ihre Leckereien wegnehmt.", completion = "Erst Spinnen und jetzt das hier. Ich kann das Gift in seinem Blut reichen... Es ist dasselbe wie bei den Huschern, nur stärker.\n\nDie Blutfratzen und Spinnen... Ich sehe da Potential.", sourceObjectiveStatus = "unverified-source-field" }
quests[26310] = { id = 26310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles, was krabbelt", description = "Bevor Ihr dort hoch geht, {class}...\n\nIch kenne ein paar Verkäufer, die sehr interessiert an starken Giften sind. Mir sind die Spinnen in der Gegend natürlich nicht entgangen... sie sind nicht riesig, aber ungefähr so groß wie Euer Hand.\n\nSie haben eine Färbung, die ich noch nie zuvor in der Gegend gesehen habe. Könntet Ihr ein paar sammeln und mir bringen?", sourceObjective = "Sammelt 8 huschende Spinnlinge in Jintha'Alor.", progress = "Wie viele habt Ihr gefunden?", completion = "Oh ja... es war gut von mir, Euch zu beten, mir diese Spinnlinge zu bringen. Sie sind so faszinierend.\n\nKommt her, meine Hübschen. Hier in meine Tasche, so ist es brav.", sourceObjectiveStatus = "unverified-source-field" }
quests[26311] = { id = 26311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbekannte Gewässer", description = "Der Kriegshäuptling plant einen großangelegten Angriff auf das Schattenhochland. Wir hoffen, dass wir uns dort mit den Orcs des Drachenmals verbünden können.\n\nMeine Quellen haben mir berichtet, dass ein Orc des Drachenmalklans hier in Orgrimmar lebt. Er ist als Herezegor Flammenhauer bekannt und führte einst ihre Krieger an.\n\nSein Wissen als einer von ihnen ist für uns von größtem Wert. Findet Flammenhauer und besorgt uns eine Karte der Wasserwege im Schattenhochland.\n\nLaut meinen letzten Informationen hielt er sich in einer Kneipe im Tal der Ehre auf...", sourceObjective = "Findet Herezegor Flammenhauer in der Kneipe \"Zum Wyvernschweif\" im Tal der Ehre in Orgrimmar und besorgt Euch eine Küstenkarte des Schattenhochlands.", progress = "<Sauranok ist überrascht, Euch so bald wiederzusehen.>\n\nAh, {class}, Ihr seid zurück. Was habt Ihr herausgefunden?", completion = "<Sauranok scheint sich nicht für die Karte zu interessieren, während Ihr Eure Geschichte erzählt.>\n\nZwielichtassassinen sind Euch in die Kneipe gefolgt? Hier in Orgrimmar?\n\nDer Kriegshäuptling wird alles andere als erfreut sein, das zu hören.\n\nFahrt mit Euren Vorbereitungen für den Einmarsch fort. Ich versuche, mehr darüber herauszufinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26312] = { id = 26312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bröckelnde Verteidigung", description = "Als der Angriff begann, sind wir nach vorne geprescht, um das Feld so schnell wie möglich einzunehmen. Ihre Streitkräfte waren schier unerschöpflich... wir haben sie unterschätzt. Nun sitzen einige unserer besten Schamanen da draußen fest, gestrandet, erschöpft und weit entfernt von unserer Verteidigung.\n\nBegebt Euch auf das Feld und entlastet unsere gestrandeten Brüder. Selbst eine kleine Pause vom Kampf sollte ihnen die Gelegenheit geben, endlich einmal durchzuatmen.\n\nBeeilt Euch, {class}.", sourceObjective = "Entlastet Tawn Winterfels, Sturmruferin Mylra und Hargoth Trübflamm, indem Ihr ihnen helft, ihre Gegner zu besiegen.", progress = "Vielleicht war es dumm von mir, sie so weit nach vorne zu schicken. Alles, was ich über die Erdelementare weiß, deutete darauf hin, dass solch ein Angriff nicht lange andauern könnte… dass sie nur ihrem Zorn freien Lauf lassen und sich genauso schnell wieder beruhigen.\n\nJetzt weiß ich, dass ich falsch lag.", completion = "Vielen Dank, {class}. Viele Anhänger des Irdenen Rings verdanken Euch heute ihr Leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26313] = { id = 26313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kern unserer Sorgen", description = "Elementare sind von Natur aus chaotisch, doch diese organisierte Aggressivität passt einfach nicht zu ihnen. Besonders hier unten, wo ihr Tod ein bisschen dauerhafter ist. Ich vermute, die Steinmutter Therazane steckt dahinter, aber ich muss Gewissheit haben.\n\nVernichtet die Zornsteinrumpler und bringt mir ihre Kerne. Wenn wir es mit dem Hass der Steinmutter zu tun haben, werden wir die Sache hier und jetzt erledigen.", sourceObjective = "Sammelt 6 Zornsteinkerne.", progress = "Die Elementarlords waren nie unsere Freunde, aber wir haben dennoch auf ein gewisses Maß an Sicherheit in ihrem Chaos vertraut. So lange sie unorganisiert bleiben, haben wir nur wenig zu fürchten.\n\nWenn die Steinmutter jedoch tatsächlich die Erde gegen uns in den Kampf führt, haben wir Einiges zu befürchten.", completion = "Die sind in einem überraschend guten Zustand. Gute Arbeit, Mann.", sourceObjectiveStatus = "unverified-source-field" }
quests[26314] = { id = 26314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fest auf dem Boden", description = "Wir können von Glück sagen, dass diese Riesen so schlecht zielen. Doch irgendwann wird das Glück auf ihrer Seite sein.\n\nWir müssen sie aus dem Kampfgeschehen nehmen, aber ihnen direkt gegenüberzutreten ist wohl keine gute Idee.\n\nNehmt dieses Wurfleine, werft sie ihnen um einen Knöchel und zieht ihnen die Füße weg. Sobald sie am Boden liegen, sollten sie leicht zu besiegen sein.", sourceObjective = "Benutzt die Elementiumwurfleine, um 3 Diener von Therazane von den Füßen zu holen.", completion = "Das wird ihren Angriff ein wenig verlangsamen, bis Norsala einen Weg gefunden hat, sie zu besänftigen. Wir haben kein Bedürfnis, weiter Feinde von Therazane der Steinmutter zu bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26315] = { id = 26315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein imposantes Aufeinandertreffen", description = "Habt Ihr den Riesen gesehen, der bedrohlich im Nordwesten aufragt? Das ist Boden der Imposante, einer der Steinlords von Therazane der Steinmutter.\n\nWir wissen nicht viel über die Steinlords, aber Boden zählt nicht gerade zu den Sanftmütigen seiner Art. Leider führt ausgerechnet er den Angriff an, also müssen wir ihm gegenübertreten.\n\nBringt diese Proklamation zu ihm und lest sie im Namen des Irdenen Rings laut vor. Ich weiß, es ist ganz schön optimistisch zu hoffen, dass Worte dies beilegen können, aber wir müssen es versuchen. Seid vorsichtig.", sourceObjective = "Lest Boden dem Imposanten die Proklamation des Irdenen Rings vor.", progress = "Hattet Ihr schon die Gelegenheit, Boden gegenüberzutreten?", completion = "Ja… genau diese Reaktion hatte ich erwartet.\n\nDoch er hat Diamant erwähnt? Wenn die beiden nicht miteinander auskommen, ist dieser Diamant vielleicht nicht so unbändig wie Boden. Zumindest besteht eine kleine Hoffnung.\n\nMal sehen, ob ich die Erde dazu bringen kann, mir den Aufenthaltsort dieses Diamant zu verraten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26316] = { id = 26316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worauf wartet Jessup?", description = "Der Kataklysmus öffnete tiefe Spalten unter der Höhle der Frostmähnen. Troggs stürmten daraufhin aus ihren Bauten. Es gelang ihnen, die Trolle, die dort lebten, zu verjagen und das gleiche Schicksal blüht uns auch, wenn wir nicht handeln.\n\nHochtüftler Mekkadrill hat den bekannten Demolierer Jessup McCree angeheuert, um die Spalten zu versiegeln und den Ansturm der Troggs zu beenden. Er hat uns noch nicht mitgeteilt, ob es ihm gelungen ist, die Troggs aufzuhalten. Würdet Ihr in seinem Lager nahe der Höhle der Frostmähnen, südlich des Toxischen Flugplatzes nach ihm suchen?", sourceObjective = "Findet Jessup McCree in seinem Lager nahe der Höhle der Frostmähnen.", completion = "Die Tunnel zu sprengen, ist nicht schwer, aber dafür brauche ich mein Team und meine Ausrüstung. Vorher kann ich nicht anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26317] = { id = 26317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schmetterschwanzjunges", description = "Als Ihr das letzte der Schmetterschwanzeier zerstört habt, seht Ihr, wie ein neugeborenes Schmetterschwanzjunges Euch anschaut. Ihr seht, wie es Euch genau betrachtet, Eure Gesichtszüge untersucht und alle Eure Bewegungen aufmerksam verfolgt.\n\nDas Schmetterschwanzjunge hat Euch in sein Herz geschlossen.\n\nEigentlich solltet Ihr die Bevölkerung der Raptoren ausmerzen, aber Ihr habt alle Eier zerstört, die von Euch zerstört werden sollten, und dieser Raptor ist ein unschuldiges Jungtier. Vielleicht weiß jemand im Basislager Grom'gol, was man mit einem Raptorenjungen anfangen kann.", sourceObjective = "Bringt das Schmetterschwanzjunge zu Scharfseher Mok'thardin im Basislager Grom'gol.\n\nBereitgestellter Gegenstand:", completion = "Ja, die Kleine scheint einen Narren an Euch gefressen zu haben. Ich vermute, dass ein einzelner Raptor, noch dazu, wenn er unter Orcs aufwächst, eine viel geringere Gefahr sein wird, als ein ganzes Rudel. Behaltet sie, {name}... vielleicht erweist sie sich noch als nützlich.\n\nUm genau zu sein...", sourceObjectiveStatus = "unverified-source-field" }
quests[26318] = { id = 26318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine unvollendete Aufgabe", description = "Mein Team hat die Pulverfässer und den Zünder bereits am Ende der Höhle im westlichen Teil der Höhle der Frostmähnen angebracht. Ihr müsst nur dorthin vordringen und den Zünder aktivieren, dann explodiert das Pulver und die Tunnel brechen ein.\n\nDann werden die Troggs die Tiefen der Erde nicht mehr verlassen. Mekkadrill wird mit den restlichen Troggs leichter fertigwerden, wenn Ihr ihren Anführer, der sich selbst Boss Bruggor nennt, ausschaltet. Viel Glück, {name}.", sourceObjective = "Dringt zum Ende der Höhle in der Höhle der Frostmähnen vor, tötet Boss Bruggor und aktiviert den Zünder, um die Troggtunnel zum Einsturz zu bringen.", completion = "Ich konnte die Explosion selbst hier oben spüren! Meine Jungs haben die Sprengung gut vorbereitet, aber ohne Eure Hilfe hätte uns das nichts genutzt. Es ist nur gerecht, wenn ich mein Vertragshonorar mit Euch teile. Schließlich habt Ihr unsere Aufgabe vollendet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26319] = { id = 26319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gelöste Geheimnisse", description = "Es gibt hier einen Schamanen, Thoralius, der uns vielleicht helfen kann. Er ist ein Freund von Gryan und ist vor Kurzem nach Westfall gekommen, um die elementare Verwüstung zu untersuchen, die über uns hereingebrochen ist.\n\nSprecht mit Thoralius und seht, ob er etwas Licht auf die Identität dieser merkwürdigen Gestalt werfen kann.", sourceObjective = "Sprecht mit Thoralius dem Weisen in Mondbruch in Westfall.", completion = "Hmm, ja, vielleicht kann ich Euch helfen. Als ich in Nordend war, habe ich den Einwohnern von Valgarde dabei geholfen, einige der Geheimnisse der Vrykul aufzudecken, indem ich in die Geisterwelt eingetaucht bin. Vielleicht kann ich dasselbe auch hier tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[26320] = { id = 26320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Vision aus der Vergangenheit", description = "Dieser Weihrauch wird Euren Körper und Euren Geist in tiefe Meditation versetzen. Sobald die Trance beginnt, werdet Ihr in die Geisterwelt übertreten. Wehrt Euch nicht gegen die Trance, sobald sie begonnen hat, {name}. Erlaubt den Geistern, Euch zu zeigen, was sie wissen.\n\nIhr müsst nun aufbrechen. Begebt Euch zu den Todesminen, ein Ort, der angeblich eine große Rolle in der Geschichte Westfalls gespielt hat. Sobald Ihr im Inneren seid, benutzt den Weihrauch.\n\nIhr gelangt durch das alte Bauernhaus südlich von hier in die Todesminen. Folgt den Obdachlosen.\n\nKehrt zu Gryan zurück und berichtet ihm von dem, was Ihr erfahren habt.", sourceObjective = "Betretet das Versteck der Defias und folgt der Spur der Obdachlosen in die Todesminen. Betretet den Dungeon \"Die Todesminen\" und benutzt das Räuchergefäß, um in die Vergangenheit zu blicken.", completion = "WAS? Van Cleef hatte eine Tochter?", sourceObjectiveStatus = "unverified-source-field" }
quests[26321] = { id = 26321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich glaube, sie hat Hunger", description = "Ich glaube, Euer Raptorenjunges ist hungrig. Wenn Ihr sie behalten wollt, solltet Ihr Essen für sie finden, nicht wahr? Schmetterschwänze greifen oft das Lager der Düsterkiemen nördlich von hier an.\n\nSie ist wahrscheinlich noch nicht stark genug, um selbst zu jagen, aber frisches Murlocfleisch kann sie sicher schon essen.", sourceObjective = "Tötet Murlocs der Düsterkiemen im Nördlichen Schlingendorntal und gebt Eurem Schmetterschwanz 40 Bissen Murlocfleisch.", completion = "Sie sieht schon ein bisschen größer aus! Ihr müsst wissen, dass Raptoren schnell wachsen. Ihr habt Glück, so einen starken Begleiter gefunden zu haben.\n\nBehaltet sie, so lange Ihr könnt, {name}. Sie wird sich sicherlich bald als sehr wertvoll für Euch erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26322] = { id = 26322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg der Bruderschaft", description = "Ich hatte ja keine Ahnung, dass van Cleef eine Tochter hatte, {name}. Wenn es etwas gab, in dem der Mann außerordentlich gut war, dann war es, Geheimnisse zu bewahren.\n\nWie tragisch. Das arme Ding hat eine schreckliche Tat mit angesehen. Hätte ich doch nur etwas geahnt.\n\nWas war das? Habt Ihr etwas gehört? Scheint so, als ziehen sich die Gnolle zurück... wo sind meine Wachen?\n\nPASST AUF, {name}!", sourceObjective = "Werdet Zeuge des Aufstiegs der Bruderschaft.", completion = "Ich werde sofort ein Bataillon nach Westfall entsenden! Nun da die Bruderschaft der Defias neu gegründet worden ist, ist eine alte Bedrohung für das Königreich wiederauferstanden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26323] = { id = 26323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieblingsschädel", description = "Euer Raptor scheint ein neues Spielzeug gefunden zu haben: einen Schädel aus einem Haufen von Trollschädeln.\n\nIhr wisst nicht, warum sie diesen Schädel allen anderen bevorzugt, aber aus irgendeinem Grund lässt sie nicht von ihm ab.\n\nNimboya im Basislager Grom'gol ist eine Art Schädelexperte, wenn man von dem Schädelhaufen ausgeht, den er hat. Vielleicht weiß er, was an diesem Schädel so besonders ist.", sourceObjective = "Kehrt zu Nimboya im Basislager Grom'gol zurück und zeigt ihm den Lieblingsschädel von Eurem Schmetterschwanzjungen.\n\nBereitgestellter Gegenstand:", completion = "Was haben wir hier? Ein Schmetterschwanzjunges und ihren Goblinbegleiter.Hah!\n\nUnd weitaus wichtiger, was für einen Schädel habt Ihr da? Das war kein normaler Troll. Es war ein sehr großer Troll...\n\n<Nimboya klopft auf die Schädeldecke.>\n\n... und ein sehr starker. Mal sehen, was wir damit machen können.\n\nGeht nicht weg.", sourceObjectiveStatus = "unverified-source-field" }
quests[26324] = { id = 26324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ist meine Kriegsflotte?", description = "Wir haben eine Karte von den Zugängen zum Schattenhochland. Unser Plan ist eindeutig: Wir werden uns mit unserer kompletten Streitmacht zeigen. Wenn die Orcs des Drachenmals unsere ganzen Truppen an ihrem Strand sehen, haben sie keine Wahl, außer sich mit uns zu verbünden und uns bei unserem Kreuzzug gegen den Schattenhammer zu unterstützen.\n\nDie Flotte wird im Bilgepier in Azshara zusammengebaut, doch sie kommen für meinen Geschmack viel zu langsam voran.\n\n{class}! Ihr seid geschickt darin, die Räder an meinen Kriegsmaschinen zu ölen. Sucht nach Kriegsfürst Krogg in Azshara und findet heraus, was da so lange dauert.", sourceObjective = "Sprecht mit Kriegsfürst Krogg am Bilgepier in Azshara.", completion = "Was? Noch eine Nachricht von Höllschrei? Sein Geduldsfaden ist dünner als Elfenhaar.\n\nHabt Ihr je mit Goblins zusammengearbeitet? Überall sind weitere versteckte Kosten. Unsere Schiffe liegen halb zusammengebaut im Hafen und unsere Luftflotte ist in alle Winde zerstreut.\n\nWenn diese Invasion tatsächlich stattfinden soll, brauche ich Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[26325] = { id = 26325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gespür für solche Dinge", description = "<Der Schädel spricht zu Euch.>\n\nIch lebe? Nein, ich lebe nicht... aber ich kann leben.\n\nEuer Raptor ist sehr schlau, wenn er meinen Schädel in einem Haufen so vieler Schädel gefunden hat. Zu Lebzeiten war ich ein starker, mächtiger Troll, ein Fürst unter den Trollen. Mit Eurer Hilfe kann ich wieder ein Fürst sein.\n\nDie Blutskalpe in Zuuldaia haben magische Fetische, die mir zur Rückkehr verhelfen können. Sie verstecken die Artefakte unter dem Sand. Euer Schmetterschwanzjunges wird diese Artefakte finden können, {name}... wenn Ihr sie habt, werft sie in den Kessel.", sourceObjective = "Lasst Euer Schmetterschwanzjunges 8 Fetische von Zuuldaia aufspüren.", progress = "<Der große Trollschädel taucht aus dem brodelnden Kessel auf.>\n\nWie viele konntet Ihr finden?", completion = "<Ihr fügt die Fetische dem Kessel hinzu.>\n\nJa... jaaaaa...\n\nMein Geist ist wieder stark, {name}, und ich bin bereit, in die Welt zurückzukehren. Jetzt brauche ich einen Körper.", sourceObjectiveStatus = "unverified-source-field" }
quests[26326] = { id = 26326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erde unter unseren Füßen", description = "Nur noch ein Teil der Weltensäule fehlt, und der befindet sich in den Händen der Steinmutter selbst. Schlimmer noch, der Tempel wird von Elementaren und Riesen belagert. Selbst einem Narr dürfte klar sein, dass sie auf ihren Befehl hin handeln.\n\nGeht und stellt Euch den Elementaren im Nordwesten im Kampf. Beratet Euch mit Torunskar und Norsala und findet einen Weg, um mit ihren Anführern zu sprechen und die Weltensäule zu finden. Wir ziehen eine friedliche Beilegung vor, aber wir werden alles tun, was nötig ist, um den Riss zu schließen.", sourceObjective = "Sucht nach Erdenrufer Torunskar direkt nordwestlich des Tempels der Erde in der Zackenwüste.", completion = "Hey, Mann! Vielen Dank für Euer Kommen.\n\nWir waren auf diese Art von Angriff nicht vorbereitet. Wir haben den Schattenhammerkult erwartet, aber nicht die Elementare. Ich habe keine Ahnung, was sie so sehr in Aufruhr versetzt hat, dass sie sich plötzlich gegen uns wenden.\n\nIhr habt doch keine von ihnen getötet, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[26327] = { id = 26327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ambossar der Held", description = "Ihr verschwendet nur Eure Zeit, wenn Ihr jetzt mit mir reden wollt, <Junge/Mädchen>. Thargas Ambossar hält sich auf der anderen Seite dieser Wagen auf.\n\nIhr habt von ihm gehört, oder? Er hat an der Seite des Königs von Sturmwind den Thandolübergang gegen die Dunkeleisenzwerge verteidigt! Er ist einer der größten Helden von Eisenschmiede.\n\nAber jetzt steckt er bis zum Hals in Ärger! Geht zu ihm und lasst ihn wissen, dass Ihr helfen wollt. Aber haltet Abstand; er holt weit aus.", sourceObjective = "Redet mit Thargas Ambossar.", completion = "Seid gegrüßt! Wenn Ihr eine Waffe habt, könnt Ihr mir gern helfen, diese verrückten Narren loszuwerden!", sourceObjectiveStatus = "unverified-source-field" }
quests[26328] = { id = 26328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steinige Beziehungen", description = "<Norsala legt die Hand auf den Boden, um Diamants Aufenthaltsort herauszufinden, springt jedoch sofort schockiert zurück.>\n\nMeine Güte! Das habe ich nicht erwartet. Diamant ist gar nicht weit entfernt. Als ich eine Verbindung zu ihm aufbaute, hat er geantwortet und mir gesagt, wo wir ihn finden können. Geht zum nordöstlichen Rand der Zackenwüste. Diamant erwartet Euch.\n\n{name}, seid vorsichtig. Es sieht Erdgeschöpfen zwar nicht ähnlich, einen Hinterhalt zu planen, aber es sah ihnen auch nicht ähnlich, den Tempel überhaupt zu belagern.", sourceObjective = "Findet Diamant den Geduldigen am nordöstlichen Rand der Zackenwüste.", completion = "Ah… Ihr müsst der {class} sein, den ich erwarte.\n\nAlso kommt Ihr im Namen des Irdenen Rings?", sourceObjectiveStatus = "unverified-source-field" }
quests[26329] = { id = 26329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und noch etwas", description = "So, dann werde ich meine Sachen packen und mich der nächsten Aufgabe widmen. Irgendwo gibt es immer etwas zu sprengen. Irgendwo gibt es einen Berg, der bewegt werden muss oder eine Schlucht, die gegraben werden muss. Dafür bin ich da.\n\nWürdet Ihr mir vielleicht noch einen Gefallen erweisen? Würdet Ihr diesen Bericht zu Hochtüftler Mekkadrill in Neu-Tüftlerstadt bringen? Er sollte wissen, dass die Troggs seinem Volk in nächster Zeit keine Probleme mehr machen werden.", sourceObjective = "Bringt Jessups Bericht zu Hochtüftler Mekkadrill in Neu-Tüftlerstadt.", progress = "Willkommen zurück, {name}.", completion = "<Der Hochtüftler liest Jessups Bericht.>\n\nGroßartige Neuigkeiten! Ohne die Troggs können wir unsere Aufmerksamkeit endlich dem Ärger widmen, den Ritzelstoß veranstaltet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26330] = { id = 26330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer ist ein großer Troll?", description = "<Der Schädel spricht erneut.>\n\nMeine Seele ist bereit, doch mein Körper ist es nicht. Die Blutskalpe haben meinen alten Körper vor langer Zeit entweiht. Die Schrecken, die sie mir zugefügt haben... mein Geist sah dabei zu, als sie meinen Körper in Stücke rissen und... und... ich kann es nicht erzählen.\n\nIhr Häuptling, Gan'zulah, leitete diese grauenvollen Taten. Wenn ich mich recht erinnere, so war er ein starker, mächtiger Troll... ungefähr so groß wie ich. Was für ein interessanter Zufall.\n\nIhr wisst, was Ihr zu tun habt, {name}. Beeilt Euch.", sourceObjective = "Holt Gan'zulahs Leiche aus Zul'Kunda.", progress = "<Ihr hört die Stimme des Schädels:>\n\nGan'zulah...", completion = "Ihr habt Gutes getan, {name}. Es gilt nur noch eine Aufgabe zu erfüllen, bevor ich zurückkehren kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[26331] = { id = 26331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritzelstoß' Handlanger", description = "Unser alter Feind Thermadraht versucht uns mit allen Mitteln vom Wiederaufbau und der Rückeroberung Gnomeregans abzuhalten. Er hat einen seiner loyalsten Schergen, Razlo Ritzelstoß und einen Trupp bestrahlter Gnome ausgesandt, um uns zu terrorisieren.\n\nSie haben sich in einem alten Arsenal auf der Straße nach Norden verschanzt. Ritzelstoß' Techniker reparieren die Waffen dort. Wir müssen sie aufhalten, bevor die Mechanopanzer einsatzbereit sind. Geht zu Ritzelstoß' Arsenal und eliminiert alle Techniker, die Ihr findet.", sourceObjective = "Tötet 8 von Ritzelstoß' Handlangern in Ritzelstoß' Arsenal. Ihr könnt wahlweise bestrahlte Techniker oder Ritzelstoß' Kampfanzüge töten.", completion = "Das sollte Ritzelstoß ein wenig aufhalten, aber wir dürfen nicht ruhen, bevor er besiegt und das Frosthauchtal sicher ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[26332] = { id = 26332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mojo der Schädelspalter", description = "<Der Schädel spricht wieder.>\n\nDank Euch und Eurem Raptor habe ich meinen Körper. Wenn ich mich recht erinnere, so braucht Ihr und Euer Freund, der Hexendoktor, Mojo, um das Ritual abzuschließen.\n\nDie Blutskalpe haben Mojo in Zul'Kunda, aber es ist schwach. Das Mojo der Dunkelspeere wird auch nicht ausreichen. Nein... wir brauchen das Mojo der Schädelspalter. Ihr könnt sie auf der anderen Seite des Flusses östlich von hier finden.\n\nBeeilt Euch, {race}. Ich werde Euch zusehen...", sourceObjective = "Erhaltet 6 Mojos der Schädelspalter von Trollen der Schädelspalter in den Ruinen von Ziata'jai und den Ruinen von Balia'mah.", progress = "<Der große Trollschädel treibt im Kessel umher.>", completion = "<Ihr fügt das Mojo dem Kessel hinzu.>\n\nAusgezeichnete Arbeit, {race}. Ihr und Euer Raptor haben eine große Tat vollbracht. Hakkar wäre sehr erfreut...", sourceObjectiveStatus = "unverified-source-field" }
